//! Consume corrected-chamber GV context exports.
//!
//! This is an opt-in diagnostic binary for the JSON written by
//! `mcallister_first_principles --dump-corrected-chamber-gv-context`. It does
//! not read McAllister downstream GV rows. Its job is to validate the
//! CYTools/cygv-shaped context and, when requested, run small explicit
//! semigroup HKTY checks for missing targets whose exact active-generator
//! decomposition is an integer semigroup.

use malachite::{Integer, Rational as MalachiteRational};
use nalgebra::{DMatrix, RowDVector};
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};
use std::path::PathBuf;

use cyrus_core::geometry::ConvexHull;
use cyrus_core::gv::{
    CygvGvCoefficientTrace, SupportingMoriFaceLpSearchOptions,
    certify_supporting_mori_face_by_exact_kernel, certify_supporting_mori_face_by_lp_search,
    cygv_pair_reduced_seed_generators, diagnose_extremal_mori_ray_separator_by_lp_search,
    diagnose_supporting_mori_face_by_lp_search, find_extremal_mori_ray_separator,
};
use cyrus_core::triangulation::{
    CircuitOmissionSide, Triangulation, circuit_triangulation_choices,
    classify_circuit_omission_side, complete_circuit_flip_links, compute_regular_triangulation,
    expanded_secondary_face_inequality_choices_from_circuit_faces, flip_circuit_in_triangulation,
    flip_circuit_link_in_triangulation, secondary_cone_height_pairings,
    secondary_cone_hyperplanes_native, secondary_cone_strictly_contains_height_vector,
};
use cyrus_core::types::rational::Rational;
use cyrus_core::types::{f64::F64, tags::Finite, tags::Pos};
use cyrus_core::{
    CkyzLocalSurfaceKind, CygvQnTracePolynomial, GvDilogFailure, Intersection,
    LocalToricCircuitKind, Point, certify_nef_partition_cytools_style,
    check_stable_weyl_candidate_certificate, ckyz_local_surface_target_degrees,
    compute_ckyz_local_surface_gv_invariants_for_multiples_with_causal_domain,
    compute_gv_invariants_with_explicit_semigroup,
    compute_gv_invariants_with_explicit_semigroup_qn_trace,
    compute_gv_invariants_with_provided_generators,
    compute_gv_invariants_with_provided_generators_qn_trace,
    compute_gw_coefficient_trace_with_explicit_semigroup,
    compute_gw_coefficient_trace_with_provided_generators, curve_row_span_rank,
    diagnose_affine_toric_circuit, divisor_quadratic_vanishes_on_curve_facet,
    gv_dilog_from_curve_volume_checked, identify_ckyz_local_surface,
    integer_math::{integer_kernel, solve_linear_system_rational},
    rank_two_local_charge_model, rank_two_local_support_signature,
    utils::gcd_list_int,
    weyl_reflection_matches_flop_transform,
};

const CYGV_PATH_PREDECESSOR_SAMPLE_LIMIT: usize = 32;
const CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT: usize = 32;
const CYGV_PATH_SUPPORT_QN_TRACE_SAMPLE_LIMIT: usize = 16;
const CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT: usize = 16;
const CYGV_PATH_SUPPORT_GV_COEFFICIENT_TRACE_SAMPLE_LIMIT: usize = 32;
const CYGV_PATH_SUPPORT_TARGET_MONOMIAL_QN_SOURCE_SAMPLE_LIMIT: usize = 16;
const DEFAULT_CYGV_LOWER_SEED_PAIR_LIMIT: usize = 1024;
const CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT: usize = 64;
const CYGV_BOUNDED_DIAMOND_PARENT_QN_DIFF_SAMPLE_LIMIT: usize = 16;
const ORIGIN_CIRCUIT_WITNESS_DOMAIN_UNRESOLVED_SAMPLE_LIMIT: usize = 64;
const ORIGIN_CIRCUIT_WITNESS_DOMAIN_OCCURRENCE_SAMPLE_LIMIT: usize = 8;
const ORIGIN_CIRCUIT_WITNESS_DOMAIN_SPAN_CLOSURE_SAMPLE_LIMIT: usize = 16;
const CHAMBER_GENERATOR_SUPPORT_OVERLAP_SAMPLE_LIMIT: usize = 5;

#[derive(Debug, Deserialize)]
struct CorrectedChamberGvContext {
    schema_version: u32,
    ambient_rays: usize,
    toric_gv_missing_count: usize,
    remaining_gv_missing_count: usize,
    basis_mori_ray_count: Option<usize>,
    basis_mori_rays_for_missing_degree_bound: Option<i128>,
    basis_mori_rays_for_missing_degree_bounded: Option<Vec<Vec<i64>>>,
    degree_bounded_mori_ray_context_for_missing: Option<Vec<DegreeBoundedMoriRayContextSample>>,
    covered_toric_gv_context_for_missing: Option<Vec<CoveredToricGvContextSample>>,
    #[serde(default)]
    uncovered_source_ray_toric_diagnostic_sample: Option<Vec<ToricGvDiagnosticContextSample>>,
    #[serde(default)]
    degree_bounded_toric_gv_diagnostic_context_for_missing:
        Option<Vec<ToricGvDiagnosticContextSample>>,
    #[serde(default)]
    secondary_cone_height_certificate: Option<SecondaryConeHeightCertificate>,
    #[serde(default)]
    secondary_cone_2face_height_certificate: Option<SecondaryConeHeightCertificate>,
    #[serde(default)]
    expanded_secondary_fan_height_certificate: Option<SecondaryConeHeightCertificate>,
    #[serde(default)]
    secondary_cone_heights_for_missing: Option<Vec<f64>>,
    #[serde(default)]
    corrected_chamber_face_triangulation_choice_summary: Option<FaceTriangulationChoiceSummary>,
    #[serde(default)]
    induced_face_triangulation_chamber_certificate:
        Option<InducedFaceTriangulationChamberCertificate>,
    uncovered_source_ray_stats_for_missing: Option<MissingGvTargetStats>,
    #[serde(default)]
    shared_facet_unresolved_source_ray_stats_for_missing: Option<MissingGvTargetStats>,
    gv_q_matrix_for_missing: Option<Vec<Vec<i64>>>,
    grading_for_missing: Option<Vec<i64>>,
    corrected_kappa_basis_for_missing: Option<Vec<SparseIntersectionEntry>>,
    missing_target_stats: Option<MissingGvTargetStats>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct SecondaryConeHeightCertificate {
    status: String,
    epsilon: f64,
    hyperplane_count: usize,
    pairing_count: usize,
    min_pairing: Option<f64>,
    max_pairing: Option<f64>,
    strictly_inside: bool,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct FaceTriangulationChoiceSummary {
    status: String,
    max_exact_face_points: usize,
    samples_per_large_face: usize,
    max_sampling_attempts_per_face: usize,
    seed: u64,
    face_count: usize,
    exact_face_count: usize,
    sampled_face_count: usize,
    empty_choice_face_count: usize,
    min_face_points: Option<usize>,
    max_face_points: Option<usize>,
    min_choice_count: Option<usize>,
    max_choice_count: Option<usize>,
    total_choice_count: String,
    face_point_counts: Vec<usize>,
    choice_counts: Vec<usize>,
    sampled_face_indices: Vec<usize>,
    sampled_face_point_counts: Vec<usize>,
    height_compatible_choice_indices: Option<Vec<Vec<usize>>>,
    height_compatible_choice_counts: Option<Vec<usize>>,
    height_unique_compatible_face_count: Option<usize>,
    height_no_compatible_face_count: Option<usize>,
    height_multi_compatible_face_count: Option<usize>,
    height_first_no_compatible_face_index: Option<usize>,
    height_unique_choice_digits: Option<Vec<usize>>,
    height_unique_choice_index: Option<String>,
    #[serde(default)]
    height_unique_selected_chamber_certificate: Option<SecondaryConeHeightCertificate>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct InducedFaceTriangulationChamberCertificate {
    status: String,
    face_count: usize,
    min_face_point_count: Option<usize>,
    max_face_point_count: Option<usize>,
    min_face_simplex_count: Option<usize>,
    max_face_simplex_count: Option<usize>,
    total_face_simplex_count: usize,
    face_point_counts: Vec<usize>,
    face_simplex_counts: Vec<usize>,
    height_certificate: SecondaryConeHeightCertificate,
}

#[derive(Debug, Deserialize)]
struct SparseIntersectionEntry {
    indices: [usize; 3],
    value: String,
}

#[derive(Debug, Deserialize)]
struct DegreeBoundedMoriRayContextSample {
    degree: i128,
    ambient_nonzero: Vec<(usize, i64)>,
    basis_nonzero: Vec<(usize, i64)>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct CoveredToricGvContextSample {
    degree: i128,
    gv: String,
    ambient_nonzero: Vec<(usize, i64)>,
    basis_nonzero: Vec<(usize, i64)>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct ToricGvDiagnosticContextSample {
    degree: i128,
    gv: String,
    source_bucket: String,
    source_summary: String,
    ambient_nonzero: Vec<(usize, i64)>,
    basis_nonzero: Vec<(usize, i64)>,
}

#[derive(Debug, Deserialize)]
struct MissingGvTargetStats {
    target_count: usize,
    real_cone_decomposition_exact_kind_counts: HashMap<String, usize>,
    sample: Vec<MissingGvTargetSample>,
}

#[derive(Debug, Deserialize)]
struct MissingGvTargetSample {
    degree: i128,
    generators_le_degree: usize,
    is_mori_generator: bool,
    origin_circuit_pattern: Option<String>,
    origin_circuit_witness_count: Option<usize>,
    origin_circuit_first_witness: Option<OriginCircuitWitnessSample>,
    #[serde(default)]
    origin_circuit_witnesses: Option<Vec<OriginCircuitWitnessSample>>,
    origin_circuit_affine_support: Option<OriginCircuitAffineSupportSample>,
    cms_general_divisor_shape_candidates: Option<Vec<CmsGeneralDivisorShapeCandidate>>,
    cms_general_divisor_intersection_checks: Option<Vec<CmsGeneralDivisorIntersectionCheck>>,
    branch_diagnostic: Option<MissingGvBranchDiagnostic>,
    real_cone_decomposable_by_other_generators: bool,
    real_cone_decomposition_active_generators: Option<usize>,
    real_cone_decomposition_active_generator_basis_nonzero: Option<Vec<Vec<(usize, i64)>>>,
    real_cone_decomposition_exact_coefficients: Option<Vec<String>>,
    real_cone_decomposition_exact_kind: Option<String>,
    ambient_nonzero: Vec<(usize, i64)>,
    basis_nonzero: Vec<(usize, i64)>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct MissingGvBranchDiagnostic {
    q_dot_t: String,
    parity: i128,
    parity_mod2: i128,
    q_dot_bucket: String,
    dilog_status: String,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct OriginCircuitAffineSupportSample {
    affine_rank: usize,
    coefficient_counts: BTreeMap<i64, usize>,
    local_charge_basis: Vec<Vec<i64>>,
    #[serde(default)]
    local_coordinates: Vec<OriginCircuitLocalCoordinateSample>,
    local_coordinates_2d: Option<Vec<OriginCircuitLocalCoordinate2DSample>>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct OriginCircuitLocalCoordinateSample {
    point_index: usize,
    coordinates: Vec<i64>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct OriginCircuitLocalCoordinate2DSample {
    point_index: usize,
    coordinates: [i64; 2],
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct CmsGeneralDivisorShapeCandidate {
    shrinking_divisor_index: usize,
    shrinking_divisor_coefficient: i64,
    shrinking_divisor_coordinates: Vec<i64>,
    inferred_other_normal_degree: i64,
    toric_gv1_formula_value: Option<i64>,
    all_non_origin_relation_points_are_two_face: bool,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct CmsGeneralDivisorIntersectionCheck {
    shrinking_divisor_index: usize,
    has_rational_divisor_solution: bool,
    #[serde(default)]
    linear_system: Option<CmsGeneralDivisorLinearSystemDiagnostic>,
    solution_basis_support_len: Option<usize>,
    #[serde(default)]
    solution_basis_nonzero: Option<Vec<(usize, String)>>,
    #[serde(default)]
    solution_ambient_basis_nonzero: Option<Vec<(usize, String)>>,
    solution_is_integral: Option<bool>,
    computed_other_normal_degree: Option<String>,
    matches_inferred_other_normal_degree: Option<bool>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct CmsGeneralDivisorLinearSystemDiagnostic {
    row_count: usize,
    column_count: usize,
    rank: usize,
    augmented_rank: usize,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct OriginCircuitWitnessSample {
    first_facet_exclusive_point: usize,
    second_facet_exclusive_point: usize,
    shared_two_simplex: Vec<usize>,
    #[serde(default)]
    shared_two_simplex_points: Vec<OriginCircuitRelationPointSample>,
    #[serde(default)]
    shared_two_simplex_star_simplices: Vec<Vec<usize>>,
    #[serde(default)]
    shared_two_simplex_star_extra_point_samples: Vec<Vec<OriginCircuitRelationPointSample>>,
    #[serde(default)]
    first_facet: Vec<usize>,
    #[serde(default)]
    second_facet: Vec<usize>,
    first_facet_size: usize,
    second_facet_size: usize,
    sparse_relation: Vec<(usize, i64)>,
    relation_points: Vec<OriginCircuitRelationPointSample>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct OriginCircuitRelationPointSample {
    point_index: usize,
    coefficient: i64,
    coordinates: Vec<i64>,
    face_dimension: Option<usize>,
}

