fn residual_path_support_generator_probe(
    residual: Option<&CygvClosestKnownQnPredecessor>,
    context: &ValidatedContext<'_>,
    run_path_support_generators: bool,
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
) -> Result<Option<PathSupportGeneratorProbe>, String> {
    let Some(residual) = residual else {
        return Ok(None);
    };
    let predecessor = dense_from_sparse(&residual.predecessor_nonzero, context.dimension)?;
    let difference = dense_from_sparse(&residual.difference_nonzero, context.dimension)?;
    let residual_target = checked_vector_sum(&predecessor, &difference)?;
    let residual_degree = curve_degree(&residual_target, context.grading)?;
    let candidate = CygvPathPredecessorCandidate {
        predecessor_degree: residual.predecessor_degree,
        difference_degree: residual.difference_degree,
        series_distance: residual.series_distance.clone(),
        predecessor_toric_gv: residual.predecessor_toric_gv.clone(),
        difference_toric_gv: residual.difference_toric_gv.clone(),
        predecessor_source_derived_gv: residual.predecessor_source_derived_gv.clone(),
        difference_source_derived_gv: residual.difference_source_derived_gv.clone(),
        predecessor_known_qn_history_status: residual.predecessor_known_qn_history_status.clone(),
        difference_known_qn_history_status: residual.difference_known_qn_history_status.clone(),
        known_qn_history_pair_status: known_qn_history_pair_status(
            &residual.predecessor_known_qn_history_status,
            &residual.difference_known_qn_history_status,
        ),
        compact_qn_polynomial_pair_status: compact_qn_polynomial_pair_status(
            &residual.predecessor_known_qn_history_status,
            &residual.difference_known_qn_history_status,
        ),
        predecessor_is_seed: seed_set.contains(&predecessor),
        difference_is_seed: seed_set.contains(&difference),
        predecessor_is_reduced_seed: reduced_seed_set.contains(&predecessor),
        difference_is_reduced_seed: reduced_seed_set.contains(&difference),
        predecessor_first_generation_seed_sum: first_generation_seed_sum_decomposition(
            &predecessor,
            context.grading,
            seed_set,
            reduced_seed_set,
            &context.covered_toric_gv_by_basis,
            &context.source_derived_gv_by_basis,
        )?,
        difference_first_generation_seed_sum: first_generation_seed_sum_decomposition(
            &difference,
            context.grading,
            seed_set,
            reduced_seed_set,
            &context.covered_toric_gv_by_basis,
            &context.source_derived_gv_by_basis,
        )?,
        candidate_pair_diamond: None,
        predecessor_nonzero: residual.predecessor_nonzero.clone(),
        difference_nonzero: residual.difference_nonzero.clone(),
    };
    Ok(Some(path_support_generator_probe(
        &residual_target,
        residual_degree,
        &[candidate],
        context,
        run_path_support_generators,
        None,
    )))
}

fn residual_qn_domain_comparison(
    residual: Option<&CygvClosestKnownQnPredecessor>,
    parent_probe: &PathSupportGeneratorProbe,
    residual_probe: Option<&PathSupportGeneratorProbe>,
    context: &ValidatedContext<'_>,
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
) -> Result<Option<CygvResidualQnDomainComparison>, String> {
    let Some(residual) = residual else {
        return Ok(None);
    };
    let predecessor = dense_from_sparse(&residual.predecessor_nonzero, context.dimension)?;
    let difference = dense_from_sparse(&residual.difference_nonzero, context.dimension)?;
    let residual_target = checked_vector_sum(&predecessor, &difference)?;
    let mut comparison = residual_qn_domain_comparison_for_curve(
        sparse_from_dense(&residual_target),
        parent_probe,
        residual_probe,
    );
    let parent_only_classifications = residual_parent_only_qn_term_classifications(
        &comparison,
        parent_probe,
        context,
        seed_set,
        reduced_seed_set,
    )?;
    comparison.parent_only_term_source_status_counts =
        parent_only_qn_term_source_status_counts(&parent_only_classifications);
    comparison.parent_only_term_parent_path_support_qn_trace_status_counts = optional_status_counts(
        parent_only_classifications.iter().map(|classification| {
            classification
                .parent_path_support_qn_trace_status
                .as_deref()
        }),
        "missing_parent_path_support_qn_trace_status",
    );
    comparison.parent_only_term_parent_path_support_qn_polynomial_shape_status_counts =
        optional_status_counts(
            parent_only_classifications.iter().map(|classification| {
                classification
                    .parent_path_support_qn_polynomial_shape_status
                    .as_deref()
            }),
            "missing_parent_path_support_qn_polynomial_shape_status",
        );
    comparison.parent_only_term_parent_path_support_gv_coefficient_status_counts =
        optional_status_counts(
            parent_only_classifications.iter().map(|classification| {
                classification
                    .parent_path_support_gv_coefficient_status
                    .as_deref()
            }),
            "missing_parent_path_support_gv_coefficient_status",
        );
    comparison.parent_only_term_classification_sample = parent_only_classifications;
    Ok(Some(comparison))
}

fn residual_qn_domain_comparison_for_curve(
    residual_nonzero: Vec<(usize, i64)>,
    parent_probe: &PathSupportGeneratorProbe,
    residual_probe: Option<&PathSupportGeneratorProbe>,
) -> CygvResidualQnDomainComparison {
    let parent_qn = qn_trace_sample_for_curve(parent_probe, &residual_nonzero);
    let residual_qn =
        residual_probe.and_then(|probe| qn_trace_sample_for_curve(probe, &residual_nonzero));
    let parent_path_support_qn_term_count = parent_qn.map(|sample| sample.term_count);
    let residual_subtarget_qn_term_count = residual_qn.map(|sample| sample.term_count);
    let parent_path_support_sample_complete = qn_trace_sample_is_complete(parent_qn);
    let residual_subtarget_sample_complete = qn_trace_sample_is_complete(residual_qn);
    let parent_path_support_term_signatures = qn_trace_term_signatures(parent_qn);
    let residual_subtarget_term_signatures = qn_trace_term_signatures(residual_qn);
    let term_signature_comparison_status = qn_domain_comparison_status(
        parent_qn,
        residual_qn,
        parent_path_support_sample_complete,
        residual_subtarget_sample_complete,
        &parent_path_support_term_signatures,
        &residual_subtarget_term_signatures,
    );

    CygvResidualQnDomainComparison {
        residual_nonzero,
        parent_path_support_qn_term_count,
        residual_subtarget_qn_term_count,
        parent_path_support_sample_complete,
        residual_subtarget_sample_complete,
        term_signature_comparison_status,
        parent_path_support_term_signatures,
        residual_subtarget_term_signatures,
        parent_only_term_source_status_counts: BTreeMap::new(),
        parent_only_term_parent_path_support_qn_trace_status_counts: BTreeMap::new(),
        parent_only_term_parent_path_support_qn_polynomial_shape_status_counts: BTreeMap::new(),
        parent_only_term_parent_path_support_gv_coefficient_status_counts: BTreeMap::new(),
        parent_only_term_classification_sample: Vec::new(),
    }
}

fn residual_parent_only_qn_term_classifications(
    comparison: &CygvResidualQnDomainComparison,
    parent_probe: &PathSupportGeneratorProbe,
    context: &ValidatedContext<'_>,
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
) -> Result<Vec<CygvResidualQnDomainTermClassification>, String> {
    let residual_dense = dense_from_sparse(&comparison.residual_nonzero, context.dimension)?;
    comparison
        .parent_path_support_term_signatures
        .iter()
        .filter(|term| {
            !comparison
                .residual_subtarget_term_signatures
                .contains(*term)
        })
        .map(|term| {
            let curve = dense_from_sparse(&term.exponent_nonzero, context.dimension)?;
            let degree = curve_degree(&curve, context.grading)?;
            let offset = checked_vector_difference(&curve, &residual_dense)?;
            let offset_from_residual_degree = curve_degree(&offset, context.grading)?;
            let offset_toric_gv = context.covered_toric_gv_by_basis.get(&offset).cloned();
            let offset_source_derived_gv = context.source_derived_gv_by_basis.get(&offset).cloned();
            let offset_known_qn_history_status = known_qn_history_status(
                offset_toric_gv.as_deref(),
                offset_source_derived_gv.as_deref(),
            )?
            .to_string();
            let parent_path_support =
                path_support_runtime_curve_lookup(parent_probe, &term.exponent_nonzero, context)?;
            let source_context = path_support_source_class_context(&curve, context)?;
            let source_first_generation_seed_sum = first_generation_seed_sum_decomposition(
                &curve,
                context.grading,
                seed_set,
                reduced_seed_set,
                &context.covered_toric_gv_by_basis,
                &context.source_derived_gv_by_basis,
            )?;
            let source_bounded_seed_decomposition =
                bounded_seed_decomposition_summary(&curve, seed_set, 4, Some(context))?;
            Ok(CygvResidualQnDomainTermClassification {
                exponent_nonzero: term.exponent_nonzero.clone(),
                coefficient: term.coefficient.clone(),
                degree,
                parent_path_support_gv: parent_path_support.path_support_gv,
                parent_path_support_qn_trace_status: parent_path_support
                    .path_support_qn_trace_status,
                parent_path_support_qn_trace_term_count: parent_path_support
                    .path_support_qn_trace_term_count,
                parent_path_support_qn_term_sample_complete: parent_path_support
                    .path_support_qn_term_sample_complete,
                parent_path_support_qn_polynomial_shape_status: parent_path_support
                    .path_support_qn_polynomial_shape_status,
                parent_path_support_qn_term_signature_sample: parent_path_support
                    .path_support_qn_term_signature_sample,
                parent_path_support_gv_coefficient_status: parent_path_support
                    .path_support_gv_coefficient_status,
                parent_path_support_instanton_coefficient: parent_path_support
                    .path_support_instanton_coefficient,
                parent_path_support_gv_candidate: parent_path_support.path_support_gv_candidate,
                parent_path_support_rounded_gv_candidate: parent_path_support
                    .path_support_rounded_gv_candidate,
                offset_from_residual_nonzero: sparse_from_dense(&offset),
                offset_from_residual_degree,
                offset_toric_gv,
                offset_source_derived_gv,
                offset_known_qn_history_status,
                source_class_status: source_context.status,
                source_ray_ambient_nonzero: source_context.source_ray_ambient_nonzero,
                matching_missing_target_index: source_context.matching_missing_target_index,
                matching_missing_target_degree: source_context.matching_missing_target_degree,
                matching_missing_target_exact_kind: source_context
                    .matching_missing_target_exact_kind,
                matching_uncovered_source_ray_index: source_context
                    .matching_uncovered_source_ray_index,
                matching_uncovered_source_ray_degree: source_context
                    .matching_uncovered_source_ray_degree,
                matching_uncovered_source_ray_exact_kind: source_context
                    .matching_uncovered_source_ray_exact_kind,
                source_is_seed: Some(seed_set.contains(&curve)),
                source_is_reduced_seed: Some(reduced_seed_set.contains(&curve)),
                source_first_generation_seed_sum,
                source_bounded_seed_decomposition: Some(source_bounded_seed_decomposition),
            })
        })
        .collect()
}

fn parent_only_qn_term_source_status_counts(
    classifications: &[CygvResidualQnDomainTermClassification],
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for classification in classifications {
        *counts
            .entry(classification.source_class_status.clone())
            .or_insert(0) += 1;
    }
    counts
}

fn parent_only_qn_term_offset_degree_counts(
    classifications: &[CygvResidualQnDomainTermClassification],
) -> BTreeMap<i128, usize> {
    let mut counts = BTreeMap::new();
    for classification in classifications {
        *counts
            .entry(classification.offset_from_residual_degree)
            .or_insert(0) += 1;
    }
    counts
}

fn path_support_runtime_curve_lookup(
    probe: &PathSupportGeneratorProbe,
    curve_nonzero: &[(usize, i64)],
    context: &ValidatedContext<'_>,
) -> Result<PathSupportCurveRuntimeLookup, String> {
    if probe.status.as_deref() != Some("computed_path_support_generators") {
        return Ok(PathSupportCurveRuntimeLookup {
            path_support_gv: None,
            path_support_qn_trace_status: None,
            path_support_qn_trace_term_count: None,
            path_support_qn_term_sample_complete: None,
            path_support_qn_polynomial_shape_status: None,
            path_support_qn_term_signature_sample: Vec::new(),
            path_support_gv_coefficient_status: None,
            path_support_instanton_coefficient: None,
            path_support_gv_candidate: None,
            path_support_rounded_gv_candidate: None,
        });
    }
    let curve = dense_from_sparse(curve_nonzero, context.dimension)?;
    let curve_i32 = curve_i64_to_i32(&curve, "path-support runtime lookup curve")?;
    let path_support_gv = probe
        .gv_by_curve
        .get(&curve_i32)
        .cloned()
        .unwrap_or_else(|| "0".to_string());
    let path_support_qn_trace_term_count =
        probe.qn_trace_term_counts_by_curve.get(&curve_i32).copied();
    let path_support_qn_trace_status =
        path_support_qn_trace_status(&path_support_gv, path_support_qn_trace_term_count)?
            .to_string();
    let qn_trace = probe.qn_trace_by_curve.get(&curve_i32);
    let path_support_qn_term_sample_complete =
        qn_trace.map(|poly| poly.terms.len() <= CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT);
    let path_support_qn_polynomial_shape_status =
        qn_trace.map(|poly| qn_polynomial_shape_status(poly, &curve_i32).to_string());
    let path_support_qn_term_signature_sample = qn_trace
        .map(|poly| {
            poly.terms
                .iter()
                .take(CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT)
                .map(|term| CygvPathSupportQnTraceTermSignature {
                    exponent_nonzero: sparse_from_i32_dense(&term.exponent),
                    coefficient: term.coefficient.clone(),
                })
                .collect()
        })
        .unwrap_or_default();
    let gv_coefficient_trace = probe.gv_coefficient_trace_by_curve.get(&curve_i32);
    Ok(PathSupportCurveRuntimeLookup {
        path_support_gv: Some(path_support_gv),
        path_support_qn_trace_status: Some(path_support_qn_trace_status),
        path_support_qn_trace_term_count,
        path_support_qn_term_sample_complete,
        path_support_qn_polynomial_shape_status,
        path_support_qn_term_signature_sample,
        path_support_gv_coefficient_status: gv_coefficient_trace.map(|entry| entry.status.clone()),
        path_support_instanton_coefficient: gv_coefficient_trace
            .and_then(|entry| entry.instanton_coefficient.clone()),
        path_support_gv_candidate: gv_coefficient_trace
            .and_then(|entry| entry.gv_candidate.clone()),
        path_support_rounded_gv_candidate: gv_coefficient_trace
            .and_then(|entry| entry.rounded_gv_candidate.clone()),
    })
}

fn qn_polynomial_shape_status(poly: &CygvQnTracePolynomial, curve: &[i32]) -> &'static str {
    match poly.terms.as_slice() {
        [] => "empty_qn_polynomial",
        [term] if term.exponent.as_slice() == curve && term.coefficient == "1" => {
            "identity_single_term_qn_polynomial"
        }
        [_] => "nonidentity_single_term_qn_polynomial",
        terms
            if terms
                .iter()
                .any(|term| term.exponent.as_slice() == curve && term.coefficient == "1") =>
        {
            "multi_term_qn_polynomial_with_identity_term"
        }
        _ => "multi_term_qn_polynomial_without_identity_term",
    }
}

fn qn_trace_sample_for_curve<'a>(
    probe: &'a PathSupportGeneratorProbe,
    curve_nonzero: &[(usize, i64)],
) -> Option<&'a CygvPathSupportQnTracePolynomialSample> {
    probe
        .qn_trace_sample
        .iter()
        .find(|sample| sample.curve_nonzero.as_slice() == curve_nonzero)
}

fn qn_trace_sample_is_complete(sample: Option<&CygvPathSupportQnTracePolynomialSample>) -> bool {
    sample
        .map(|sample| sample.term_count <= sample.term_sample_limit)
        .unwrap_or(false)
}

fn qn_trace_term_signatures(
    sample: Option<&CygvPathSupportQnTracePolynomialSample>,
) -> Vec<CygvPathSupportQnTraceTermSignature> {
    sample
        .into_iter()
        .flat_map(|sample| sample.term_sample.iter())
        .map(|term| CygvPathSupportQnTraceTermSignature {
            exponent_nonzero: term.exponent_nonzero.clone(),
            coefficient: term.coefficient.clone(),
        })
        .collect()
}

fn qn_domain_comparison_status(
    parent_qn: Option<&CygvPathSupportQnTracePolynomialSample>,
    residual_qn: Option<&CygvPathSupportQnTracePolynomialSample>,
    parent_sample_complete: bool,
    residual_sample_complete: bool,
    parent_terms: &[CygvPathSupportQnTraceTermSignature],
    residual_terms: &[CygvPathSupportQnTraceTermSignature],
) -> String {
    match (parent_qn, residual_qn) {
        (None, None) => "missing_in_parent_and_residual_subtarget".to_string(),
        (None, Some(_)) => "missing_in_parent_path_support".to_string(),
        (Some(_), None) => "missing_in_residual_subtarget".to_string(),
        (Some(parent), Some(residual)) if parent.term_count != residual.term_count => {
            "different_qn_term_counts".to_string()
        }
        (Some(_), Some(_)) if !parent_sample_complete || !residual_sample_complete => {
            "same_count_but_sample_truncated".to_string()
        }
        (Some(_), Some(_)) if parent_terms == residual_terms => {
            "same_qn_term_signatures".to_string()
        }
        (Some(_), Some(_)) => "same_count_different_qn_term_signatures".to_string(),
    }
}

fn sorted_path_support_indices(support: &HashSet<usize>) -> Vec<usize> {
    let mut indices = support.iter().copied().collect::<Vec<_>>();
    indices.sort_unstable();
    indices
}

fn path_support_generator_degree_counts(
    generators: &[Vec<i64>],
    grading: &[i64],
) -> Result<BTreeMap<i128, usize>, String> {
    let mut counts = BTreeMap::new();
    for generator in generators {
        let degree = curve_degree(generator, grading)?;
        *counts.entry(degree).or_insert(0) += 1;
    }
    Ok(counts)
}

fn path_support_generator_nonzero_sample(generators: &[Vec<i64>]) -> Vec<Vec<(usize, i64)>> {
    generators
        .iter()
        .take(CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT)
        .map(|generator| sparse_from_dense(generator))
        .collect()
}

struct PathSupportGwCoefficientDiagnostic {
    trace_count: Option<usize>,
    noninteger_candidate_count: Option<usize>,
    noninteger_known_qn_history_status_counts: BTreeMap<String, usize>,
    noninteger_source_class_status_counts: BTreeMap<String, usize>,
    noninteger_candidate_sample: Vec<CygvPathSupportGvCoefficientTraceSample>,
    error: Option<String>,
    target_status: Option<String>,
    target_instanton_coefficient: Option<String>,
    target_gw_candidate: Option<String>,
    target_pivot_coordinate: Option<usize>,
    target_pivot_component: Option<i32>,
}

fn gw_noninteger_classification_counts(
    trace: &[CygvGvCoefficientTrace],
    context: &ValidatedContext<'_>,
) -> (BTreeMap<String, usize>, BTreeMap<String, usize>) {
    let mut known_counts = BTreeMap::new();
    let mut source_counts = BTreeMap::new();
    for entry in trace
        .iter()
        .filter(|entry| gv_coefficient_trace_has_noninteger_candidate(entry))
    {
        let (known_status, source_status) =
            gv_coefficient_trace_classification(entry, Some(context));
        let known_status =
            known_status.unwrap_or_else(|| "known_qn_history_status_missing".to_string());
        let source_status =
            source_status.unwrap_or_else(|| "source_class_status_missing".to_string());
        *known_counts.entry(known_status).or_insert(0) += 1;
        *source_counts.entry(source_status).or_insert(0) += 1;
    }
    (known_counts, source_counts)
}

fn path_support_gw_coefficient_diagnostic(
    generators: &[Vec<i64>],
    context: &ValidatedContext<'_>,
    max_deg: u32,
    target: &[i32],
) -> PathSupportGwCoefficientDiagnostic {
    match compute_gw_coefficient_trace_with_provided_generators(
        generators,
        context.grading,
        context.q_matrix,
        &context.intersection,
        None,
        Some(max_deg),
    ) {
        Ok(trace) => {
            let noninteger_count = trace
                .iter()
                .filter(|entry| gv_coefficient_trace_has_noninteger_candidate(entry))
                .count();
            let (known_counts, source_counts) =
                gw_noninteger_classification_counts(&trace, context);
            let sample = path_support_gw_noninteger_candidate_sample(&trace, context);
            let target_trace = trace
                .iter()
                .find(|entry| entry.element.as_slice() == target);
            PathSupportGwCoefficientDiagnostic {
                trace_count: Some(trace.len()),
                noninteger_candidate_count: Some(noninteger_count),
                noninteger_known_qn_history_status_counts: known_counts,
                noninteger_source_class_status_counts: source_counts,
                noninteger_candidate_sample: sample,
                error: None,
                target_status: target_trace.map(|entry| entry.status.clone()),
                target_instanton_coefficient: target_trace
                    .and_then(|entry| entry.instanton_coefficient.clone()),
                target_gw_candidate: target_trace.and_then(|entry| entry.gv_candidate.clone()),
                target_pivot_coordinate: target_trace.map(|entry| entry.insertion_index),
                target_pivot_component: target_trace.map(|entry| entry.pivot_component),
            }
        }
        Err(error) => PathSupportGwCoefficientDiagnostic {
            trace_count: None,
            noninteger_candidate_count: None,
            noninteger_known_qn_history_status_counts: BTreeMap::new(),
            noninteger_source_class_status_counts: BTreeMap::new(),
            noninteger_candidate_sample: Vec::new(),
            error: Some(error.to_string()),
            target_status: None,
            target_instanton_coefficient: None,
            target_gw_candidate: None,
            target_pivot_coordinate: None,
            target_pivot_component: None,
        },
    }
}

