fn path_support_qn_trace_sample(
    qn_trace: &[CygvQnTracePolynomial],
) -> Vec<CygvPathSupportQnTracePolynomialSample> {
    qn_trace
        .iter()
        .take(CYGV_PATH_SUPPORT_QN_TRACE_SAMPLE_LIMIT)
        .map(|poly| CygvPathSupportQnTracePolynomialSample {
            element_index: poly.element_index,
            degree: poly.degree,
            curve_nonzero: sparse_from_i32_dense(&poly.element),
            term_count: poly.terms.len(),
            term_sample_limit: CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT,
            term_sample: poly
                .terms
                .iter()
                .take(CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT)
                .map(|term| CygvPathSupportQnTraceTermSample {
                    monomial_index: term.monomial_index,
                    exponent_nonzero: sparse_from_i32_dense(&term.exponent),
                    coefficient: term.coefficient.clone(),
                })
                .collect(),
        })
        .collect()
}

fn path_support_gv_coefficient_status_counts(
    trace: &[CygvGvCoefficientTrace],
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for entry in trace {
        *counts.entry(entry.status.clone()).or_insert(0) += 1;
    }
    counts
}

fn gv_coefficient_trace_classification(
    entry: &CygvGvCoefficientTrace,
    context: Option<&ValidatedContext<'_>>,
) -> (Option<String>, Option<String>) {
    let Some(context) = context else {
        return (None, None);
    };
    let curve = entry
        .element
        .iter()
        .map(|&value| i64::from(value))
        .collect::<Vec<_>>();
    let known_status = known_qn_history_status(
        context
            .covered_toric_gv_by_basis
            .get(&curve)
            .map(String::as_str),
        context
            .source_derived_gv_by_basis
            .get(&curve)
            .map(String::as_str),
    )
    .map(str::to_string)
    .unwrap_or_else(|error| {
        format!(
            "known_qn_history_classification_error_{}",
            status_error_fragment(&error)
        )
    });
    let source_status = path_support_source_class_context(&curve, context)
        .map(|source_context| source_context.status)
        .unwrap_or_else(|error| {
            format!(
                "source_classification_error_{}",
                status_error_fragment(&error)
            )
        });
    (Some(known_status), Some(source_status))
}

fn path_support_gv_coefficient_trace_sample(
    trace: &[CygvGvCoefficientTrace],
    context: Option<&ValidatedContext<'_>>,
) -> Vec<CygvPathSupportGvCoefficientTraceSample> {
    trace
        .iter()
        .take(CYGV_PATH_SUPPORT_GV_COEFFICIENT_TRACE_SAMPLE_LIMIT)
        .map(|entry| {
            let (known_qn_history_status, source_class_status) =
                gv_coefficient_trace_classification(entry, context);
            CygvPathSupportGvCoefficientTraceSample {
                element_index: entry.element_index,
                degree: entry.degree,
                curve_nonzero: sparse_from_i32_dense(&entry.element),
                known_qn_history_status,
                source_class_status,
                insertion_index: entry.insertion_index,
                pivot_component: entry.pivot_component,
                instanton_coefficient: entry.instanton_coefficient.clone(),
                gv_candidate: entry.gv_candidate.clone(),
                rounded_gv_candidate: entry.rounded_gv_candidate.clone(),
                status: entry.status.clone(),
            }
        })
        .collect()
}

fn gv_coefficient_trace_has_noninteger_candidate(entry: &CygvGvCoefficientTrace) -> bool {
    let Some(candidate) = entry.gv_candidate.as_deref() else {
        return false;
    };
    parse_rational(candidate)
        .map(|candidate| candidate.denominator_ref() != &1u32)
        .unwrap_or(false)
}

fn path_support_gw_noninteger_candidate_sample(
    trace: &[CygvGvCoefficientTrace],
    context: &ValidatedContext<'_>,
) -> Vec<CygvPathSupportGvCoefficientTraceSample> {
    let noninteger_candidates = trace
        .iter()
        .filter(|entry| gv_coefficient_trace_has_noninteger_candidate(entry))
        .cloned()
        .collect::<Vec<_>>();
    path_support_gv_coefficient_trace_sample(&noninteger_candidates, Some(context))
}

fn path_support_target_monomial_qn_sources(
    qn_trace: &[CygvQnTracePolynomial],
    gvs_by_curve: &HashMap<Vec<i32>, String>,
    target: &[i32],
    context: Option<&ValidatedContext<'_>>,
) -> Result<Vec<CygvPathSupportTargetMonomialQnSource>, String> {
    let target_pivot_coordinate = target.iter().position(|&value| value != 0);
    qn_trace
        .iter()
        .filter_map(|poly| {
            let target_terms = poly
                .terms
                .iter()
                .filter(|term| term.exponent.as_slice() == target)
                .collect::<Vec<_>>();
            if target_terms.is_empty() {
                return None;
            }
            Some((poly, target_terms))
        })
        .map(|(poly, target_terms)| {
            let li2_coefficient = poly
                .li2_terms
                .iter()
                .filter(|term| term.exponent.as_slice() == target)
                .try_fold(MalachiteRational::from(0), |acc, term| {
                    parse_rational(&term.coefficient).map(|coefficient| acc + coefficient)
                });
            let (target_li2_coefficient_status, li2_coefficient) = match li2_coefficient {
                Ok(value) => (
                    "target_li2_coefficient_from_cygv_trace".to_string(),
                    Some(value),
                ),
                Err(error) => (format!("target_li2_coefficient_error: {error}"), None),
            };
            let curve_gv = gvs_by_curve.get(&poly.element).cloned();
            let (source_component_at_target_pivot, pivot_li2_subtraction_coefficient) = match (
                target_pivot_coordinate,
                curve_gv.as_deref().map(parse_rational).transpose(),
                li2_coefficient.as_ref(),
            ) {
                (Some(pivot), Ok(Some(gv)), Some(li2)) => {
                    let component = poly.element.get(pivot).copied().unwrap_or_default();
                    let coefficient =
                        gv * MalachiteRational::from(Integer::from(component)) * li2.clone();
                    (Some(component), Some(coefficient.to_string()))
                }
                (Some(pivot), _, _) => (poly.element.get(pivot).copied(), None),
                (None, _, _) => (None, None),
            };
            let source_context = match context {
                Some(context) => {
                    let source_curve = poly
                        .element
                        .iter()
                        .map(|&value| i64::from(value))
                        .collect::<Vec<_>>();
                    path_support_source_class_context(&source_curve, context)?
                }
                None => PathSupportSourceClassContext {
                    status: "not_classified_no_context".to_string(),
                    source_ray_ambient_nonzero: None,
                    matching_missing_target_index: None,
                    matching_missing_target_degree: None,
                    matching_missing_target_origin_circuit_pattern: None,
                    matching_missing_target_exact_kind: None,
                    matching_uncovered_source_ray_index: None,
                    matching_uncovered_source_ray_degree: None,
                    matching_uncovered_source_ray_origin_circuit_pattern: None,
                    matching_uncovered_source_ray_exact_kind: None,
                    matching_uncovered_source_ray_cms_check_status_counts: BTreeMap::new(),
                    matching_uncovered_source_ray_cms_solution_summaries: Vec::new(),
                    matching_uncovered_source_ray_local_charge_signature: None,
                    matching_uncovered_source_ray_local_cygv_readiness: None,
                    matching_uncovered_source_ray_local_missing_inputs: Vec::new(),
                    matching_uncovered_source_ray_local_cygv_input_skeleton: None,
                    matching_uncovered_source_ray_local_unit_phase_probe: None,
                },
            };
            Ok(CygvPathSupportTargetMonomialQnSource {
                element_index: poly.element_index,
                degree: poly.degree,
                curve_nonzero: sparse_from_i32_dense(&poly.element),
                curve_gv,
                term_count: poly.terms.len(),
                source_qn_term_sample_complete: poly.terms.len()
                    <= CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT,
                source_qn_polynomial_shape_status: qn_polynomial_shape_status(poly, &poly.element)
                    .to_string(),
                source_qn_term_signature_sample: poly
                    .terms
                    .iter()
                    .take(CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT)
                    .map(|term| CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: sparse_from_i32_dense(&term.exponent),
                        coefficient: term.coefficient.clone(),
                    })
                    .collect(),
                target_term_count: target_terms.len(),
                target_term_monomial_indices: target_terms
                    .iter()
                    .map(|term| term.monomial_index)
                    .collect(),
                target_term_coefficients: target_terms
                    .iter()
                    .map(|term| term.coefficient.clone())
                    .collect(),
                target_li2_coefficient_status,
                target_li2_coefficient: li2_coefficient.map(|value| value.to_string()),
                target_pivot_coordinate,
                source_component_at_target_pivot,
                pivot_li2_subtraction_coefficient,
                source_class_status: source_context.status,
                source_ray_ambient_nonzero: source_context.source_ray_ambient_nonzero,
                matching_missing_target_index: source_context.matching_missing_target_index,
                matching_missing_target_degree: source_context.matching_missing_target_degree,
                matching_missing_target_origin_circuit_pattern: source_context
                    .matching_missing_target_origin_circuit_pattern,
                matching_missing_target_exact_kind: source_context
                    .matching_missing_target_exact_kind,
                matching_uncovered_source_ray_index: source_context
                    .matching_uncovered_source_ray_index,
                matching_uncovered_source_ray_degree: source_context
                    .matching_uncovered_source_ray_degree,
                matching_uncovered_source_ray_origin_circuit_pattern: source_context
                    .matching_uncovered_source_ray_origin_circuit_pattern,
                matching_uncovered_source_ray_exact_kind: source_context
                    .matching_uncovered_source_ray_exact_kind,
                matching_uncovered_source_ray_local_cygv_readiness: source_context
                    .matching_uncovered_source_ray_local_cygv_readiness,
                matching_uncovered_source_ray_local_missing_inputs: source_context
                    .matching_uncovered_source_ray_local_missing_inputs,
                source_is_seed: None,
                source_is_reduced_seed: None,
                source_first_generation_seed_sum: None,
                source_bounded_seed_decomposition: None,
                source_bounded_diamond_parent_qn_comparison_status: None,
                source_bounded_diamond_parent_only_qn_term_signature_sample: Vec::new(),
                source_bounded_diamond_diamond_only_qn_term_signature_sample: Vec::new(),
                source_bounded_diamond_parent_only_qn_term_context_sample: Vec::new(),
                source_parent_qn_term_semigroup_probe: None,
                source_parent_qn_term_seed_expanded_semigroup_probe: None,
                source_parent_qn_term_offset_generator_probe: None,
            })
        })
        .collect()
}

fn bounded_seed_decomposition_summary(
    target: &[i64],
    seed_set: &HashSet<Vec<i64>>,
    max_terms: usize,
    context: Option<&ValidatedContext<'_>>,
) -> Result<CygvBoundedSeedDecompositionSummary, String> {
    let mut seeds = seed_set.iter().cloned().collect::<Vec<_>>();
    seeds.sort();
    match bounded_seed_decomposition(target, &seeds, max_terms)? {
        Some(terms) => {
            let diamond = context
                .map(|context| bounded_decomposition_diamond_qn_trace(target, &terms, context))
                .transpose()?;
            Ok(CygvBoundedSeedDecompositionSummary {
                max_terms,
                status: "found_lower_seed_decomposition".to_string(),
                term_count: Some(terms.len()),
                terms_nonzero: Some(terms.iter().map(|term| sparse_from_dense(term)).collect()),
                diamond_element_count: diamond.as_ref().and_then(|probe| probe.element_count),
                diamond_status: diamond.as_ref().and_then(|probe| probe.status.clone()),
                diamond_gv: diamond.as_ref().and_then(|probe| probe.gv.clone()),
                diamond_error: diamond.as_ref().and_then(|probe| probe.error.clone()),
                diamond_qn_trace_polynomial_count: diamond
                    .as_ref()
                    .and_then(|probe| probe.qn_trace_polynomial_count),
                diamond_target_qn_trace_status: diamond
                    .as_ref()
                    .and_then(|probe| probe.target_qn_trace_status.clone()),
                diamond_target_qn_trace_term_count: diamond
                    .as_ref()
                    .and_then(|probe| probe.target_qn_trace_term_count),
                diamond_qn_trace_sample: diamond
                    .as_ref()
                    .map(|probe| probe.qn_trace_sample.clone())
                    .unwrap_or_default(),
                diamond_gw_coefficient_trace_count: diamond
                    .as_ref()
                    .and_then(|probe| probe.gw_coefficient_trace_count),
                diamond_gw_noninteger_candidate_count: diamond
                    .as_ref()
                    .and_then(|probe| probe.gw_noninteger_candidate_count),
                diamond_gw_noninteger_known_qn_history_status_counts: diamond
                    .as_ref()
                    .map(|probe| probe.gw_noninteger_known_qn_history_status_counts.clone())
                    .unwrap_or_default(),
                diamond_gw_noninteger_source_class_status_counts: diamond
                    .as_ref()
                    .map(|probe| probe.gw_noninteger_source_class_status_counts.clone())
                    .unwrap_or_default(),
                diamond_gw_noninteger_candidate_sample: diamond
                    .as_ref()
                    .map(|probe| probe.gw_noninteger_candidate_sample.clone())
                    .unwrap_or_default(),
                diamond_gw_coefficient_trace_error: diamond
                    .as_ref()
                    .and_then(|probe| probe.gw_coefficient_trace_error.clone()),
                diamond_target_gw_coefficient_status: diamond
                    .as_ref()
                    .and_then(|probe| probe.target_gw_coefficient_status.clone()),
                diamond_target_gw_instanton_coefficient: diamond
                    .as_ref()
                    .and_then(|probe| probe.target_gw_instanton_coefficient.clone()),
                diamond_target_gw_candidate: diamond
                    .as_ref()
                    .and_then(|probe| probe.target_gw_candidate.clone()),
            })
        }
        None => Ok(CygvBoundedSeedDecompositionSummary {
            max_terms,
            status: format!("not_found_up_to_{max_terms}"),
            term_count: None,
            terms_nonzero: None,
            diamond_element_count: None,
            diamond_status: None,
            diamond_gv: None,
            diamond_error: None,
            diamond_qn_trace_polynomial_count: None,
            diamond_target_qn_trace_status: None,
            diamond_target_qn_trace_term_count: None,
            diamond_qn_trace_sample: Vec::new(),
            diamond_gw_coefficient_trace_count: None,
            diamond_gw_noninteger_candidate_count: None,
            diamond_gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            diamond_gw_noninteger_source_class_status_counts: BTreeMap::new(),
            diamond_gw_noninteger_candidate_sample: Vec::new(),
            diamond_gw_coefficient_trace_error: None,
            diamond_target_gw_coefficient_status: None,
            diamond_target_gw_instanton_coefficient: None,
            diamond_target_gw_candidate: None,
        }),
    }
}

fn bounded_decomposition_diamond_qn_trace(
    target: &[i64],
    terms: &[Vec<i64>],
    context: &ValidatedContext<'_>,
) -> Result<CygvBoundedDecompositionDiamondProbe, String> {
    let elements = decomposition_diamond_elements(terms, target)?;
    if elements.len() > CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT {
        return Ok(CygvBoundedDecompositionDiamondProbe {
            element_count: Some(elements.len()),
            status: Some(format!(
                "skipped_element_limit_{CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT}"
            )),
            gv: None,
            error: None,
            qn_trace_polynomial_count: None,
            target_qn_trace_status: None,
            target_qn_trace_term_count: None,
            qn_trace_sample: Vec::new(),
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            target_gw_coefficient_status: None,
            target_gw_instanton_coefficient: None,
            target_gw_candidate: None,
            target_gw_pivot_coordinate: None,
            target_gw_pivot_component: None,
        });
    }
    if context.q_matrix.is_empty() || context.q_cols == 0 {
        return Ok(CygvBoundedDecompositionDiamondProbe {
            element_count: Some(elements.len()),
            status: Some("skipped_no_q_matrix".to_string()),
            gv: None,
            error: None,
            qn_trace_polynomial_count: None,
            target_qn_trace_status: None,
            target_qn_trace_term_count: None,
            qn_trace_sample: Vec::new(),
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            target_gw_coefficient_status: None,
            target_gw_instanton_coefficient: None,
            target_gw_candidate: None,
            target_gw_pivot_coordinate: None,
            target_gw_pivot_component: None,
        });
    }
    if cfg!(panic = "abort") {
        return Ok(CygvBoundedDecompositionDiamondProbe {
            element_count: Some(elements.len()),
            status: Some("hkty_unavailable_panic_abort".to_string()),
            gv: None,
            error: Some(
                "running cygv explicit-semigroup HKTY requires a panic=unwind build for diagnostics"
                    .to_string(),
            ),
            qn_trace_polynomial_count: None,
            target_qn_trace_status: None,
            target_qn_trace_term_count: None,
            qn_trace_sample: Vec::new(),
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            target_gw_coefficient_status: None,
            target_gw_instanton_coefficient: None,
            target_gw_candidate: None,
            target_gw_pivot_coordinate: None,
            target_gw_pivot_component: None,
        });
    }
    let target_i32 = curve_i64_to_i32(target, "bounded-decomposition target")?;
    let gw_diagnostic =
        explicit_semigroup_gw_coefficient_diagnostic(&elements, context, &target_i32);
    let previous_panic_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let traced_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        compute_gv_invariants_with_explicit_semigroup_qn_trace(
            &elements,
            context.grading,
            context.q_matrix,
            &context.intersection,
        )
    }));
    std::panic::set_hook(previous_panic_hook);

    let traced = match traced_result {
        Ok(Ok(traced)) => traced,
        Ok(Err(error)) => {
            return Ok(CygvBoundedDecompositionDiamondProbe {
                element_count: Some(elements.len()),
                status: Some("hkty_error".to_string()),
                gv: None,
                error: Some(format!(
                    "bounded decomposition diamond qN trace failed: {error}"
                )),
                qn_trace_polynomial_count: None,
                target_qn_trace_status: None,
                target_qn_trace_term_count: None,
                qn_trace_sample: Vec::new(),
                gw_coefficient_trace_count: gw_diagnostic.trace_count,
                gw_noninteger_candidate_count: gw_diagnostic.noninteger_candidate_count,
                gw_noninteger_known_qn_history_status_counts: gw_diagnostic
                    .noninteger_known_qn_history_status_counts,
                gw_noninteger_source_class_status_counts: gw_diagnostic
                    .noninteger_source_class_status_counts,
                gw_noninteger_candidate_sample: gw_diagnostic.noninteger_candidate_sample,
                gw_coefficient_trace_error: gw_diagnostic.error,
                target_gw_coefficient_status: gw_diagnostic.target_status,
                target_gw_instanton_coefficient: gw_diagnostic.target_instanton_coefficient,
                target_gw_candidate: gw_diagnostic.target_gw_candidate,
                target_gw_pivot_coordinate: gw_diagnostic.target_pivot_coordinate,
                target_gw_pivot_component: gw_diagnostic.target_pivot_component,
            });
        }
        Err(payload) => {
            return Ok(CygvBoundedDecompositionDiamondProbe {
                element_count: Some(elements.len()),
                status: Some("hkty_panic".to_string()),
                gv: None,
                error: Some(format!(
                    "bounded decomposition diamond qN trace panicked: {}",
                    panic_payload_message(payload.as_ref())
                )),
                qn_trace_polynomial_count: None,
                target_qn_trace_status: None,
                target_qn_trace_term_count: None,
                qn_trace_sample: Vec::new(),
                gw_coefficient_trace_count: gw_diagnostic.trace_count,
                gw_noninteger_candidate_count: gw_diagnostic.noninteger_candidate_count,
                gw_noninteger_known_qn_history_status_counts: gw_diagnostic
                    .noninteger_known_qn_history_status_counts,
                gw_noninteger_source_class_status_counts: gw_diagnostic
                    .noninteger_source_class_status_counts,
                gw_noninteger_candidate_sample: gw_diagnostic.noninteger_candidate_sample,
                gw_coefficient_trace_error: gw_diagnostic.error,
                target_gw_coefficient_status: gw_diagnostic.target_status,
                target_gw_instanton_coefficient: gw_diagnostic.target_instanton_coefficient,
                target_gw_candidate: gw_diagnostic.target_gw_candidate,
                target_gw_pivot_coordinate: gw_diagnostic.target_pivot_coordinate,
                target_gw_pivot_component: gw_diagnostic.target_pivot_component,
            });
        }
    };
    let qn_trace_polynomial_count = traced.qn_trace.len();
    let target_qn_trace_term_count = traced
        .qn_trace
        .iter()
        .find_map(|poly| (poly.element == target_i32).then_some(poly.terms.len()));
    let gv = traced
        .invariants
        .into_iter()
        .find_map(|(curve, value)| (curve == target_i32).then(|| value.to_string()))
        .unwrap_or_else(|| "0".to_string());
    let target_qn_trace_status =
        path_support_qn_trace_status(&gv, target_qn_trace_term_count)?.to_string();
    Ok(CygvBoundedDecompositionDiamondProbe {
        element_count: Some(elements.len()),
        status: Some("computed_bounded_decomposition_diamond_qn_trace".to_string()),
        gv: Some(gv),
        error: None,
        qn_trace_polynomial_count: Some(qn_trace_polynomial_count),
        target_qn_trace_status: Some(target_qn_trace_status),
        target_qn_trace_term_count,
        qn_trace_sample: path_support_qn_trace_sample(&traced.qn_trace),
        gw_coefficient_trace_count: gw_diagnostic.trace_count,
        gw_noninteger_candidate_count: gw_diagnostic.noninteger_candidate_count,
        gw_noninteger_known_qn_history_status_counts: gw_diagnostic
            .noninteger_known_qn_history_status_counts,
        gw_noninteger_source_class_status_counts: gw_diagnostic
            .noninteger_source_class_status_counts,
        gw_noninteger_candidate_sample: gw_diagnostic.noninteger_candidate_sample,
        gw_coefficient_trace_error: gw_diagnostic.error,
        target_gw_coefficient_status: gw_diagnostic.target_status,
        target_gw_instanton_coefficient: gw_diagnostic.target_instanton_coefficient,
        target_gw_candidate: gw_diagnostic.target_gw_candidate,
        target_gw_pivot_coordinate: gw_diagnostic.target_pivot_coordinate,
        target_gw_pivot_component: gw_diagnostic.target_pivot_component,
    })
}

fn annotate_target_monomial_qn_sources_with_seed_decompositions(
    sources: &mut [CygvPathSupportTargetMonomialQnSource],
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
    context: &ValidatedContext<'_>,
    supporting_face_lp_options: &SupportingMoriFaceLpSearchOptions,
) -> Result<(), String> {
    for source in sources {
        let curve = dense_from_sparse(&source.curve_nonzero, context.dimension)?;
        source.source_is_seed = Some(seed_set.contains(&curve));
        source.source_is_reduced_seed = Some(reduced_seed_set.contains(&curve));
        source.source_first_generation_seed_sum = first_generation_seed_sum_decomposition(
            &curve,
            context.grading,
            seed_set,
            reduced_seed_set,
            &context.covered_toric_gv_by_basis,
            &context.source_derived_gv_by_basis,
        )?;
        let bounded_seed_decomposition =
            bounded_seed_decomposition_summary(&curve, seed_set, 4, Some(context))?;
        let comparison = bounded_diamond_parent_qn_comparison(source, &bounded_seed_decomposition);
        source.source_bounded_diamond_parent_qn_comparison_status = comparison.status;
        source.source_bounded_diamond_parent_only_qn_term_signature_sample =
            comparison.parent_only_term_signature_sample;
        source.source_bounded_diamond_diamond_only_qn_term_signature_sample =
            comparison.diamond_only_term_signature_sample;
        source.source_bounded_diamond_parent_only_qn_term_context_sample =
            qn_term_signature_context_sample(
                &source.source_bounded_diamond_parent_only_qn_term_signature_sample,
                context,
                seed_set,
                reduced_seed_set,
                Some(&curve),
            )?;
        source.source_bounded_seed_decomposition = Some(bounded_seed_decomposition);
        source.source_parent_qn_term_semigroup_probe =
            source_parent_qn_term_semigroup_probe(source, context)?;
        source.source_parent_qn_term_seed_expanded_semigroup_probe =
            source_parent_qn_term_seed_expanded_semigroup_probe(source, context, seed_set)?;
        source.source_parent_qn_term_offset_generator_probe =
            source_parent_qn_term_offset_generator_probe(
                source,
                context,
                supporting_face_lp_options,
            )?;
    }
    Ok(())
}

struct CygvBoundedDiamondParentQnComparison {
    status: Option<String>,
    parent_only_term_signature_sample: Vec<CygvPathSupportQnTraceTermSignature>,
    diamond_only_term_signature_sample: Vec<CygvPathSupportQnTraceTermSignature>,
}

fn bounded_diamond_parent_qn_comparison(
    source: &CygvPathSupportTargetMonomialQnSource,
    bounded: &CygvBoundedSeedDecompositionSummary,
) -> CygvBoundedDiamondParentQnComparison {
    if bounded.diamond_status.as_deref() != Some("computed_bounded_decomposition_diamond_qn_trace")
    {
        return CygvBoundedDiamondParentQnComparison {
            status: None,
            parent_only_term_signature_sample: Vec::new(),
            diamond_only_term_signature_sample: Vec::new(),
        };
    }
    let diamond_qn = bounded
        .diamond_qn_trace_sample
        .iter()
        .find(|sample| sample.curve_nonzero.as_slice() == source.curve_nonzero.as_slice());
    let Some(diamond_qn) = diamond_qn else {
        return CygvBoundedDiamondParentQnComparison {
            status: Some(
                if bounded.diamond_target_qn_trace_term_count.is_some() {
                    "bounded_diamond_target_qn_sample_truncated"
                } else {
                    "missing_in_bounded_diamond"
                }
                .to_string(),
            ),
            parent_only_term_signature_sample: source.source_qn_term_signature_sample.clone(),
            diamond_only_term_signature_sample: Vec::new(),
        };
    };
    let diamond_terms = qn_trace_term_signatures(Some(diamond_qn));
    let parent_only_term_signature_sample = qn_term_signature_multiset_difference(
        &source.source_qn_term_signature_sample,
        &diamond_terms,
        CYGV_BOUNDED_DIAMOND_PARENT_QN_DIFF_SAMPLE_LIMIT,
    );
    let diamond_only_term_signature_sample = qn_term_signature_multiset_difference(
        &diamond_terms,
        &source.source_qn_term_signature_sample,
        CYGV_BOUNDED_DIAMOND_PARENT_QN_DIFF_SAMPLE_LIMIT,
    );
    if source.term_count != diamond_qn.term_count {
        return CygvBoundedDiamondParentQnComparison {
            status: Some("different_qn_term_counts".to_string()),
            parent_only_term_signature_sample,
            diamond_only_term_signature_sample,
        };
    }
    if !source.source_qn_term_sample_complete || !qn_trace_sample_is_complete(Some(diamond_qn)) {
        return CygvBoundedDiamondParentQnComparison {
            status: Some("same_count_but_sample_truncated".to_string()),
            parent_only_term_signature_sample,
            diamond_only_term_signature_sample,
        };
    }
    CygvBoundedDiamondParentQnComparison {
        status: Some(
            if qn_term_signature_multisets_match(
                &source.source_qn_term_signature_sample,
                &diamond_terms,
            ) {
                "same_qn_term_signatures"
            } else {
                "same_count_different_qn_term_signatures"
            }
            .to_string(),
        ),
        parent_only_term_signature_sample,
        diamond_only_term_signature_sample,
    }
}

fn qn_term_signature_multiset_difference(
    left: &[CygvPathSupportQnTraceTermSignature],
    right: &[CygvPathSupportQnTraceTermSignature],
    limit: usize,
) -> Vec<CygvPathSupportQnTraceTermSignature> {
    let mut right_remaining = right.to_vec();
    let mut difference = Vec::new();
    for term in left {
        if let Some(pos) = right_remaining
            .iter()
            .position(|candidate| candidate == term)
        {
            right_remaining.remove(pos);
        } else if difference.len() < limit {
            difference.push(term.clone());
        }
    }
    difference
}

fn qn_term_signature_context_sample(
    signatures: &[CygvPathSupportQnTraceTermSignature],
    context: &ValidatedContext<'_>,
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
    source_curve: Option<&[i64]>,
) -> Result<Vec<CygvQnTermSignatureContext>, String> {
    signatures
        .iter()
        .map(|signature| {
            let curve = dense_from_sparse(&signature.exponent_nonzero, context.dimension)?;
            let degree = curve_degree(&curve, context.grading)?;
            let source_context = path_support_source_class_context(&curve, context)?;
            let offset_context = source_curve
                .map(|source_curve| {
                    let offset = checked_vector_difference(&curve, source_curve)?;
                    let offset_toric_gv = context.covered_toric_gv_by_basis.get(&offset).cloned();
                    let offset_source_derived_gv =
                        context.source_derived_gv_by_basis.get(&offset).cloned();
                    let offset_known_qn_history_status = known_qn_history_status(
                        offset_toric_gv.as_deref(),
                        offset_source_derived_gv.as_deref(),
                    )?
                    .to_string();
                    Ok::<_, String>((
                        sparse_from_dense(&offset),
                        curve_degree(&offset, context.grading)?,
                        offset_toric_gv,
                        offset_source_derived_gv,
                        offset_known_qn_history_status,
                    ))
                })
                .transpose()?;
            Ok(CygvQnTermSignatureContext {
                exponent_nonzero: signature.exponent_nonzero.clone(),
                coefficient: signature.coefficient.clone(),
                degree,
                known_qn_history_status: known_qn_history_status(
                    context
                        .covered_toric_gv_by_basis
                        .get(&curve)
                        .map(String::as_str),
                    context
                        .source_derived_gv_by_basis
                        .get(&curve)
                        .map(String::as_str),
                )?
                .to_string(),
                offset_from_source_nonzero: offset_context
                    .as_ref()
                    .map(|context| context.0.clone()),
                offset_from_source_degree: offset_context.as_ref().map(|context| context.1),
                offset_from_source_toric_gv: offset_context
                    .as_ref()
                    .and_then(|context| context.2.clone()),
                offset_from_source_derived_gv: offset_context
                    .as_ref()
                    .and_then(|context| context.3.clone()),
                offset_from_source_known_qn_history_status: offset_context
                    .as_ref()
                    .map(|context| context.4.clone()),
                source_class_status: source_context.status,
                matching_missing_target_index: source_context.matching_missing_target_index,
                matching_missing_target_degree: source_context.matching_missing_target_degree,
                matching_missing_target_exact_kind: source_context
                    .matching_missing_target_exact_kind,
                matching_uncovered_source_ray_index: source_context
                    .matching_uncovered_source_ray_index,
                matching_uncovered_source_ray_degree: source_context
                    .matching_uncovered_source_ray_degree,
                matching_uncovered_source_ray_exact_kind: source_context
                    .matching_uncovered_source_ray_exact_kind,
                source_is_seed: seed_set.contains(&curve),
                source_is_reduced_seed: reduced_seed_set.contains(&curve),
            })
        })
        .collect()
}

fn source_parent_qn_term_semigroup_probe(
    source: &CygvPathSupportTargetMonomialQnSource,
    context: &ValidatedContext<'_>,
) -> Result<Option<CygvSourceQnTermSemigroupProbe>, String> {
    if source
        .source_bounded_diamond_parent_qn_comparison_status
        .as_deref()
        != Some("different_qn_term_counts")
    {
        return Ok(None);
    }
    let elements = source_qn_term_support_elements(source, context.dimension)?;
    source_qn_term_semigroup_probe_from_elements(
        source,
        context,
        elements,
        "computed_source_qn_term_semigroup",
        "source qN-term semigroup",
    )
}

fn source_parent_qn_term_seed_expanded_semigroup_probe(
    source: &CygvPathSupportTargetMonomialQnSource,
    context: &ValidatedContext<'_>,
    seed_set: &HashSet<Vec<i64>>,
) -> Result<Option<CygvSourceQnTermSemigroupProbe>, String> {
    if source
        .source_bounded_diamond_parent_qn_comparison_status
        .as_deref()
        != Some("different_qn_term_counts")
    {
        return Ok(None);
    }
    let elements =
        source_qn_term_seed_expanded_support_elements(source, context.dimension, seed_set)?;
    source_qn_term_semigroup_probe_from_elements(
        source,
        context,
        elements,
        "computed_source_qn_term_seed_expanded_semigroup",
        "source qN-term seed-expanded semigroup",
    )
}

fn source_parent_qn_term_offset_generator_probe(
    source: &CygvPathSupportTargetMonomialQnSource,
    context: &ValidatedContext<'_>,
    supporting_face_lp_options: &SupportingMoriFaceLpSearchOptions,
) -> Result<Option<CygvSourceQnTermSemigroupProbe>, String> {
    if source
        .source_bounded_diamond_parent_qn_comparison_status
        .as_deref()
        != Some("different_qn_term_counts")
    {
        return Ok(None);
    }
    let (generators, max_degree) = source_qn_term_offset_generators(source, context)?;
    if generators.is_empty() {
        return Ok(None);
    }
    source_qn_term_provided_generator_probe_from_generators(
        source,
        context,
        generators,
        max_degree,
        "computed_source_qn_term_offset_generators",
        "source qN-term offset generators",
        supporting_face_lp_options,
    )
}

fn source_qn_term_support_elements(
    source: &CygvPathSupportTargetMonomialQnSource,
    dimension: usize,
) -> Result<Vec<Vec<i64>>, String> {
    let source_curve = dense_from_sparse(&source.curve_nonzero, dimension)?;
    let mut elements = Vec::new();
    let mut seen = HashSet::new();
    let zero = vec![0i64; dimension];
    if seen.insert(zero.clone()) {
        elements.push(zero);
    }
    if seen.insert(source_curve.clone()) {
        elements.push(source_curve.clone());
    }
    for signature in &source.source_qn_term_signature_sample {
        let element = dense_from_sparse(&signature.exponent_nonzero, dimension)?;
        if seen.insert(element.clone()) {
            elements.push(element);
        }
    }
    elements.sort();
    Ok(elements)
}

fn source_qn_term_offset_generators(
    source: &CygvPathSupportTargetMonomialQnSource,
    context: &ValidatedContext<'_>,
) -> Result<(Vec<Vec<i64>>, i128), String> {
    let source_curve = dense_from_sparse(&source.curve_nonzero, context.dimension)?;
    let mut generators = Vec::new();
    let mut seen = HashSet::new();
    let mut add_generator = |generator: Vec<i64>| {
        if generator.iter().any(|&coordinate| coordinate != 0) && seen.insert(generator.clone()) {
            generators.push(generator);
        }
    };

    let mut used_source_decomposition = false;
    if let Some(bounded) = &source.source_bounded_seed_decomposition
        && bounded.status == "found_lower_seed_decomposition"
        && let Some(terms) = bounded.terms_nonzero.as_deref()
    {
        for term in terms {
            add_generator(dense_from_sparse(term, context.dimension)?);
        }
        used_source_decomposition = true;
    }
    if !used_source_decomposition {
        add_generator(source_curve.clone());
    }

    for term_context in &source.source_bounded_diamond_parent_only_qn_term_context_sample {
        if term_context
            .offset_from_source_known_qn_history_status
            .as_deref()
            .is_some_and(|status| status.starts_with("known_nonzero"))
            && let Some(offset) = term_context.offset_from_source_nonzero.as_deref()
        {
            add_generator(dense_from_sparse(offset, context.dimension)?);
        }
    }

    generators.sort();
    let mut max_degree = curve_degree(&source_curve, context.grading)?;
    for signature in &source.source_qn_term_signature_sample {
        let curve = dense_from_sparse(&signature.exponent_nonzero, context.dimension)?;
        max_degree = max_degree.max(curve_degree(&curve, context.grading)?);
    }
    for term_context in &source.source_bounded_diamond_parent_only_qn_term_context_sample {
        max_degree = max_degree.max(term_context.degree);
    }
    Ok((generators, max_degree))
}

fn source_qn_term_generator_face_certificate(
    generators: &[Vec<i64>],
    context: &ValidatedContext<'_>,
    supporting_face_lp_options: &SupportingMoriFaceLpSearchOptions,
) -> Result<CygvSourceQnTermGeneratorFaceCertificate, String> {
    if generators.is_empty() {
        return Ok(CygvSourceQnTermGeneratorFaceCertificate {
            status: "offset_generators_no_generators".to_string(),
            normal_nonzero: None,
            zero_count: None,
            positive_count: None,
            lp_search_status: None,
            lp_exact_kernel_status: None,
            lp_full_status: None,
            lp_aggregate_status: None,
            lp_anchor_attempt_count: None,
            lp_anchor_lp_solution_count: None,
            lp_anchor_status_counts: BTreeMap::new(),
        });
    }
    let rank = curve_row_span_rank(generators)
        .map_err(|error| format!("offset-generator face rank failed: {error}"))?;
    if rank >= context.dimension {
        return Ok(CygvSourceQnTermGeneratorFaceCertificate {
            status: format!(
                "offset_generators_full_dimensional_rank_{rank}_dim_{}",
                context.dimension
            ),
            normal_nonzero: None,
            zero_count: None,
            positive_count: None,
            lp_search_status: None,
            lp_exact_kernel_status: None,
            lp_full_status: None,
            lp_aggregate_status: None,
            lp_anchor_attempt_count: None,
            lp_anchor_lp_solution_count: None,
            lp_anchor_status_counts: BTreeMap::new(),
        });
    }

    if rank == context.dimension.saturating_sub(1) {
        return match certify_supporting_mori_face_by_exact_kernel(
            generators,
            context.degree_bounded_rays,
        ) {
            Ok(Some(certificate)) => Ok(CygvSourceQnTermGeneratorFaceCertificate {
                status: format!(
                    "offset_generators_certified_exact_kernel_rank_{rank}_dim_{}",
                    context.dimension
                ),
                normal_nonzero: Some(sparse_from_dense(&certificate.normal)),
                zero_count: Some(certificate.zero_generator_count),
                positive_count: Some(certificate.positive_generator_count),
                lp_search_status: None,
                lp_exact_kernel_status: None,
                lp_full_status: None,
                lp_aggregate_status: None,
                lp_anchor_attempt_count: None,
                lp_anchor_lp_solution_count: None,
                lp_anchor_status_counts: BTreeMap::new(),
            }),
            Ok(None) => Ok(CygvSourceQnTermGeneratorFaceCertificate {
                status: format!(
                    "offset_generators_codimension_one_but_not_supporting_rank_{rank}_dim_{}",
                    context.dimension
                ),
                normal_nonzero: None,
                zero_count: None,
                positive_count: None,
                lp_search_status: None,
                lp_exact_kernel_status: None,
                lp_full_status: None,
                lp_aggregate_status: None,
                lp_anchor_attempt_count: None,
                lp_anchor_lp_solution_count: None,
                lp_anchor_status_counts: BTreeMap::new(),
            }),
            Err(error) => Ok(CygvSourceQnTermGeneratorFaceCertificate {
                status: format!(
                    "offset_generators_face_certificate_error_{}",
                    status_error_fragment(&error.to_string())
                ),
                normal_nonzero: None,
                zero_count: None,
                positive_count: None,
                lp_search_status: None,
                lp_exact_kernel_status: None,
                lp_full_status: None,
                lp_aggregate_status: None,
                lp_anchor_attempt_count: None,
                lp_anchor_lp_solution_count: None,
                lp_anchor_status_counts: BTreeMap::new(),
            }),
        };
    }

    match diagnose_supporting_mori_face_by_lp_search(
        generators,
        context.degree_bounded_rays,
        supporting_face_lp_options,
    ) {
        Ok(diagnostic) => {
            let certificate = diagnostic.certificate.as_ref();
            Ok(CygvSourceQnTermGeneratorFaceCertificate {
                status: if certificate.is_some() {
                    format!(
                        "offset_generators_certified_lp_containing_face_rank_{rank}_dim_{}",
                        context.dimension
                    )
                } else {
                    format!(
                        "offset_generators_lp_no_certificate_rank_{rank}_dim_{}",
                        context.dimension
                    )
                },
                normal_nonzero: certificate
                    .map(|certificate| sparse_from_dense(&certificate.normal)),
                zero_count: certificate.map(|certificate| certificate.zero_generator_count),
                positive_count: certificate.map(|certificate| certificate.positive_generator_count),
                lp_search_status: Some(diagnostic.status),
                lp_exact_kernel_status: Some(diagnostic.exact_kernel_status),
                lp_full_status: Some(diagnostic.full_status),
                lp_aggregate_status: Some(diagnostic.aggregate_status),
                lp_anchor_attempt_count: Some(diagnostic.anchor_attempt_count),
                lp_anchor_lp_solution_count: Some(diagnostic.anchor_lp_solution_count),
                lp_anchor_status_counts: diagnostic.anchor_status_counts,
            })
        }
        Err(error) => Ok(CygvSourceQnTermGeneratorFaceCertificate {
            status: format!(
                "offset_generators_face_certificate_error_{}",
                status_error_fragment(&error.to_string())
            ),
            normal_nonzero: None,
            zero_count: None,
            positive_count: None,
            lp_search_status: None,
            lp_exact_kernel_status: None,
            lp_full_status: None,
            lp_aggregate_status: None,
            lp_anchor_attempt_count: None,
            lp_anchor_lp_solution_count: None,
            lp_anchor_status_counts: BTreeMap::new(),
        }),
    }
}

fn source_qn_term_seed_expanded_support_elements(
    source: &CygvPathSupportTargetMonomialQnSource,
    dimension: usize,
    seed_set: &HashSet<Vec<i64>>,
) -> Result<Vec<Vec<i64>>, String> {
    let mut elements = source_qn_term_support_elements(source, dimension)?;
    let mut seen = elements.iter().cloned().collect::<HashSet<_>>();
    let mut seeds = seed_set.iter().cloned().collect::<Vec<_>>();
    seeds.sort();
    if seeds.is_empty() {
        return Ok(elements);
    }
    let base_elements = elements.clone();
    for element in base_elements {
        if element.iter().all(|&coordinate| coordinate == 0) {
            continue;
        }
        let Some(terms) = bounded_seed_decomposition(&element, &seeds, 4)? else {
            continue;
        };
        for diamond_element in decomposition_diamond_elements(&terms, &element)? {
            if seen.insert(diamond_element.clone()) {
                elements.push(diamond_element);
            }
        }
    }
    elements.sort();
    Ok(elements)
}

fn source_qn_term_provided_generator_probe_from_generators(
    source: &CygvPathSupportTargetMonomialQnSource,
    context: &ValidatedContext<'_>,
    generators: Vec<Vec<i64>>,
    max_degree: i128,
    computed_status: &str,
    error_label: &str,
    supporting_face_lp_options: &SupportingMoriFaceLpSearchOptions,
) -> Result<Option<CygvSourceQnTermSemigroupProbe>, String> {
    let source_curve = dense_from_sparse(&source.curve_nonzero, context.dimension)?;
    let generator_degree_counts =
        path_support_generator_degree_counts(&generators, context.grading)?;
    let generator_nonzero_sample = path_support_generator_nonzero_sample(&generators);
    let face_certificate = source_qn_term_generator_face_certificate(
        &generators,
        context,
        supporting_face_lp_options,
    )?;
    if generators.len() > CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT {
        return Ok(Some(CygvSourceQnTermSemigroupProbe {
            element_count: None,
            generator_count: Some(generators.len()),
            generator_degree_counts,
            generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
            generator_nonzero_sample,
            status: format!(
                "skipped_generator_limit_{CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT}"
            ),
            gv: None,
            error: None,
            qn_trace_polynomial_count: None,
            source_qn_trace_term_count: None,
            source_qn_trace_term_sample_complete: None,
            source_qn_trace_term_signature_sample: Vec::new(),
            parent_qn_comparison_status: None,
            generator_face_certificate_status: Some(face_certificate.status),
            generator_face_certificate_normal_nonzero: face_certificate.normal_nonzero,
            generator_face_certificate_zero_count: face_certificate.zero_count,
            generator_face_certificate_positive_count: face_certificate.positive_count,
            generator_face_certificate_lp_search_status: face_certificate.lp_search_status,
            generator_face_certificate_lp_exact_kernel_status: face_certificate
                .lp_exact_kernel_status,
            generator_face_certificate_lp_full_status: face_certificate.lp_full_status,
            generator_face_certificate_lp_aggregate_status: face_certificate.lp_aggregate_status,
            generator_face_certificate_lp_anchor_attempt_count: face_certificate
                .lp_anchor_attempt_count,
            generator_face_certificate_lp_anchor_lp_solution_count: face_certificate
                .lp_anchor_lp_solution_count,
            generator_face_certificate_lp_anchor_status_counts: face_certificate
                .lp_anchor_status_counts,
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            source_gw_coefficient_status: None,
            source_gw_instanton_coefficient: None,
            source_gw_candidate: None,
        }));
    }
    if context.q_matrix.is_empty() || context.q_cols == 0 {
        return Ok(Some(CygvSourceQnTermSemigroupProbe {
            element_count: None,
            generator_count: Some(generators.len()),
            generator_degree_counts,
            generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
            generator_nonzero_sample,
            status: "skipped_no_q_matrix".to_string(),
            gv: None,
            error: None,
            qn_trace_polynomial_count: None,
            source_qn_trace_term_count: None,
            source_qn_trace_term_sample_complete: None,
            source_qn_trace_term_signature_sample: Vec::new(),
            parent_qn_comparison_status: None,
            generator_face_certificate_status: Some(face_certificate.status),
            generator_face_certificate_normal_nonzero: face_certificate.normal_nonzero,
            generator_face_certificate_zero_count: face_certificate.zero_count,
            generator_face_certificate_positive_count: face_certificate.positive_count,
            generator_face_certificate_lp_search_status: face_certificate.lp_search_status,
            generator_face_certificate_lp_exact_kernel_status: face_certificate
                .lp_exact_kernel_status,
            generator_face_certificate_lp_full_status: face_certificate.lp_full_status,
            generator_face_certificate_lp_aggregate_status: face_certificate.lp_aggregate_status,
            generator_face_certificate_lp_anchor_attempt_count: face_certificate
                .lp_anchor_attempt_count,
            generator_face_certificate_lp_anchor_lp_solution_count: face_certificate
                .lp_anchor_lp_solution_count,
            generator_face_certificate_lp_anchor_status_counts: face_certificate
                .lp_anchor_status_counts,
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            source_gw_coefficient_status: None,
            source_gw_instanton_coefficient: None,
            source_gw_candidate: None,
        }));
    }
    if cfg!(panic = "abort") {
        return Ok(Some(CygvSourceQnTermSemigroupProbe {
            element_count: None,
            generator_count: Some(generators.len()),
            generator_degree_counts,
            generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
            generator_nonzero_sample,
            status: "hkty_unavailable_panic_abort".to_string(),
            gv: None,
            error: Some(
                "running cygv provided-generator HKTY requires a panic=unwind build for diagnostics"
                    .to_string(),
            ),
            qn_trace_polynomial_count: None,
            source_qn_trace_term_count: None,
            source_qn_trace_term_sample_complete: None,
            source_qn_trace_term_signature_sample: Vec::new(),
            parent_qn_comparison_status: None,
            generator_face_certificate_status: Some(face_certificate.status),
            generator_face_certificate_normal_nonzero: face_certificate.normal_nonzero,
            generator_face_certificate_zero_count: face_certificate.zero_count,
            generator_face_certificate_positive_count: face_certificate.positive_count,
            generator_face_certificate_lp_search_status: face_certificate.lp_search_status,
            generator_face_certificate_lp_exact_kernel_status: face_certificate
                .lp_exact_kernel_status,
            generator_face_certificate_lp_full_status: face_certificate.lp_full_status,
            generator_face_certificate_lp_aggregate_status: face_certificate.lp_aggregate_status,
            generator_face_certificate_lp_anchor_attempt_count: face_certificate
                .lp_anchor_attempt_count,
            generator_face_certificate_lp_anchor_lp_solution_count: face_certificate
                .lp_anchor_lp_solution_count,
            generator_face_certificate_lp_anchor_status_counts: face_certificate
                .lp_anchor_status_counts,
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            source_gw_coefficient_status: None,
            source_gw_instanton_coefficient: None,
            source_gw_candidate: None,
        }));
    }
    let max_degree = u32::try_from(max_degree)
        .map_err(|_| format!("source qN-term offset max degree {max_degree} does not fit u32"))?;
    let source_i32 = curve_i64_to_i32(&source_curve, "source qN-term offset-generator curve")?;
    let previous_panic_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let traced_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        compute_gv_invariants_with_provided_generators_qn_trace(
            &generators,
            context.grading,
            context.q_matrix,
            &context.intersection,
            None,
            Some(max_degree),
        )
    }));
    std::panic::set_hook(previous_panic_hook);

    let traced = match traced_result {
        Ok(Ok(traced)) => traced,
        Ok(Err(error)) => {
            let gw_diagnostic = path_support_gw_coefficient_diagnostic(
                &generators,
                context,
                max_degree,
                &source_i32,
            );
            return Ok(Some(CygvSourceQnTermSemigroupProbe {
                element_count: None,
                generator_count: Some(generators.len()),
                generator_degree_counts,
                generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
                generator_nonzero_sample,
                status: "hkty_error".to_string(),
                gv: None,
                error: Some(format!("{error_label} HKTY failed: {error}")),
                qn_trace_polynomial_count: None,
                source_qn_trace_term_count: None,
                source_qn_trace_term_sample_complete: None,
                source_qn_trace_term_signature_sample: Vec::new(),
                parent_qn_comparison_status: None,
                generator_face_certificate_status: Some(face_certificate.status),
                generator_face_certificate_normal_nonzero: face_certificate.normal_nonzero,
                generator_face_certificate_zero_count: face_certificate.zero_count,
                generator_face_certificate_positive_count: face_certificate.positive_count,
                generator_face_certificate_lp_search_status: face_certificate.lp_search_status,
                generator_face_certificate_lp_exact_kernel_status: face_certificate
                    .lp_exact_kernel_status,
                generator_face_certificate_lp_full_status: face_certificate.lp_full_status,
                generator_face_certificate_lp_aggregate_status: face_certificate
                    .lp_aggregate_status,
                generator_face_certificate_lp_anchor_attempt_count: face_certificate
                    .lp_anchor_attempt_count,
                generator_face_certificate_lp_anchor_lp_solution_count: face_certificate
                    .lp_anchor_lp_solution_count,
                generator_face_certificate_lp_anchor_status_counts: face_certificate
                    .lp_anchor_status_counts,
                gw_coefficient_trace_count: gw_diagnostic.trace_count,
                gw_noninteger_candidate_count: gw_diagnostic.noninteger_candidate_count,
                gw_noninteger_known_qn_history_status_counts: gw_diagnostic
                    .noninteger_known_qn_history_status_counts,
                gw_noninteger_source_class_status_counts: gw_diagnostic
                    .noninteger_source_class_status_counts,
                gw_noninteger_candidate_sample: gw_diagnostic.noninteger_candidate_sample,
                gw_coefficient_trace_error: gw_diagnostic.error,
                source_gw_coefficient_status: gw_diagnostic.target_status,
                source_gw_instanton_coefficient: gw_diagnostic.target_instanton_coefficient,
                source_gw_candidate: gw_diagnostic.target_gw_candidate,
            }));
        }
        Err(payload) => {
            let gw_diagnostic = path_support_gw_coefficient_diagnostic(
                &generators,
                context,
                max_degree,
                &source_i32,
            );
            return Ok(Some(CygvSourceQnTermSemigroupProbe {
                element_count: None,
                generator_count: Some(generators.len()),
                generator_degree_counts,
                generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
                generator_nonzero_sample,
                status: "hkty_panic".to_string(),
                gv: None,
                error: Some(format!(
                    "{error_label} HKTY panicked: {}",
                    panic_payload_message(payload.as_ref())
                )),
                qn_trace_polynomial_count: None,
                source_qn_trace_term_count: None,
                source_qn_trace_term_sample_complete: None,
                source_qn_trace_term_signature_sample: Vec::new(),
                parent_qn_comparison_status: None,
                generator_face_certificate_status: Some(face_certificate.status),
                generator_face_certificate_normal_nonzero: face_certificate.normal_nonzero,
                generator_face_certificate_zero_count: face_certificate.zero_count,
                generator_face_certificate_positive_count: face_certificate.positive_count,
                generator_face_certificate_lp_search_status: face_certificate.lp_search_status,
                generator_face_certificate_lp_exact_kernel_status: face_certificate
                    .lp_exact_kernel_status,
                generator_face_certificate_lp_full_status: face_certificate.lp_full_status,
                generator_face_certificate_lp_aggregate_status: face_certificate
                    .lp_aggregate_status,
                generator_face_certificate_lp_anchor_attempt_count: face_certificate
                    .lp_anchor_attempt_count,
                generator_face_certificate_lp_anchor_lp_solution_count: face_certificate
                    .lp_anchor_lp_solution_count,
                generator_face_certificate_lp_anchor_status_counts: face_certificate
                    .lp_anchor_status_counts,
                gw_coefficient_trace_count: gw_diagnostic.trace_count,
                gw_noninteger_candidate_count: gw_diagnostic.noninteger_candidate_count,
                gw_noninteger_known_qn_history_status_counts: gw_diagnostic
                    .noninteger_known_qn_history_status_counts,
                gw_noninteger_source_class_status_counts: gw_diagnostic
                    .noninteger_source_class_status_counts,
                gw_noninteger_candidate_sample: gw_diagnostic.noninteger_candidate_sample,
                gw_coefficient_trace_error: gw_diagnostic.error,
                source_gw_coefficient_status: gw_diagnostic.target_status,
                source_gw_instanton_coefficient: gw_diagnostic.target_instanton_coefficient,
                source_gw_candidate: gw_diagnostic.target_gw_candidate,
            }));
        }
    };

    let qn_trace_polynomial_count = traced.qn_trace.len();
    let source_qn = traced
        .qn_trace
        .iter()
        .find(|poly| poly.element == source_i32);
    let source_qn_trace_term_count = source_qn.map(|poly| poly.terms.len());
    let source_qn_trace_term_sample_complete =
        source_qn.map(|poly| poly.terms.len() <= CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT);
    let generated_terms = source_qn
        .map(qn_trace_poly_term_signatures)
        .unwrap_or_default();
    let parent_qn_comparison_status = Some(qn_term_signature_comparison_status(
        source.term_count,
        source.source_qn_term_sample_complete,
        &source.source_qn_term_signature_sample,
        source_qn_trace_term_count,
        source_qn_trace_term_sample_complete.unwrap_or(false),
        &generated_terms,
    ));
    let gv = traced
        .invariants
        .into_iter()
        .find_map(|(curve, value)| (curve == source_i32).then(|| value.to_string()))
        .unwrap_or_else(|| "0".to_string());
    let gw_diagnostic =
        path_support_gw_coefficient_diagnostic(&generators, context, max_degree, &source_i32);
    Ok(Some(CygvSourceQnTermSemigroupProbe {
        element_count: None,
        generator_count: Some(generators.len()),
        generator_degree_counts,
        generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
        generator_nonzero_sample,
        status: computed_status.to_string(),
        gv: Some(gv),
        error: None,
        qn_trace_polynomial_count: Some(qn_trace_polynomial_count),
        source_qn_trace_term_count,
        source_qn_trace_term_sample_complete,
        source_qn_trace_term_signature_sample: generated_terms,
        parent_qn_comparison_status,
        generator_face_certificate_status: Some(face_certificate.status),
        generator_face_certificate_normal_nonzero: face_certificate.normal_nonzero,
        generator_face_certificate_zero_count: face_certificate.zero_count,
        generator_face_certificate_positive_count: face_certificate.positive_count,
        generator_face_certificate_lp_search_status: face_certificate.lp_search_status,
        generator_face_certificate_lp_exact_kernel_status: face_certificate.lp_exact_kernel_status,
        generator_face_certificate_lp_full_status: face_certificate.lp_full_status,
        generator_face_certificate_lp_aggregate_status: face_certificate.lp_aggregate_status,
        generator_face_certificate_lp_anchor_attempt_count: face_certificate
            .lp_anchor_attempt_count,
        generator_face_certificate_lp_anchor_lp_solution_count: face_certificate
            .lp_anchor_lp_solution_count,
        generator_face_certificate_lp_anchor_status_counts: face_certificate
            .lp_anchor_status_counts,
        gw_coefficient_trace_count: gw_diagnostic.trace_count,
        gw_noninteger_candidate_count: gw_diagnostic.noninteger_candidate_count,
        gw_noninteger_known_qn_history_status_counts: gw_diagnostic
            .noninteger_known_qn_history_status_counts,
        gw_noninteger_source_class_status_counts: gw_diagnostic
            .noninteger_source_class_status_counts,
        gw_noninteger_candidate_sample: gw_diagnostic.noninteger_candidate_sample,
        gw_coefficient_trace_error: gw_diagnostic.error,
        source_gw_coefficient_status: gw_diagnostic.target_status,
        source_gw_instanton_coefficient: gw_diagnostic.target_instanton_coefficient,
        source_gw_candidate: gw_diagnostic.target_gw_candidate,
    }))
}

fn source_qn_term_semigroup_probe_from_elements(
    source: &CygvPathSupportTargetMonomialQnSource,
    context: &ValidatedContext<'_>,
    elements: Vec<Vec<i64>>,
    computed_status: &str,
    error_label: &str,
) -> Result<Option<CygvSourceQnTermSemigroupProbe>, String> {
    let source_curve = dense_from_sparse(&source.curve_nonzero, context.dimension)?;
    if elements.len() > CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT {
        return Ok(Some(CygvSourceQnTermSemigroupProbe {
            element_count: Some(elements.len()),
            generator_count: None,
            generator_degree_counts: BTreeMap::new(),
            generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
            generator_nonzero_sample: Vec::new(),
            status: format!(
                "skipped_element_limit_{CYGV_BOUNDED_DECOMPOSITION_DIAMOND_ELEMENT_LIMIT}"
            ),
            gv: None,
            error: None,
            qn_trace_polynomial_count: None,
            source_qn_trace_term_count: None,
            source_qn_trace_term_sample_complete: None,
            source_qn_trace_term_signature_sample: Vec::new(),
            parent_qn_comparison_status: None,
            generator_face_certificate_status: None,
            generator_face_certificate_normal_nonzero: None,
            generator_face_certificate_zero_count: None,
            generator_face_certificate_positive_count: None,
            generator_face_certificate_lp_search_status: None,
            generator_face_certificate_lp_exact_kernel_status: None,
            generator_face_certificate_lp_full_status: None,
            generator_face_certificate_lp_aggregate_status: None,
            generator_face_certificate_lp_anchor_attempt_count: None,
            generator_face_certificate_lp_anchor_lp_solution_count: None,
            generator_face_certificate_lp_anchor_status_counts: BTreeMap::new(),
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            source_gw_coefficient_status: None,
            source_gw_instanton_coefficient: None,
            source_gw_candidate: None,
        }));
    }
    if context.q_matrix.is_empty() || context.q_cols == 0 {
        return Ok(Some(CygvSourceQnTermSemigroupProbe {
            element_count: Some(elements.len()),
            generator_count: None,
            generator_degree_counts: BTreeMap::new(),
            generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
            generator_nonzero_sample: Vec::new(),
            status: "skipped_no_q_matrix".to_string(),
            gv: None,
            error: None,
            qn_trace_polynomial_count: None,
            source_qn_trace_term_count: None,
            source_qn_trace_term_sample_complete: None,
            source_qn_trace_term_signature_sample: Vec::new(),
            parent_qn_comparison_status: None,
            generator_face_certificate_status: None,
            generator_face_certificate_normal_nonzero: None,
            generator_face_certificate_zero_count: None,
            generator_face_certificate_positive_count: None,
            generator_face_certificate_lp_search_status: None,
            generator_face_certificate_lp_exact_kernel_status: None,
            generator_face_certificate_lp_full_status: None,
            generator_face_certificate_lp_aggregate_status: None,
            generator_face_certificate_lp_anchor_attempt_count: None,
            generator_face_certificate_lp_anchor_lp_solution_count: None,
            generator_face_certificate_lp_anchor_status_counts: BTreeMap::new(),
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            source_gw_coefficient_status: None,
            source_gw_instanton_coefficient: None,
            source_gw_candidate: None,
        }));
    }
    if cfg!(panic = "abort") {
        return Ok(Some(CygvSourceQnTermSemigroupProbe {
            element_count: Some(elements.len()),
            generator_count: None,
            generator_degree_counts: BTreeMap::new(),
            generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
            generator_nonzero_sample: Vec::new(),
            status: "hkty_unavailable_panic_abort".to_string(),
            gv: None,
            error: Some(
                "running cygv explicit-semigroup HKTY requires a panic=unwind build for diagnostics"
                    .to_string(),
            ),
            qn_trace_polynomial_count: None,
            source_qn_trace_term_count: None,
            source_qn_trace_term_sample_complete: None,
            source_qn_trace_term_signature_sample: Vec::new(),
            parent_qn_comparison_status: None,
            generator_face_certificate_status: None,
            generator_face_certificate_normal_nonzero: None,
            generator_face_certificate_zero_count: None,
            generator_face_certificate_positive_count: None,
            generator_face_certificate_lp_search_status: None,
            generator_face_certificate_lp_exact_kernel_status: None,
            generator_face_certificate_lp_full_status: None,
            generator_face_certificate_lp_aggregate_status: None,
            generator_face_certificate_lp_anchor_attempt_count: None,
            generator_face_certificate_lp_anchor_lp_solution_count: None,
            generator_face_certificate_lp_anchor_status_counts: BTreeMap::new(),
            gw_coefficient_trace_count: None,
            gw_noninteger_candidate_count: None,
            gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            gw_noninteger_source_class_status_counts: BTreeMap::new(),
            gw_noninteger_candidate_sample: Vec::new(),
            gw_coefficient_trace_error: None,
            source_gw_coefficient_status: None,
            source_gw_instanton_coefficient: None,
            source_gw_candidate: None,
        }));
    }

    let source_i32 = curve_i64_to_i32(&source_curve, "source qN-term semigroup curve")?;
    let previous_panic_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let traced_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        compute_gv_invariants_with_explicit_semigroup_qn_trace(
            &elements,
            context.grading,
            context.q_matrix,
            &context.intersection,
        )
    }));
    std::panic::set_hook(previous_panic_hook);

    let traced = match traced_result {
        Ok(Ok(traced)) => traced,
        Ok(Err(error)) => {
            return Ok(Some(CygvSourceQnTermSemigroupProbe {
                element_count: Some(elements.len()),
                generator_count: None,
                generator_degree_counts: BTreeMap::new(),
                generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
                generator_nonzero_sample: Vec::new(),
                status: "hkty_error".to_string(),
                gv: None,
                error: Some(format!("{error_label} HKTY failed: {error}")),
                qn_trace_polynomial_count: None,
                source_qn_trace_term_count: None,
                source_qn_trace_term_sample_complete: None,
                source_qn_trace_term_signature_sample: Vec::new(),
                parent_qn_comparison_status: None,
                generator_face_certificate_status: None,
                generator_face_certificate_normal_nonzero: None,
                generator_face_certificate_zero_count: None,
                generator_face_certificate_positive_count: None,
                generator_face_certificate_lp_search_status: None,
                generator_face_certificate_lp_exact_kernel_status: None,
                generator_face_certificate_lp_full_status: None,
                generator_face_certificate_lp_aggregate_status: None,
                generator_face_certificate_lp_anchor_attempt_count: None,
                generator_face_certificate_lp_anchor_lp_solution_count: None,
                generator_face_certificate_lp_anchor_status_counts: BTreeMap::new(),
                gw_coefficient_trace_count: None,
                gw_noninteger_candidate_count: None,
                gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
                gw_noninteger_source_class_status_counts: BTreeMap::new(),
                gw_noninteger_candidate_sample: Vec::new(),
                gw_coefficient_trace_error: None,
                source_gw_coefficient_status: None,
                source_gw_instanton_coefficient: None,
                source_gw_candidate: None,
            }));
        }
        Err(payload) => {
            return Ok(Some(CygvSourceQnTermSemigroupProbe {
                element_count: Some(elements.len()),
                generator_count: None,
                generator_degree_counts: BTreeMap::new(),
                generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
                generator_nonzero_sample: Vec::new(),
                status: "hkty_panic".to_string(),
                gv: None,
                error: Some(format!(
                    "{error_label} HKTY panicked: {}",
                    panic_payload_message(payload.as_ref())
                )),
                qn_trace_polynomial_count: None,
                source_qn_trace_term_count: None,
                source_qn_trace_term_sample_complete: None,
                source_qn_trace_term_signature_sample: Vec::new(),
                parent_qn_comparison_status: None,
                generator_face_certificate_status: None,
                generator_face_certificate_normal_nonzero: None,
                generator_face_certificate_zero_count: None,
                generator_face_certificate_positive_count: None,
                generator_face_certificate_lp_search_status: None,
                generator_face_certificate_lp_exact_kernel_status: None,
                generator_face_certificate_lp_full_status: None,
                generator_face_certificate_lp_aggregate_status: None,
                generator_face_certificate_lp_anchor_attempt_count: None,
                generator_face_certificate_lp_anchor_lp_solution_count: None,
                generator_face_certificate_lp_anchor_status_counts: BTreeMap::new(),
                gw_coefficient_trace_count: None,
                gw_noninteger_candidate_count: None,
                gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
                gw_noninteger_source_class_status_counts: BTreeMap::new(),
                gw_noninteger_candidate_sample: Vec::new(),
                gw_coefficient_trace_error: None,
                source_gw_coefficient_status: None,
                source_gw_instanton_coefficient: None,
                source_gw_candidate: None,
            }));
        }
    };

    let qn_trace_polynomial_count = traced.qn_trace.len();
    let source_qn = traced
        .qn_trace
        .iter()
        .find(|poly| poly.element == source_i32);
    let source_qn_trace_term_count = source_qn.map(|poly| poly.terms.len());
    let source_qn_trace_term_sample_complete =
        source_qn.map(|poly| poly.terms.len() <= CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT);
    let generated_terms = source_qn
        .map(qn_trace_poly_term_signatures)
        .unwrap_or_default();
    let parent_qn_comparison_status = Some(qn_term_signature_comparison_status(
        source.term_count,
        source.source_qn_term_sample_complete,
        &source.source_qn_term_signature_sample,
        source_qn_trace_term_count,
        source_qn
            .map(|poly| poly.terms.len() <= CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT)
            .unwrap_or(false),
        &generated_terms,
    ));
    let gv = traced
        .invariants
        .into_iter()
        .find_map(|(curve, value)| (curve == source_i32).then(|| value.to_string()))
        .unwrap_or_else(|| "0".to_string());
    Ok(Some(CygvSourceQnTermSemigroupProbe {
        element_count: Some(elements.len()),
        generator_count: None,
        generator_degree_counts: BTreeMap::new(),
        generator_sample_limit: CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT,
        generator_nonzero_sample: Vec::new(),
        status: computed_status.to_string(),
        gv: Some(gv),
        error: None,
        qn_trace_polynomial_count: Some(qn_trace_polynomial_count),
        source_qn_trace_term_count,
        source_qn_trace_term_sample_complete,
        source_qn_trace_term_signature_sample: generated_terms,
        parent_qn_comparison_status,
        generator_face_certificate_status: None,
        generator_face_certificate_normal_nonzero: None,
        generator_face_certificate_zero_count: None,
        generator_face_certificate_positive_count: None,
        generator_face_certificate_lp_search_status: None,
        generator_face_certificate_lp_exact_kernel_status: None,
        generator_face_certificate_lp_full_status: None,
        generator_face_certificate_lp_aggregate_status: None,
        generator_face_certificate_lp_anchor_attempt_count: None,
        generator_face_certificate_lp_anchor_lp_solution_count: None,
        generator_face_certificate_lp_anchor_status_counts: BTreeMap::new(),
        gw_coefficient_trace_count: None,
        gw_noninteger_candidate_count: None,
        gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
        gw_noninteger_source_class_status_counts: BTreeMap::new(),
        gw_noninteger_candidate_sample: Vec::new(),
        gw_coefficient_trace_error: None,
        source_gw_coefficient_status: None,
        source_gw_instanton_coefficient: None,
        source_gw_candidate: None,
    }))
}

fn qn_trace_poly_term_signatures(
    poly: &CygvQnTracePolynomial,
) -> Vec<CygvPathSupportQnTraceTermSignature> {
    poly.terms
        .iter()
        .take(CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT)
        .map(|term| CygvPathSupportQnTraceTermSignature {
            exponent_nonzero: sparse_from_i32_dense(&term.exponent),
            coefficient: term.coefficient.clone(),
        })
        .collect()
}

fn qn_term_signature_comparison_status(
    expected_term_count: usize,
    expected_sample_complete: bool,
    expected_terms: &[CygvPathSupportQnTraceTermSignature],
    actual_term_count: Option<usize>,
    actual_sample_complete: bool,
    actual_terms: &[CygvPathSupportQnTraceTermSignature],
) -> String {
    let Some(actual_term_count) = actual_term_count else {
        return "missing_in_source_qn_term_semigroup".to_string();
    };
    if expected_term_count != actual_term_count {
        return "different_qn_term_counts".to_string();
    }
    if !expected_sample_complete || !actual_sample_complete {
        return "same_count_but_sample_truncated".to_string();
    }
    if qn_term_signature_multisets_match(expected_terms, actual_terms) {
        "same_qn_term_signatures".to_string()
    } else {
        "same_count_different_qn_term_signatures".to_string()
    }
}

fn qn_term_signature_multisets_match(
    left: &[CygvPathSupportQnTraceTermSignature],
    right: &[CygvPathSupportQnTraceTermSignature],
) -> bool {
    qn_term_signature_multiset_difference(left, right, 1).is_empty()
        && qn_term_signature_multiset_difference(right, left, 1).is_empty()
}

fn target_monomial_qn_source_diamond_parent_qn_comparison_status_counts(
    sources: &[CygvPathSupportTargetMonomialQnSource],
) -> BTreeMap<String, usize> {
    optional_status_counts(
        sources.iter().map(|source| {
            source
                .source_bounded_diamond_parent_qn_comparison_status
                .as_deref()
        }),
        "not_compared",
    )
}

fn path_support_target_li2_subtraction_balance(
    sources: &[CygvPathSupportTargetMonomialQnSource],
    target_degree: i128,
    target_instanton_coefficient: Option<&String>,
    target_pivot_component: Option<i32>,
) -> Result<CygvPathSupportTargetLi2SubtractionBalance, String> {
    let mut subtraction_sum = MalachiteRational::from(0);
    let lower_sources = sources
        .iter()
        .filter(|source| i128::from(source.degree) < target_degree)
        .collect::<Vec<_>>();
    for source in &lower_sources {
        let Some(coefficient) = source.pivot_li2_subtraction_coefficient.as_deref() else {
            return Ok(CygvPathSupportTargetLi2SubtractionBalance {
                source_count: lower_sources.len(),
                subtraction_sum: None,
                reconstructed_pre_subtraction_instanton_coefficient: None,
                reconstructed_pre_subtraction_gv_candidate: None,
                status: "missing_lower_pivot_li2_subtraction_coefficient".to_string(),
            });
        };
        subtraction_sum += parse_rational(coefficient)?;
    }

    let Some(target_instanton_coefficient) = target_instanton_coefficient else {
        return Ok(CygvPathSupportTargetLi2SubtractionBalance {
            source_count: lower_sources.len(),
            subtraction_sum: Some(subtraction_sum.to_string()),
            reconstructed_pre_subtraction_instanton_coefficient: None,
            reconstructed_pre_subtraction_gv_candidate: None,
            status: "missing_target_instanton_coefficient".to_string(),
        });
    };
    let target_instanton_coefficient = parse_rational(target_instanton_coefficient)?;
    let reconstructed_pre_subtraction_instanton_coefficient =
        target_instanton_coefficient + subtraction_sum.clone();
    let Some(target_pivot_component) = target_pivot_component else {
        return Ok(CygvPathSupportTargetLi2SubtractionBalance {
            source_count: lower_sources.len(),
            subtraction_sum: Some(subtraction_sum.to_string()),
            reconstructed_pre_subtraction_instanton_coefficient: Some(
                reconstructed_pre_subtraction_instanton_coefficient.to_string(),
            ),
            reconstructed_pre_subtraction_gv_candidate: None,
            status: "missing_target_pivot_component".to_string(),
        });
    };
    if target_pivot_component == 0 {
        return Ok(CygvPathSupportTargetLi2SubtractionBalance {
            source_count: lower_sources.len(),
            subtraction_sum: Some(subtraction_sum.to_string()),
            reconstructed_pre_subtraction_instanton_coefficient: Some(
                reconstructed_pre_subtraction_instanton_coefficient.to_string(),
            ),
            reconstructed_pre_subtraction_gv_candidate: None,
            status: "zero_target_pivot_component".to_string(),
        });
    }
    let reconstructed_pre_subtraction_gv_candidate =
        reconstructed_pre_subtraction_instanton_coefficient.clone()
            / MalachiteRational::from(Integer::from(target_pivot_component));
    Ok(CygvPathSupportTargetLi2SubtractionBalance {
        source_count: lower_sources.len(),
        subtraction_sum: Some(subtraction_sum.to_string()),
        reconstructed_pre_subtraction_instanton_coefficient: Some(
            reconstructed_pre_subtraction_instanton_coefficient.to_string(),
        ),
        reconstructed_pre_subtraction_gv_candidate: Some(
            reconstructed_pre_subtraction_gv_candidate.to_string(),
        ),
        status: "reconstructed_from_target_readout_plus_li2_subtractions".to_string(),
    })
}

fn path_support_formula_balance(
    target_instanton_coefficient: Option<&String>,
    target_pivot_component: Option<i32>,
    lower_pivot_li2_subtraction_sum: Option<&String>,
    reconstructed_pre_subtraction_gv_candidate: Option<&String>,
    expected_formula_sum: Option<&String>,
) -> Result<CygvPathSupportFormulaBalance, String> {
    let Some(expected_formula_sum) = expected_formula_sum else {
        return Ok(CygvPathSupportFormulaBalance {
            required_pivot_li2_subtraction_sum: None,
            missing_pivot_li2_subtraction_sum: None,
            gv_candidate_delta: None,
            status: "missing_formula_sum".to_string(),
        });
    };
    let Some(target_instanton_coefficient) = target_instanton_coefficient else {
        return Ok(CygvPathSupportFormulaBalance {
            required_pivot_li2_subtraction_sum: None,
            missing_pivot_li2_subtraction_sum: None,
            gv_candidate_delta: None,
            status: "missing_target_instanton_coefficient".to_string(),
        });
    };
    let Some(target_pivot_component) = target_pivot_component else {
        return Ok(CygvPathSupportFormulaBalance {
            required_pivot_li2_subtraction_sum: None,
            missing_pivot_li2_subtraction_sum: None,
            gv_candidate_delta: None,
            status: "missing_target_pivot_component".to_string(),
        });
    };
    if target_pivot_component == 0 {
        return Ok(CygvPathSupportFormulaBalance {
            required_pivot_li2_subtraction_sum: None,
            missing_pivot_li2_subtraction_sum: None,
            gv_candidate_delta: None,
            status: "zero_target_pivot_component".to_string(),
        });
    }
    let Some(lower_pivot_li2_subtraction_sum) = lower_pivot_li2_subtraction_sum else {
        return Ok(CygvPathSupportFormulaBalance {
            required_pivot_li2_subtraction_sum: None,
            missing_pivot_li2_subtraction_sum: None,
            gv_candidate_delta: None,
            status: "missing_lower_pivot_li2_subtraction_sum".to_string(),
        });
    };

    let expected_formula_sum = parse_rational(expected_formula_sum)?;
    let target_instanton_coefficient = parse_rational(target_instanton_coefficient)?;
    let lower_pivot_li2_subtraction_sum = parse_rational(lower_pivot_li2_subtraction_sum)?;
    let required = expected_formula_sum.clone()
        * MalachiteRational::from(Integer::from(target_pivot_component))
        - target_instanton_coefficient;
    let missing = required.clone() - lower_pivot_li2_subtraction_sum;
    let gv_candidate_delta = reconstructed_pre_subtraction_gv_candidate
        .map(|candidate| {
            parse_rational(candidate).map(|candidate| expected_formula_sum - candidate)
        })
        .transpose()?;
    let status = if missing == 0 {
        "formula_pivot_subtraction_balanced"
    } else {
        "formula_pivot_subtraction_mismatch"
    };
    Ok(CygvPathSupportFormulaBalance {
        required_pivot_li2_subtraction_sum: Some(required.to_string()),
        missing_pivot_li2_subtraction_sum: Some(missing.to_string()),
        gv_candidate_delta: gv_candidate_delta.map(|value| value.to_string()),
        status: status.to_string(),
    })
}

fn sparse_from_i32_dense(values: &[i32]) -> Vec<(usize, i64)> {
    values
        .iter()
        .enumerate()
        .filter_map(|(idx, &value)| (value != 0).then_some((idx, i64::from(value))))
        .collect()
}

fn path_support_uncovered_source_ray_summaries(
    targets: &[TargetReport],
) -> Vec<CygvPathSupportSourceRaySummary> {
    let mut summaries: BTreeMap<Vec<(usize, i64)>, CygvPathSupportSourceRaySummaryBuilder> =
        BTreeMap::new();
    for target in targets {
        let Some(probe) = target.cygv_path_history_probe.as_ref() else {
            continue;
        };
        for lookup in &probe.path_support_lookup_sample {
            add_path_support_uncovered_source_ray_lookup(&mut summaries, target.index, lookup);
        }
    }
    let mut out = summaries
        .into_values()
        .map(|builder| CygvPathSupportSourceRaySummary {
            degree: builder.degree,
            occurrence_count: builder.occurrences.len(),
            known_qn_history_status_counts: builder.known_qn_history_status_counts,
            path_support_lookup_status_counts: builder.path_support_lookup_status_counts,
            path_support_gv_counts: builder.path_support_gv_counts,
            uncovered_source_ray_origin_circuit_pattern: builder
                .uncovered_source_ray_origin_circuit_pattern,
            uncovered_source_ray_exact_kind: builder.uncovered_source_ray_exact_kind,
            uncovered_source_ray_cms_check_status_counts: builder
                .uncovered_source_ray_cms_check_status_counts,
            uncovered_source_ray_cms_solution_summaries: builder
                .uncovered_source_ray_cms_solution_summaries,
            uncovered_source_ray_local_charge_signature: builder
                .uncovered_source_ray_local_charge_signature,
            uncovered_source_ray_local_cygv_readiness_counts: builder
                .uncovered_source_ray_local_cygv_readiness_counts,
            uncovered_source_ray_local_missing_input_counts: builder
                .uncovered_source_ray_local_missing_input_counts,
            source_ray_ambient_nonzero: builder.source_ray_ambient_nonzero,
            curve_nonzero: builder.curve_nonzero,
            occurrences: builder.occurrences,
        })
        .collect::<Vec<_>>();
    out.sort_by(|lhs, rhs| {
        lhs.degree
            .cmp(&rhs.degree)
            .then_with(|| lhs.curve_nonzero.cmp(&rhs.curve_nonzero))
    });
    out
}

fn add_path_support_uncovered_source_ray_lookup(
    summaries: &mut BTreeMap<Vec<(usize, i64)>, CygvPathSupportSourceRaySummaryBuilder>,
    target_index: usize,
    lookup: &CygvPathSupportLookup,
) {
    if lookup.source_class_status != "source_ray_not_toric_covered" {
        return;
    }
    let entry = summaries
        .entry(lookup.curve_nonzero.clone())
        .or_insert_with(|| CygvPathSupportSourceRaySummaryBuilder {
            degree: lookup.degree,
            known_qn_history_status_counts: BTreeMap::new(),
            path_support_lookup_status_counts: BTreeMap::new(),
            path_support_gv_counts: BTreeMap::new(),
            uncovered_source_ray_origin_circuit_pattern: lookup
                .matching_uncovered_source_ray_origin_circuit_pattern
                .clone(),
            uncovered_source_ray_exact_kind: lookup
                .matching_uncovered_source_ray_exact_kind
                .clone(),
            uncovered_source_ray_cms_check_status_counts: BTreeMap::new(),
            uncovered_source_ray_cms_solution_summaries: Vec::new(),
            uncovered_source_ray_local_charge_signature: lookup
                .matching_uncovered_source_ray_local_charge_signature
                .clone(),
            uncovered_source_ray_local_cygv_readiness_counts: BTreeMap::new(),
            uncovered_source_ray_local_missing_input_counts: BTreeMap::new(),
            source_ray_ambient_nonzero: lookup
                .source_ray_ambient_nonzero
                .clone()
                .unwrap_or_default(),
            curve_nonzero: lookup.curve_nonzero.clone(),
            occurrences: Vec::new(),
        });
    debug_assert_eq!(entry.degree, lookup.degree);
    if entry.uncovered_source_ray_origin_circuit_pattern.is_none() {
        entry.uncovered_source_ray_origin_circuit_pattern = lookup
            .matching_uncovered_source_ray_origin_circuit_pattern
            .clone();
    }
    if entry.uncovered_source_ray_exact_kind.is_none() {
        entry.uncovered_source_ray_exact_kind =
            lookup.matching_uncovered_source_ray_exact_kind.clone();
    }
    if entry.uncovered_source_ray_local_charge_signature.is_none() {
        entry.uncovered_source_ray_local_charge_signature = lookup
            .matching_uncovered_source_ray_local_charge_signature
            .clone();
    }
    for (status, count) in &lookup.matching_uncovered_source_ray_cms_check_status_counts {
        *entry
            .uncovered_source_ray_cms_check_status_counts
            .entry(status.clone())
            .or_insert(0) += count;
    }
    for solution in &lookup.matching_uncovered_source_ray_cms_solution_summaries {
        if !entry
            .uncovered_source_ray_cms_solution_summaries
            .contains(solution)
        {
            entry
                .uncovered_source_ray_cms_solution_summaries
                .push(solution.clone());
        }
    }
    entry.uncovered_source_ray_cms_solution_summaries.sort();
    entry.uncovered_source_ray_cms_solution_summaries.dedup();
    if let Some(readiness) = &lookup.matching_uncovered_source_ray_local_cygv_readiness {
        *entry
            .uncovered_source_ray_local_cygv_readiness_counts
            .entry(readiness.clone())
            .or_insert(0) += 1;
    }
    for input in &lookup.matching_uncovered_source_ray_local_missing_inputs {
        *entry
            .uncovered_source_ray_local_missing_input_counts
            .entry(input.clone())
            .or_insert(0) += 1;
    }
    *entry
        .known_qn_history_status_counts
        .entry(lookup.known_qn_history_status.clone())
        .or_insert(0) += 1;
    *entry
        .path_support_lookup_status_counts
        .entry(lookup.path_support_lookup_status.clone())
        .or_insert(0) += 1;
    *entry
        .path_support_gv_counts
        .entry(
            lookup
                .path_support_gv
                .clone()
                .unwrap_or_else(|| "missing_path_support_gv".to_string()),
        )
        .or_insert(0) += 1;
    entry.occurrences.push(CygvPathSupportSourceRayOccurrence {
        target_index,
        candidate_index: lookup.candidate_index,
        side: lookup.side.clone(),
    });
}

