fn path_candidate_support(
    target: &[i64],
    candidates: &[CygvPathPredecessorCandidate],
) -> HashSet<usize> {
    let mut support = sparse_from_dense(target)
        .into_iter()
        .map(|(idx, _)| idx)
        .collect::<HashSet<_>>();
    for candidate in candidates {
        extend_support_from_sparse(&mut support, &candidate.predecessor_nonzero);
        extend_support_from_sparse(&mut support, &candidate.difference_nonzero);
        if let Some(decomposition) = candidate.predecessor_first_generation_seed_sum.as_ref() {
            extend_support_from_seed_sum(&mut support, decomposition);
        }
        if let Some(decomposition) = candidate.difference_first_generation_seed_sum.as_ref() {
            extend_support_from_seed_sum(&mut support, decomposition);
        }
    }
    support
}

fn extend_support_from_seed_sum(
    support: &mut HashSet<usize>,
    decomposition: &CygvSeedSumDecomposition,
) {
    extend_support_from_sparse(support, &decomposition.reduced_seed_nonzero);
    extend_support_from_sparse(support, &decomposition.seed_nonzero);
    if let Some(pair) = decomposition.seed_pair_reduction_sum.as_ref() {
        extend_support_from_sparse(support, &pair.lhs_nonzero);
        extend_support_from_sparse(support, &pair.rhs_nonzero);
    }
}

fn extend_support_from_sparse(support: &mut HashSet<usize>, sparse: &[(usize, i64)]) {
    for &(idx, value) in sparse {
        if value != 0 {
            support.insert(idx);
        }
    }
}

fn pair_expanded_lower_seed_probe(
    lower_seed_decomposition: &LowerSeedDecompositionProbe,
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
    max_terms: usize,
    max_depth: usize,
) -> PairExpandedLowerSeedProbe {
    let Some(terms) = lower_seed_decomposition.terms.as_deref() else {
        return PairExpandedLowerSeedProbe {
            status: "skipped_no_lower_seed_decomposition".to_string(),
            term_count: None,
            terms_nonzero: None,
            terms: None,
            error: lower_seed_decomposition.error.clone(),
        };
    };
    match pair_expand_terms_to_reduced_seeds(
        terms,
        seed_set,
        reduced_seed_set,
        max_terms,
        max_depth,
    ) {
        Ok(Some(expanded_terms)) => PairExpandedLowerSeedProbe {
            status: "expanded_to_pair_reduced_seed_terms".to_string(),
            term_count: Some(expanded_terms.len()),
            terms_nonzero: Some(
                expanded_terms
                    .iter()
                    .map(|term| sparse_from_dense(term))
                    .collect(),
            ),
            terms: Some(expanded_terms),
            error: None,
        },
        Ok(None) => PairExpandedLowerSeedProbe {
            status: "already_pair_reduced_seed_terms".to_string(),
            term_count: Some(terms.len()),
            terms_nonzero: Some(terms.iter().map(|term| sparse_from_dense(term)).collect()),
            terms: Some(terms.to_vec()),
            error: None,
        },
        Err(error) => PairExpandedLowerSeedProbe {
            status: "error".to_string(),
            term_count: None,
            terms_nonzero: None,
            terms: None,
            error: Some(error),
        },
    }
}

fn pair_expand_terms_to_reduced_seeds(
    terms: &[Vec<i64>],
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
    max_terms: usize,
    max_depth: usize,
) -> Result<Option<Vec<Vec<i64>>>, String> {
    let mut expanded = Vec::new();
    let mut changed = false;
    for term in terms {
        let mut term_expansion = Vec::new();
        pair_expand_seed_to_reduced_terms(
            term,
            seed_set,
            reduced_seed_set,
            max_depth,
            &mut term_expansion,
        )?;
        if term_expansion.len() != 1 || term_expansion.first() != Some(term) {
            changed = true;
        }
        expanded.extend(term_expansion);
        if expanded.len() > max_terms {
            return Err(format!(
                "pair-expanded lower-seed decomposition exceeds term limit {max_terms}"
            ));
        }
    }
    if !changed {
        return Ok(None);
    }
    Ok(Some(sorted_decomposition(expanded)))
}

fn pair_expand_seed_to_reduced_terms(
    seed: &[i64],
    seed_set: &HashSet<Vec<i64>>,
    reduced_seed_set: &HashSet<Vec<i64>>,
    remaining_depth: usize,
    out: &mut Vec<Vec<i64>>,
) -> Result<(), String> {
    if reduced_seed_set.contains(seed) {
        out.push(seed.to_vec());
        return Ok(());
    }
    if remaining_depth == 0 {
        out.push(seed.to_vec());
        return Ok(());
    }
    let Some((lhs, rhs)) = seed_pair_reduction_terms(seed, seed_set)? else {
        out.push(seed.to_vec());
        return Ok(());
    };
    pair_expand_seed_to_reduced_terms(&lhs, seed_set, reduced_seed_set, remaining_depth - 1, out)?;
    pair_expand_seed_to_reduced_terms(&rhs, seed_set, reduced_seed_set, remaining_depth - 1, out)?;
    Ok(())
}

fn seed_pair_reduction_terms(
    seed: &[i64],
    seed_set: &HashSet<Vec<i64>>,
) -> Result<Option<(Vec<i64>, Vec<i64>)>, String> {
    let mut sorted_seeds = seed_set.iter().collect::<Vec<_>>();
    sorted_seeds.sort();
    for lhs in sorted_seeds {
        let rhs = checked_vector_difference(seed, lhs)?;
        if seed_set.contains(&rhs) {
            return Ok(Some((lhs.clone(), rhs)));
        }
    }
    Ok(None)
}

fn lower_seed_diamond_probe_inner(
    target: &[i64],
    terms: &[Vec<i64>],
    context: &ValidatedContext<'_>,
    element_limit: usize,
) -> Result<LowerSeedDiamondProbe, String> {
    let elements = decomposition_diamond_elements(terms, target)?;
    if elements.len() > element_limit {
        return Ok(LowerSeedDiamondProbe {
            status: Some(format!("skipped_element_limit_{element_limit}")),
            element_count: Some(elements.len()),
            gv: None,
            error: None,
        });
    }
    if cfg!(panic = "abort") {
        return Ok(LowerSeedDiamondProbe {
            status: Some("hkty_unavailable_panic_abort".to_string()),
            element_count: Some(elements.len()),
            gv: None,
            error: Some(
                "running cygv explicit-semigroup HKTY requires a panic=unwind build for diagnostics"
                    .to_string(),
            ),
        });
    }
    let target_i32 = target
        .iter()
        .map(|&value| {
            i32::try_from(value).map_err(|_| "target coordinate does not fit in i32".to_string())
        })
        .collect::<Result<Vec<_>, _>>()?;
    let previous_panic_hook = std::panic::take_hook();
    std::panic::set_hook(Box::new(|_| {}));
    let gvs_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        compute_gv_invariants_with_explicit_semigroup(
            &elements,
            context.grading,
            context.q_matrix,
            &context.intersection,
        )
    }));
    std::panic::set_hook(previous_panic_hook);

    let gvs = match gvs_result {
        Ok(Ok(gvs)) => gvs,
        Ok(Err(error)) => {
            return Ok(LowerSeedDiamondProbe {
                status: Some("hkty_error".to_string()),
                element_count: Some(elements.len()),
                gv: None,
                error: Some(format!("explicit-semigroup cygv HKTY failed: {error}")),
            });
        }
        Err(payload) => {
            return Ok(LowerSeedDiamondProbe {
                status: Some("hkty_panic".to_string()),
                element_count: Some(elements.len()),
                gv: None,
                error: Some(format!(
                    "explicit-semigroup cygv HKTY panicked: {}",
                    panic_payload_message(payload.as_ref())
                )),
            });
        }
    };
    let gv = gvs
        .into_iter()
        .find_map(|(curve, value)| (curve == target_i32).then(|| value.to_string()))
        .unwrap_or_else(|| "0".to_string());
    Ok(LowerSeedDiamondProbe {
        status: Some("computed_lower_seed_decomposition_diamond".to_string()),
        element_count: Some(elements.len()),
        gv: Some(gv),
        error: None,
    })
}

fn bounded_seed_decomposition(
    target: &[i64],
    seeds: &[Vec<i64>],
    max_terms: usize,
) -> Result<Option<Vec<Vec<i64>>>, String> {
    bounded_seed_decomposition_with_stats(target, seeds, max_terms).map(|(terms, _stats)| terms)
}

#[cfg(test)]
fn bounded_seed_decomposition_with_positive_grading(
    target: &[i64],
    seeds: &[Vec<i64>],
    max_terms: usize,
    grading: &[i64],
) -> Result<Option<Vec<Vec<i64>>>, String> {
    bounded_seed_decomposition_with_positive_grading_and_stats(target, seeds, max_terms, grading)
        .map(|(terms, _stats)| terms)
}

fn bounded_seed_decomposition_with_stats(
    target: &[i64],
    seeds: &[Vec<i64>],
    max_terms: usize,
) -> Result<(Option<Vec<Vec<i64>>>, LowerSeedDecompositionSearchStats), String> {
    bounded_seed_decomposition_impl(target, seeds, max_terms, None)
}

fn bounded_seed_decomposition_with_positive_grading_and_stats(
    target: &[i64],
    seeds: &[Vec<i64>],
    max_terms: usize,
    grading: &[i64],
) -> Result<(Option<Vec<Vec<i64>>>, LowerSeedDecompositionSearchStats), String> {
    bounded_seed_decomposition_impl(target, seeds, max_terms, Some(grading))
}

fn bounded_seed_decomposition_impl(
    target: &[i64],
    seeds: &[Vec<i64>],
    max_terms: usize,
    positive_grading: Option<&[i64]>,
) -> Result<(Option<Vec<Vec<i64>>>, LowerSeedDecompositionSearchStats), String> {
    if max_terms < 2 || seeds.is_empty() {
        return Ok((
            None,
            LowerSeedDecompositionSearchStats {
                direct_pair_seed_scan_count: 0,
                pair_sum_degree_bound: None,
                pair_sum_candidate_count: None,
                pair_sum_unique_count: None,
                pair_sum_duplicate_count: None,
                pair_sum_overdegree_skipped_count: None,
            },
        ));
    }
    if max_terms > 4 {
        return Err("bounded seed decomposition currently supports max_terms <= 4".to_string());
    }
    if seeds.iter().any(|seed| seed.len() != target.len()) {
        return Err("bounded seed decomposition seed dimension mismatch".to_string());
    }
    let (seed_degrees, _target_degree, pair_sum_max_degree) = if let Some(grading) =
        positive_grading
    {
        if grading.len() != target.len() {
            return Err("bounded seed decomposition grading dimension mismatch".to_string());
        }
        let target_degree = curve_degree(target, grading)?;
        if target_degree <= 0 {
            return Err(
                "positive-graded bounded seed decomposition target degree must be positive"
                    .to_string(),
            );
        }
        let seed_degrees = seeds
            .iter()
            .map(|seed| curve_degree(seed, grading))
            .collect::<Result<Vec<_>, _>>()?;
        if seed_degrees.iter().any(|&degree| degree <= 0) {
            return Err(
                "positive-graded bounded seed decomposition seeds must have positive degree"
                    .to_string(),
            );
        }
        let min_seed_degree = *seed_degrees
            .iter()
            .min()
            .expect("seed degrees are nonempty because seeds is nonempty");
        let pair_sum_max_degree = target_degree.checked_sub(min_seed_degree).ok_or_else(|| {
            "positive-graded bounded seed decomposition pair degree underflowed".to_string()
        })?;
        (
            Some(seed_degrees),
            Some(target_degree),
            Some(pair_sum_max_degree),
        )
    } else {
        (None, None, None)
    };
    let mut stats = LowerSeedDecompositionSearchStats {
        direct_pair_seed_scan_count: 0,
        pair_sum_degree_bound: pair_sum_max_degree,
        pair_sum_candidate_count: None,
        pair_sum_unique_count: None,
        pair_sum_duplicate_count: None,
        pair_sum_overdegree_skipped_count: None,
    };

    let target_sparse = sparse_from_dense(target);
    let seed_sparse = seeds
        .iter()
        .map(|seed| sparse_from_dense(seed))
        .collect::<Vec<_>>();
    let direct_pair = first_sparse_seed_pair_for_sum(&target_sparse, &seed_sparse)?;
    stats.direct_pair_seed_scan_count = direct_pair.seed_scan_count;
    if let Some((i, j)) = direct_pair.pair {
        return Ok((
            Some(sorted_decomposition(vec![
                seeds[i].clone(),
                seeds[j].clone(),
            ])),
            stats,
        ));
    }
    if max_terms < 3 {
        return Ok((None, stats));
    }

    let pair_sums_result =
        sparse_seed_pair_sums(&seed_sparse, seed_degrees.as_deref(), pair_sum_max_degree)?;
    stats.pair_sum_candidate_count = Some(pair_sums_result.candidate_pair_count);
    stats.pair_sum_unique_count = Some(pair_sums_result.sums.len());
    stats.pair_sum_duplicate_count = Some(pair_sums_result.duplicate_sum_count);
    stats.pair_sum_overdegree_skipped_count = Some(pair_sums_result.overdegree_skipped_count);
    let pair_sums = pair_sums_result.sums;
    for (seed_index, seed) in seed_sparse.iter().enumerate() {
        let remainder = checked_sparse_difference(&target_sparse, seed)?;
        if let Some(&(i, j)) = pair_sums.get(&remainder) {
            return Ok((
                Some(sorted_decomposition(vec![
                    seeds[seed_index].clone(),
                    seeds[i].clone(),
                    seeds[j].clone(),
                ])),
                stats,
            ));
        }
    }
    if max_terms < 4 {
        return Ok((None, stats));
    }

    let mut pair_sums_sorted = pair_sums.keys().collect::<Vec<_>>();
    pair_sums_sorted.sort_by(|left, right| compare_sparse_as_dense(left, right, target.len()));
    for first_sum in pair_sums_sorted {
        let remainder = checked_sparse_difference(&target_sparse, first_sum)?;
        let Some(&(k, l)) = pair_sums.get(&remainder) else {
            continue;
        };
        let &(i, j) = pair_sums
            .get(first_sum)
            .expect("first sum came from pair-sum keys");
        return Ok((
            Some(sorted_decomposition(vec![
                seeds[i].clone(),
                seeds[j].clone(),
                seeds[k].clone(),
                seeds[l].clone(),
            ])),
            stats,
        ));
    }

    Ok((None, stats))
}

struct FirstSparseSeedPairForSum {
    pair: Option<(usize, usize)>,
    seed_scan_count: usize,
}

fn first_sparse_seed_pair_for_sum(
    target: &[(usize, i64)],
    seeds: &[Vec<(usize, i64)>],
) -> Result<FirstSparseSeedPairForSum, String> {
    let mut seed_indices_by_sparse = HashMap::<Vec<(usize, i64)>, Vec<usize>>::new();
    for (index, seed) in seeds.iter().enumerate() {
        seed_indices_by_sparse
            .entry(seed.clone())
            .or_default()
            .push(index);
    }
    for (i, seed) in seeds.iter().enumerate() {
        let remainder = checked_sparse_difference(target, seed)?;
        let Some(indices) = seed_indices_by_sparse.get(&remainder) else {
            continue;
        };
        let candidate_index = indices.partition_point(|&index| index < i);
        if let Some(&j) = indices.get(candidate_index) {
            return Ok(FirstSparseSeedPairForSum {
                pair: Some((i, j)),
                seed_scan_count: i + 1,
            });
        }
    }
    Ok(FirstSparseSeedPairForSum {
        pair: None,
        seed_scan_count: seeds.len(),
    })
}

struct SparseSeedPairSums {
    sums: HashMap<Vec<(usize, i64)>, (usize, usize)>,
    candidate_pair_count: usize,
    duplicate_sum_count: usize,
    overdegree_skipped_count: usize,
}

fn sparse_seed_pair_sums(
    seeds: &[Vec<(usize, i64)>],
    seed_degrees: Option<&[i128]>,
    max_pair_degree: Option<i128>,
) -> Result<SparseSeedPairSums, String> {
    if seed_degrees.is_some() != max_pair_degree.is_some() {
        return Err("sparse seed pair degree filter is incomplete".to_string());
    }
    if let Some(degrees) = seed_degrees
        && degrees.len() != seeds.len()
    {
        return Err("sparse seed pair degree filter length mismatch".to_string());
    }
    let mut pair_sums = HashMap::new();
    let mut candidate_pair_count = 0usize;
    let mut duplicate_sum_count = 0usize;
    let mut overdegree_skipped_count = 0usize;
    for i in 0..seeds.len() {
        for j in i..seeds.len() {
            if let (Some(degrees), Some(max_degree)) = (seed_degrees, max_pair_degree) {
                let pair_degree = degrees[i]
                    .checked_add(degrees[j])
                    .ok_or_else(|| "sparse seed pair degree overflowed".to_string())?;
                if pair_degree > max_degree {
                    overdegree_skipped_count += 1;
                    continue;
                }
            }
            candidate_pair_count += 1;
            let sum = checked_sparse_sum(&seeds[i], &seeds[j])?;
            if let std::collections::hash_map::Entry::Vacant(entry) = pair_sums.entry(sum) {
                entry.insert((i, j));
            } else {
                duplicate_sum_count += 1;
            }
        }
    }
    Ok(SparseSeedPairSums {
        sums: pair_sums,
        candidate_pair_count,
        duplicate_sum_count,
        overdegree_skipped_count,
    })
}

fn checked_sparse_sum(
    lhs: &[(usize, i64)],
    rhs: &[(usize, i64)],
) -> Result<Vec<(usize, i64)>, String> {
    checked_sparse_linear_combination(lhs, 1, rhs, 1)
}

fn checked_sparse_difference(
    lhs: &[(usize, i64)],
    rhs: &[(usize, i64)],
) -> Result<Vec<(usize, i64)>, String> {
    checked_sparse_linear_combination(lhs, 1, rhs, -1)
}

fn checked_sparse_linear_combination(
    lhs: &[(usize, i64)],
    lhs_sign: i64,
    rhs: &[(usize, i64)],
    rhs_sign: i64,
) -> Result<Vec<(usize, i64)>, String> {
    let mut out = Vec::with_capacity(lhs.len() + rhs.len());
    let mut lhs_idx = 0usize;
    let mut rhs_idx = 0usize;
    while lhs_idx < lhs.len() || rhs_idx < rhs.len() {
        let (index, lhs_value, rhs_value) = match (lhs.get(lhs_idx), rhs.get(rhs_idx)) {
            (Some(&(lhs_index, lhs_value)), Some(&(rhs_index, rhs_value))) => {
                if lhs_index == rhs_index {
                    lhs_idx += 1;
                    rhs_idx += 1;
                    (lhs_index, lhs_value, rhs_value)
                } else if lhs_index < rhs_index {
                    lhs_idx += 1;
                    (lhs_index, lhs_value, 0)
                } else {
                    rhs_idx += 1;
                    (rhs_index, 0, rhs_value)
                }
            }
            (Some(&(lhs_index, lhs_value)), None) => {
                lhs_idx += 1;
                (lhs_index, lhs_value, 0)
            }
            (None, Some(&(rhs_index, rhs_value))) => {
                rhs_idx += 1;
                (rhs_index, 0, rhs_value)
            }
            (None, None) => break,
        };
        let signed_lhs = lhs_value
            .checked_mul(lhs_sign)
            .ok_or_else(|| "sparse linear-combination lhs multiplication overflowed".to_string())?;
        let signed_rhs = rhs_value
            .checked_mul(rhs_sign)
            .ok_or_else(|| "sparse linear-combination rhs multiplication overflowed".to_string())?;
        let value = signed_lhs
            .checked_add(signed_rhs)
            .ok_or_else(|| "sparse linear-combination addition overflowed".to_string())?;
        if value != 0 {
            out.push((index, value));
        }
    }
    Ok(out)
}

fn compare_sparse_as_dense(
    lhs: &[(usize, i64)],
    rhs: &[(usize, i64)],
    dimension: usize,
) -> std::cmp::Ordering {
    let mut lhs_idx = 0usize;
    let mut rhs_idx = 0usize;
    for index in 0..dimension {
        let lhs_value = if lhs_idx < lhs.len() && lhs[lhs_idx].0 == index {
            let value = lhs[lhs_idx].1;
            lhs_idx += 1;
            value
        } else {
            0
        };
        let rhs_value = if rhs_idx < rhs.len() && rhs[rhs_idx].0 == index {
            let value = rhs[rhs_idx].1;
            rhs_idx += 1;
            value
        } else {
            0
        };
        match lhs_value.cmp(&rhs_value) {
            std::cmp::Ordering::Equal => {}
            ordering => return ordering,
        }
    }
    std::cmp::Ordering::Equal
}

fn sorted_decomposition(mut terms: Vec<Vec<i64>>) -> Vec<Vec<i64>> {
    terms.sort();
    terms
}

fn reconstruct_intersection(
    dimension: usize,
    entries: &[SparseIntersectionEntry],
) -> Result<Intersection, String> {
    let mut intersection = Intersection::new(dimension);
    for entry in entries {
        if entry.indices.iter().any(|&idx| idx >= dimension) {
            return Err(format!(
                "intersection index {:?} is out of bounds for dimension {dimension}",
                entry.indices
            ));
        }
        let value = parse_rational(&entry.value)?;
        intersection.set(
            entry.indices[0],
            entry.indices[1],
            entry.indices[2],
            Rational::<Finite>::new(value),
        );
    }
    Ok(intersection)
}

fn target_active_support(
    sample: &MissingGvTargetSample,
    dimension: usize,
) -> Result<HashSet<usize>, String> {
    let target = dense_from_sparse(&sample.basis_nonzero, dimension)?;
    let mut support = target
        .iter()
        .enumerate()
        .filter_map(|(idx, &value)| (value != 0).then_some(idx))
        .collect::<HashSet<_>>();
    if let Some(active_generators) = sample
        .real_cone_decomposition_active_generator_basis_nonzero
        .as_ref()
    {
        for generator in active_generators {
            for &(idx, value) in generator {
                if idx >= dimension {
                    return Err(format!(
                        "active generator coordinate {idx} is out of bounds for dimension {dimension}"
                    ));
                }
                if value != 0 {
                    support.insert(idx);
                }
            }
        }
    }
    Ok(support)
}

fn support_window_stats(
    sample: &MissingGvTargetSample,
    context: &ValidatedContext<'_>,
) -> Result<
    (
        usize,
        Vec<SupportOverlapCount>,
        Vec<SupportClosureLayerCount>,
    ),
    String,
> {
    let seed_support = target_active_support(sample, context.dimension)?;
    let mut eligible_supports = Vec::new();
    for ray in context.degree_bounded_rays {
        let degree = curve_degree(ray, context.grading)?;
        if degree <= 0 || degree > sample.degree {
            continue;
        }
        let support = ray
            .iter()
            .enumerate()
            .filter_map(|(idx, &value)| (value != 0).then_some(idx))
            .collect::<HashSet<_>>();
        eligible_supports.push(support);
    }
    let overlap_counts = (1..=4)
        .map(|min_overlap| SupportOverlapCount {
            min_overlap,
            generator_count: eligible_supports
                .iter()
                .filter(|support| support.intersection(&seed_support).count() >= min_overlap)
                .count(),
        })
        .collect::<Vec<_>>();

    let mut closure_support = seed_support;
    let mut closure_counts = Vec::new();
    for layer in 1..=4 {
        let selected = eligible_supports
            .iter()
            .filter(|support| !support.is_disjoint(&closure_support))
            .collect::<Vec<_>>();
        for support in &selected {
            closure_support.extend(support.iter().copied());
        }
        closure_counts.push(SupportClosureLayerCount {
            layer,
            generator_count: selected.len(),
            support_size: closure_support.len(),
        });
    }
    Ok((eligible_supports.len(), overlap_counts, closure_counts))
}

