fn known_qn_history_status(
    toric_gv: Option<&str>,
    source_derived_gv: Option<&str>,
) -> Result<&'static str, String> {
    let toric_parsed = toric_gv.map(parse_rational).transpose()?;
    let source_parsed = source_derived_gv.map(parse_rational).transpose()?;
    if let (Some(toric), Some(source)) = (&toric_parsed, &source_parsed)
        && toric != source
    {
        return Err(format!(
            "toric GV value {toric} conflicts with source-derived GV value {source}"
        ));
    }
    let zero = MalachiteRational::from(0);
    if let Some(toric) = toric_parsed {
        if toric == zero {
            Ok("known_zero_toric_gv")
        } else {
            Ok("known_nonzero_toric_gv")
        }
    } else if let Some(source) = source_parsed {
        if source == zero {
            Ok("known_zero_source_gv")
        } else {
            Ok("known_nonzero_source_gv")
        }
    } else {
        Ok("unknown_not_toric_covered")
    }
}

fn known_qn_history_pair_status(predecessor_status: &str, difference_status: &str) -> String {
    format!("predecessor_{predecessor_status}__difference_{difference_status}")
}

fn compact_qn_polynomial_status(scalar_status: &str) -> &'static str {
    match scalar_status {
        "known_nonzero_toric_gv" => "compact_qn_missing_toric_scalar_only",
        "known_nonzero_source_gv" => "compact_qn_missing_source_scalar_only",
        "known_zero_toric_gv" | "known_zero_source_gv" => "compact_qn_not_required_zero_scalar_gv",
        "unknown_not_toric_covered" => "compact_qn_missing_unknown_scalar_gv",
        _ => "compact_qn_status_unrecognized",
    }
}

fn compact_qn_polynomial_pair_status(predecessor_status: &str, difference_status: &str) -> String {
    format!(
        "predecessor_{}__difference_{}",
        compact_qn_polynomial_status(predecessor_status),
        compact_qn_polynomial_status(difference_status)
    )
}

fn is_known_nonzero_qn_history_status(status: &str) -> bool {
    matches!(status, "known_nonzero_toric_gv" | "known_nonzero_source_gv")
}

fn cygv_closest_known_qn_residual_status(probe: &CygvPathHistoryProbe) -> String {
    let Some(closest) = probe.closest_known_qn_predecessor.as_ref() else {
        return "no_closest_known_qn_predecessor".to_string();
    };
    let Some(residual) = probe.closest_known_qn_residual_predecessor.as_ref() else {
        if closest.difference_known_qn_history_status == "unknown_not_toric_covered" {
            return "unknown_residual_has_no_known_qn_predecessor".to_string();
        }
        return format!(
            "closest_difference_{}",
            closest.difference_known_qn_history_status
        );
    };
    format!(
        "residual_{}",
        known_qn_history_pair_status(
            &residual.predecessor_known_qn_history_status,
            &residual.difference_known_qn_history_status,
        )
    )
}

fn cygv_closest_known_qn_residual_status_counts(
    targets: &[TargetReport],
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for target in targets {
        let status = target.cygv_path_history_probe.as_ref().map_or_else(
            || "not_run".to_string(),
            cygv_closest_known_qn_residual_status,
        );
        *counts.entry(status).or_insert(0) += 1;
    }
    counts
}

fn cygv_closest_known_qn_residual_degree_split_counts(
    targets: &[TargetReport],
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for residual in targets
        .iter()
        .filter_map(|target| target.cygv_path_history_probe.as_ref())
        .filter_map(|probe| probe.closest_known_qn_residual_predecessor.as_ref())
    {
        let key = format!(
            "{}+{}",
            residual.predecessor_degree, residual.difference_degree
        );
        *counts.entry(key).or_insert(0) += 1;
    }
    counts
}

fn cygv_closest_known_qn_residual_difference_summaries(
    targets: &[TargetReport],
) -> Vec<CygvClosestKnownQnResidualDifferenceSummary> {
    let mut summaries: BTreeMap<
        Vec<(usize, i64)>,
        CygvClosestKnownQnResidualDifferenceSummaryBuilder,
    > = BTreeMap::new();
    for target in targets {
        let Some(residual) = target
            .cygv_path_history_probe
            .as_ref()
            .and_then(|probe| probe.closest_known_qn_residual_predecessor.as_ref())
        else {
            continue;
        };
        add_cygv_closest_known_qn_residual_difference(&mut summaries, target.index, residual);
    }
    let mut out = summaries
        .into_values()
        .map(|builder| CygvClosestKnownQnResidualDifferenceSummary {
            degree: builder.degree,
            occurrence_count: builder.occurrences.len(),
            known_qn_history_status_counts: builder.known_qn_history_status_counts,
            source_derived_gv_counts: builder.source_derived_gv_counts,
            toric_gv_counts: builder.toric_gv_counts,
            curve_nonzero: builder.curve_nonzero,
            occurrences: builder.occurrences,
        })
        .collect::<Vec<_>>();
    out.sort_by(|lhs, rhs| {
        lhs.degree
            .cmp(&rhs.degree)
            .then_with(|| lhs.curve_nonzero.cmp(&rhs.curve_nonzero))
    });
    out
}

fn add_cygv_closest_known_qn_residual_difference(
    summaries: &mut BTreeMap<Vec<(usize, i64)>, CygvClosestKnownQnResidualDifferenceSummaryBuilder>,
    target_index: usize,
    residual: &CygvClosestKnownQnPredecessor,
) {
    let entry = summaries
        .entry(residual.difference_nonzero.clone())
        .or_insert_with(|| CygvClosestKnownQnResidualDifferenceSummaryBuilder {
            degree: residual.difference_degree,
            known_qn_history_status_counts: BTreeMap::new(),
            source_derived_gv_counts: BTreeMap::new(),
            toric_gv_counts: BTreeMap::new(),
            curve_nonzero: residual.difference_nonzero.clone(),
            occurrences: Vec::new(),
        });
    debug_assert_eq!(entry.degree, residual.difference_degree);
    *entry
        .known_qn_history_status_counts
        .entry(residual.difference_known_qn_history_status.clone())
        .or_insert(0) += 1;
    *entry
        .source_derived_gv_counts
        .entry(
            residual
                .difference_source_derived_gv
                .clone()
                .unwrap_or_else(|| "missing_source_derived_gv".to_string()),
        )
        .or_insert(0) += 1;
    *entry
        .toric_gv_counts
        .entry(
            residual
                .difference_toric_gv
                .clone()
                .unwrap_or_else(|| "not_toric_covered".to_string()),
        )
        .or_insert(0) += 1;
    entry
        .occurrences
        .push(CygvClosestKnownQnResidualDifferenceOccurrence {
            target_index,
            series_distance: residual.series_distance.clone(),
            residual_predecessor_degree: residual.predecessor_degree,
            residual_predecessor_known_qn_history_status: residual
                .predecessor_known_qn_history_status
                .clone(),
            residual_predecessor_toric_gv: residual.predecessor_toric_gv.clone(),
            residual_predecessor_source_derived_gv: residual.predecessor_source_derived_gv.clone(),
            residual_predecessor_nonzero: residual.predecessor_nonzero.clone(),
        });
}

fn cygv_closest_known_qn_residual_difference_degree_counts(
    summaries: &[CygvClosestKnownQnResidualDifferenceSummary],
) -> BTreeMap<i128, usize> {
    let mut counts = BTreeMap::new();
    for summary in summaries {
        *counts.entry(summary.degree).or_insert(0) += 1;
    }
    counts
}

fn cygv_closest_known_qn_residual_difference_known_qn_history_status_counts(
    summaries: &[CygvClosestKnownQnResidualDifferenceSummary],
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for summary in summaries {
        for (status, count) in &summary.known_qn_history_status_counts {
            *counts.entry(status.clone()).or_insert(0) += count;
        }
    }
    counts
}

fn cygv_closest_known_qn_residual_source_predecessor_summaries(
    targets: &[TargetReport],
    context: &ValidatedContext<'_>,
) -> Vec<CygvClosestKnownQnResidualSourcePredecessorSummary> {
    let mut summaries: BTreeMap<
        Vec<(usize, i64)>,
        CygvClosestKnownQnResidualSourcePredecessorSummaryBuilder,
    > = BTreeMap::new();
    for target in targets {
        let Some(residual) = target
            .cygv_path_history_probe
            .as_ref()
            .and_then(|probe| probe.closest_known_qn_residual_predecessor.as_ref())
        else {
            continue;
        };
        add_cygv_closest_known_qn_residual_source_predecessor(
            &mut summaries,
            target.index,
            residual,
            context,
        );
    }
    let mut out = summaries
        .into_values()
        .map(
            |builder| CygvClosestKnownQnResidualSourcePredecessorSummary {
                degree: builder.degree,
                occurrence_count: builder.occurrences.len(),
                source_class_status_counts: builder.source_class_status_counts,
                known_qn_history_status_counts: builder.known_qn_history_status_counts,
                source_derived_gv_counts: builder.source_derived_gv_counts,
                toric_gv_counts: builder.toric_gv_counts,
                source_ray_ambient_nonzero: builder.source_ray_ambient_nonzero,
                matching_uncovered_source_ray_index: builder.matching_uncovered_source_ray_index,
                matching_uncovered_source_ray_origin_circuit_pattern: builder
                    .matching_uncovered_source_ray_origin_circuit_pattern,
                matching_uncovered_source_ray_exact_kind: builder
                    .matching_uncovered_source_ray_exact_kind,
                matching_uncovered_source_ray_origin_witness_relation_status: builder
                    .matching_uncovered_source_ray_origin_witness_relation_status,
                matching_uncovered_source_ray_facet_context_status: builder
                    .matching_uncovered_source_ray_facet_context_status,
                matching_uncovered_source_ray_cms_check_status_counts: builder
                    .matching_uncovered_source_ray_cms_check_status_counts,
                matching_uncovered_source_ray_cms_solution_summaries: builder
                    .matching_uncovered_source_ray_cms_solution_summaries,
                matching_uncovered_source_ray_local_charge_signature: builder
                    .matching_uncovered_source_ray_local_charge_signature,
                matching_uncovered_source_ray_local_cygv_readiness_counts: builder
                    .matching_uncovered_source_ray_local_cygv_readiness_counts,
                matching_uncovered_source_ray_local_missing_input_counts: builder
                    .matching_uncovered_source_ray_local_missing_input_counts,
                matching_uncovered_source_ray_local_cygv_input_skeleton: builder
                    .matching_uncovered_source_ray_local_cygv_input_skeleton,
                matching_uncovered_source_ray_local_unit_phase_probe: builder
                    .matching_uncovered_source_ray_local_unit_phase_probe,
                curve_nonzero: builder.curve_nonzero,
                occurrences: builder.occurrences,
            },
        )
        .collect::<Vec<_>>();
    out.sort_by(|lhs, rhs| {
        lhs.degree
            .cmp(&rhs.degree)
            .then_with(|| lhs.curve_nonzero.cmp(&rhs.curve_nonzero))
    });
    out
}

fn add_cygv_closest_known_qn_residual_source_predecessor(
    summaries: &mut BTreeMap<
        Vec<(usize, i64)>,
        CygvClosestKnownQnResidualSourcePredecessorSummaryBuilder,
    >,
    target_index: usize,
    residual: &CygvClosestKnownQnPredecessor,
    context: &ValidatedContext<'_>,
) {
    if !residual
        .predecessor_known_qn_history_status
        .ends_with("_source_gv")
        && residual.predecessor_source_derived_gv.is_none()
    {
        return;
    }
    let Ok(curve) = dense_from_sparse(&residual.predecessor_nonzero, context.dimension) else {
        return;
    };
    let source_context_result = path_support_source_class_context(&curve, context);
    let source_context = source_context_result.ok();
    let source_ray_sample = matching_uncovered_source_ray_for_curve(&curve, context)
        .ok()
        .flatten()
        .map(|(_, sample)| sample);
    let source_ray_origin_witness_relation_status =
        source_ray_sample.map(origin_circuit_witness_relation_status);
    let source_ray_facet_context_status =
        source_ray_sample.map(origin_circuit_facet_context_status);
    let source_class_status = source_context.as_ref().map_or_else(
        || "source_context_lookup_error".to_string(),
        |source_context| source_context.status.clone(),
    );
    let entry = summaries
        .entry(residual.predecessor_nonzero.clone())
        .or_insert_with(
            || CygvClosestKnownQnResidualSourcePredecessorSummaryBuilder {
                degree: residual.predecessor_degree,
                source_class_status_counts: BTreeMap::new(),
                known_qn_history_status_counts: BTreeMap::new(),
                source_derived_gv_counts: BTreeMap::new(),
                toric_gv_counts: BTreeMap::new(),
                source_ray_ambient_nonzero: source_context
                    .as_ref()
                    .and_then(|source_context| source_context.source_ray_ambient_nonzero.clone()),
                matching_uncovered_source_ray_index: source_context
                    .as_ref()
                    .and_then(|source_context| source_context.matching_uncovered_source_ray_index),
                matching_uncovered_source_ray_origin_circuit_pattern: source_context
                    .as_ref()
                    .and_then(|source_context| {
                        source_context
                            .matching_uncovered_source_ray_origin_circuit_pattern
                            .clone()
                    }),
                matching_uncovered_source_ray_exact_kind: source_context.as_ref().and_then(
                    |source_context| {
                        source_context
                            .matching_uncovered_source_ray_exact_kind
                            .clone()
                    },
                ),
                matching_uncovered_source_ray_origin_witness_relation_status:
                    source_ray_origin_witness_relation_status,
                matching_uncovered_source_ray_facet_context_status: source_ray_facet_context_status,
                matching_uncovered_source_ray_cms_check_status_counts: source_context
                    .as_ref()
                    .map(|source_context| {
                        source_context
                            .matching_uncovered_source_ray_cms_check_status_counts
                            .clone()
                    })
                    .unwrap_or_default(),
                matching_uncovered_source_ray_cms_solution_summaries: source_context
                    .as_ref()
                    .map(|source_context| {
                        source_context
                            .matching_uncovered_source_ray_cms_solution_summaries
                            .clone()
                    })
                    .unwrap_or_default(),
                matching_uncovered_source_ray_local_charge_signature: source_context
                    .as_ref()
                    .and_then(|source_context| {
                        source_context
                            .matching_uncovered_source_ray_local_charge_signature
                            .clone()
                    }),
                matching_uncovered_source_ray_local_cygv_readiness_counts: BTreeMap::new(),
                matching_uncovered_source_ray_local_missing_input_counts: BTreeMap::new(),
                matching_uncovered_source_ray_local_cygv_input_skeleton: source_context
                    .as_ref()
                    .and_then(|source_context| {
                        source_context
                            .matching_uncovered_source_ray_local_cygv_input_skeleton
                            .clone()
                    }),
                matching_uncovered_source_ray_local_unit_phase_probe: source_context
                    .as_ref()
                    .and_then(|source_context| {
                        source_context
                            .matching_uncovered_source_ray_local_unit_phase_probe
                            .clone()
                    }),
                curve_nonzero: residual.predecessor_nonzero.clone(),
                occurrences: Vec::new(),
            },
        );
    debug_assert_eq!(entry.degree, residual.predecessor_degree);
    *entry
        .source_class_status_counts
        .entry(source_class_status)
        .or_insert(0) += 1;
    *entry
        .known_qn_history_status_counts
        .entry(residual.predecessor_known_qn_history_status.clone())
        .or_insert(0) += 1;
    *entry
        .source_derived_gv_counts
        .entry(
            residual
                .predecessor_source_derived_gv
                .clone()
                .unwrap_or_else(|| "missing_source_derived_gv".to_string()),
        )
        .or_insert(0) += 1;
    *entry
        .toric_gv_counts
        .entry(
            residual
                .predecessor_toric_gv
                .clone()
                .unwrap_or_else(|| "not_toric_covered".to_string()),
        )
        .or_insert(0) += 1;
    if let Some(source_context) = source_context.as_ref() {
        if let Some(readiness) = &source_context.matching_uncovered_source_ray_local_cygv_readiness
        {
            *entry
                .matching_uncovered_source_ray_local_cygv_readiness_counts
                .entry(readiness.clone())
                .or_insert(0) += 1;
        }
        for input in &source_context.matching_uncovered_source_ray_local_missing_inputs {
            *entry
                .matching_uncovered_source_ray_local_missing_input_counts
                .entry(input.clone())
                .or_insert(0) += 1;
        }
    }
    entry
        .matching_uncovered_source_ray_cms_solution_summaries
        .sort();
    entry
        .matching_uncovered_source_ray_cms_solution_summaries
        .dedup();
    entry
        .occurrences
        .push(CygvClosestKnownQnResidualSourcePredecessorOccurrence {
            target_index,
            series_distance: residual.series_distance.clone(),
            residual_difference_degree: residual.difference_degree,
            residual_difference_known_qn_history_status: residual
                .difference_known_qn_history_status
                .clone(),
            residual_difference_toric_gv: residual.difference_toric_gv.clone(),
            residual_difference_source_derived_gv: residual.difference_source_derived_gv.clone(),
            residual_difference_nonzero: residual.difference_nonzero.clone(),
        });
}

