struct LocalCygvZeroSharedAffineProjectionHint {
    status: String,
    hyperplane: Option<Vec<i64>>,
    heights: Vec<ZeroSharedAffineHeight>,
}

fn local_cygv_zero_shared_affine_projection_hint(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
) -> LocalCygvZeroSharedAffineProjectionHint {
    let empty = |status: &str| LocalCygvZeroSharedAffineProjectionHint {
        status: status.to_string(),
        hyperplane: None,
        heights: Vec::new(),
    };
    let Some(q_matrix) = skeleton.local_cygv_phase_q_matrix_candidate.as_ref() else {
        return empty("zero_shared_projection_blocked_missing_phase_q_matrix");
    };
    if q_matrix.len() != 1 {
        return empty("zero_shared_projection_not_one_parameter_local_q_matrix");
    }
    if one_parameter_weighted_p2_split_bundle_signature(&q_matrix[0]).is_none() {
        return empty("zero_shared_projection_not_weighted_p2_split_bundle");
    }
    let Some(witness) = witness else {
        return empty("weighted_p2_zero_shared_projection_missing_origin_circuit_witness");
    };
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(Some(witness));
    if zero_shared.len() != 1 {
        return empty("weighted_p2_zero_shared_projection_requires_single_zero_shared_ray");
    }
    let hyperplane = match primitive_relation_support_affine_hyperplane(witness) {
        Ok(hyperplane) => hyperplane,
        Err(error) => {
            return LocalCygvZeroSharedAffineProjectionHint {
                status: format!(
                    "weighted_p2_zero_shared_projection_hyperplane_error:{}",
                    status_error_fragment(&error)
                ),
                hyperplane: None,
                heights: Vec::new(),
            };
        }
    };
    let zero_shared_set = zero_shared.into_iter().collect::<BTreeSet<_>>();
    let heights = witness
        .shared_two_simplex_points
        .iter()
        .filter(|point| zero_shared_set.contains(&point.point_index))
        .map(|point| ZeroSharedAffineHeight {
            point_index: point.point_index,
            height: affine_hyperplane_height(&hyperplane, &point.coordinates),
        })
        .collect::<Vec<_>>();
    if heights.len() != zero_shared_set.len() {
        return LocalCygvZeroSharedAffineProjectionHint {
            status: "weighted_p2_zero_shared_projection_missing_zero_shared_ray_coordinates"
                .to_string(),
            hyperplane: Some(hyperplane),
            heights,
        };
    }
    let status = if heights.iter().all(|height| height.height.abs() == 1) {
        "weighted_p2_zero_shared_ray_has_primitive_unit_height_off_relation_hyperplane_requires_projection_or_chamber_map"
    } else if heights.iter().all(|height| height.height == 0) {
        "weighted_p2_zero_shared_ray_lies_on_relation_hyperplane"
    } else {
        "weighted_p2_zero_shared_ray_has_nonunit_height_off_relation_hyperplane"
    };
    LocalCygvZeroSharedAffineProjectionHint {
        status: status.to_string(),
        hyperplane: Some(hyperplane),
        heights,
    }
}

fn local_cygv_zero_shared_star_status(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
) -> String {
    let Some(q_matrix) = skeleton.local_cygv_phase_q_matrix_candidate.as_ref() else {
        return "zero_shared_star_blocked_missing_phase_q_matrix".to_string();
    };
    if q_matrix.len() != 1 {
        return "zero_shared_star_not_one_parameter_local_q_matrix".to_string();
    }
    if one_parameter_weighted_p2_split_bundle_signature(&q_matrix[0]).is_none() {
        return "zero_shared_star_not_weighted_p2_split_bundle".to_string();
    }
    let Some(witness) = witness else {
        return "weighted_p2_zero_shared_star_missing_origin_circuit_witness".to_string();
    };
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(Some(witness));
    if zero_shared.len() != 1 {
        return "weighted_p2_zero_shared_star_requires_single_zero_shared_ray".to_string();
    }
    if witness.shared_two_simplex_star_simplices.is_empty() {
        return "weighted_p2_zero_shared_star_missing_triangulation_star_simplices".to_string();
    }
    let extras = origin_circuit_shared_two_simplex_star_extra_points(Some(witness));
    if extras.len() != witness.shared_two_simplex_star_simplices.len() {
        return "weighted_p2_zero_shared_star_extra_point_shape_error".to_string();
    }
    if witness
        .shared_two_simplex_star_simplices
        .iter()
        .any(|simplex| !simplex.contains(&0))
    {
        return "weighted_p2_zero_shared_star_has_nonstar_simplex_without_origin".to_string();
    }
    let shared = witness
        .shared_two_simplex
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    if witness
        .shared_two_simplex_star_simplices
        .iter()
        .any(|simplex| {
            !shared
                .iter()
                .all(|point_index| simplex.contains(point_index))
        })
    {
        return "weighted_p2_zero_shared_star_simplex_missing_shared_face".to_string();
    }
    let relation_exclusive = BTreeSet::from([
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ]);
    let star_extras = extras.iter().flatten().copied().collect::<BTreeSet<_>>();
    if witness.shared_two_simplex_star_simplices.len() == 2
        && extras.iter().all(|extra| extra.len() == 1)
    {
        if star_extras == relation_exclusive {
            "weighted_p2_zero_shared_star_uses_origin_circuit_exclusive_pair".to_string()
        } else if star_extras.is_disjoint(&relation_exclusive) {
            "weighted_p2_zero_shared_star_uses_two_alternate_chamber_points".to_string()
        } else {
            "weighted_p2_zero_shared_star_mixes_exclusive_and_alternate_chamber_points".to_string()
        }
    } else {
        "weighted_p2_zero_shared_star_non_two_simplex_star_shape".to_string()
    }
}

struct LocalCygvResolvedSharedSupportHint {
    status: String,
    affine_rank: Option<usize>,
    point_indices: Vec<usize>,
    charge_basis: Option<Vec<Vec<i64>>>,
    charge_row_sums: Option<Vec<i64>>,
}

struct LocalCygvResolvedSharedChamberCertificateHint {
    status: String,
    hyperplane_count: Option<usize>,
    min_pairing: Option<String>,
    max_pairing: Option<String>,
    strictly_inside: Option<bool>,
}

struct LocalCygvResolvedSharedChamberGlobalHeightHint {
    status: String,
    min_pairing: Option<String>,
    max_pairing: Option<String>,
    zero_pairing_count: Option<usize>,
    positive_pairing_count: Option<usize>,
    negative_pairing_count: Option<usize>,
}

fn local_cygv_resolved_shared_support_hint(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
) -> LocalCygvResolvedSharedSupportHint {
    let empty = |status: &str| LocalCygvResolvedSharedSupportHint {
        status: status.to_string(),
        affine_rank: None,
        point_indices: Vec::new(),
        charge_basis: None,
        charge_row_sums: None,
    };
    let Some(q_matrix) = skeleton.local_cygv_phase_q_matrix_candidate.as_ref() else {
        return empty("resolved_shared_support_blocked_missing_phase_q_matrix");
    };
    if q_matrix.len() != 1 {
        return empty("resolved_shared_support_not_one_parameter_local_q_matrix");
    }
    if one_parameter_weighted_p2_split_bundle_signature(&q_matrix[0]).is_none() {
        return empty("resolved_shared_support_not_weighted_p2_split_bundle");
    }
    let Some(witness) = witness else {
        return empty("weighted_p2_resolved_shared_support_missing_origin_circuit_witness");
    };
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(Some(witness));
    if zero_shared.len() != 1 {
        return empty("weighted_p2_resolved_shared_support_requires_single_zero_shared_ray");
    }
    let support = origin_circuit_resolved_shared_support_point_samples(witness);
    if !zero_shared.iter().all(|point_index| {
        support
            .iter()
            .any(|point| point.point_index == *point_index && point.coefficient == 0)
    }) {
        return LocalCygvResolvedSharedSupportHint {
            status: "weighted_p2_resolved_shared_support_missing_zero_shared_ray_coordinates"
                .to_string(),
            affine_rank: None,
            point_indices: support.iter().map(|point| point.point_index).collect(),
            charge_basis: None,
            charge_row_sums: None,
        };
    }
    let point_indices = support
        .iter()
        .map(|point| point.point_index)
        .collect::<Vec<_>>();
    let affine_rank = match affine_rank_for_point_samples(&support) {
        Ok(rank) => rank,
        Err(error) => {
            return LocalCygvResolvedSharedSupportHint {
                status: format!(
                    "weighted_p2_resolved_shared_support_affine_rank_error:{}",
                    status_error_fragment(&error)
                ),
                affine_rank: None,
                point_indices,
                charge_basis: None,
                charge_row_sums: None,
            };
        }
    };
    let charge_basis = match affine_charge_basis_for_point_samples(&support) {
        Ok(charge_basis) => charge_basis,
        Err(error) => {
            return LocalCygvResolvedSharedSupportHint {
                status: format!(
                    "weighted_p2_resolved_shared_support_charge_basis_error:{}",
                    status_error_fragment(&error)
                ),
                affine_rank: Some(affine_rank),
                point_indices,
                charge_basis: None,
                charge_row_sums: None,
            };
        }
    };
    let charge_row_sums = charge_basis
        .iter()
        .map(|row| row.iter().sum::<i64>())
        .collect::<Vec<_>>();
    let cy_dim = point_indices
        .len()
        .checked_sub(charge_basis.len())
        .and_then(|value| value.checked_sub(1));
    let status = if affine_rank != 3 {
        format!(
            "weighted_p2_zero_shared_ray_raises_affine_rank_{affine_rank}_requires_projection_or_chamber_map"
        )
    } else if cy_dim == Some(3) && charge_row_sums.iter().all(|&sum| sum == 0) {
        "source_witness_resolved_weighted_p2_support_has_compact_cy_threefold_charge_basis"
            .to_string()
    } else {
        format!(
            "weighted_p2_resolved_support_not_compact_cy_threefold:cy_dim={};row_sums={}",
            cy_dim.map_or_else(|| "invalid".to_string(), |value| value.to_string()),
            charge_row_sums
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>()
                .join(",")
        )
    };
    LocalCygvResolvedSharedSupportHint {
        status,
        affine_rank: Some(affine_rank),
        point_indices,
        charge_basis: Some(charge_basis),
        charge_row_sums: Some(charge_row_sums),
    }
}

fn local_cygv_resolved_shared_chamber_certificate_hint(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
) -> LocalCygvResolvedSharedChamberCertificateHint {
    let empty = |status: &str| LocalCygvResolvedSharedChamberCertificateHint {
        status: status.to_string(),
        hyperplane_count: None,
        min_pairing: None,
        max_pairing: None,
        strictly_inside: None,
    };
    let Some(q_matrix) = skeleton.local_cygv_phase_q_matrix_candidate.as_ref() else {
        return empty("resolved_shared_chamber_blocked_missing_phase_q_matrix");
    };
    if q_matrix.len() != 1 {
        return empty("resolved_shared_chamber_not_one_parameter_local_q_matrix");
    }
    if one_parameter_weighted_p2_split_bundle_signature(&q_matrix[0]).is_none() {
        return empty("resolved_shared_chamber_not_weighted_p2_split_bundle");
    }
    let Some(witness) = witness else {
        return empty("weighted_p2_resolved_shared_chamber_missing_origin_circuit_witness");
    };
    let projection_hint = local_cygv_zero_shared_affine_projection_hint(skeleton, Some(witness));
    let Some(hyperplane) = projection_hint.hyperplane.as_ref() else {
        return LocalCygvResolvedSharedChamberCertificateHint {
            status: format!(
                "weighted_p2_resolved_shared_chamber_blocked_projection_status:{}",
                projection_hint.status
            ),
            hyperplane_count: None,
            min_pairing: None,
            max_pairing: None,
            strictly_inside: None,
        };
    };
    let support = origin_circuit_resolved_shared_support_point_samples(witness);
    if support.is_empty() {
        return empty("weighted_p2_resolved_shared_chamber_missing_support_points");
    }
    let point_to_local = support
        .iter()
        .enumerate()
        .map(|(local, point)| (point.point_index, local))
        .collect::<BTreeMap<_, _>>();
    let mut shared_face = Vec::with_capacity(witness.shared_two_simplex.len() + 1);
    shared_face.push(0);
    shared_face.extend(witness.shared_two_simplex.iter().copied());
    let mut simplices = Vec::new();
    for exclusive in [
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ] {
        let mut simplex = shared_face.clone();
        simplex.push(exclusive);
        let mapped = simplex
            .iter()
            .map(|point_index| {
                point_to_local.get(point_index).copied().ok_or_else(|| {
                    format!("resolved shared chamber simplex point {point_index} missing support")
                })
            })
            .collect::<Result<Vec<_>, _>>();
        let mapped = match mapped {
            Ok(mapped) => mapped,
            Err(error) => {
                return LocalCygvResolvedSharedChamberCertificateHint {
                    status: format!(
                        "weighted_p2_resolved_shared_chamber_simplex_error:{}",
                        status_error_fragment(&error)
                    ),
                    hyperplane_count: None,
                    min_pairing: None,
                    max_pairing: None,
                    strictly_inside: None,
                };
            }
        };
        simplices.push(mapped);
    }
    let points = support
        .iter()
        .map(|point| Point::new(point.coordinates.clone()))
        .collect::<Vec<_>>();
    let heights = support
        .iter()
        .map(|point| {
            F64::<Finite>::new(affine_hyperplane_height(hyperplane, &point.coordinates) as f64)
                .expect("integer affine height is finite")
        })
        .collect::<Vec<_>>();
    let triangulation = Triangulation::new(simplices);
    let secondary_hyperplanes = match secondary_cone_hyperplanes_native(&points, &triangulation) {
        Ok(hyperplanes) => hyperplanes,
        Err(error) => {
            return LocalCygvResolvedSharedChamberCertificateHint {
                status: format!(
                    "weighted_p2_resolved_shared_chamber_secondary_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                hyperplane_count: None,
                min_pairing: None,
                max_pairing: None,
                strictly_inside: None,
            };
        }
    };
    let pairings = match secondary_cone_height_pairings(&secondary_hyperplanes, &heights) {
        Ok(pairings) => pairings,
        Err(error) => {
            return LocalCygvResolvedSharedChamberCertificateHint {
                status: format!(
                    "weighted_p2_resolved_shared_chamber_pairing_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                hyperplane_count: Some(secondary_hyperplanes.len()),
                min_pairing: None,
                max_pairing: None,
                strictly_inside: None,
            };
        }
    };
    let epsilon = F64::<Pos>::new(1e-6).expect("positive secondary cone epsilon");
    let strictly_inside = match secondary_cone_strictly_contains_height_vector(
        &secondary_hyperplanes,
        &heights,
        epsilon,
    ) {
        Ok(strictly_inside) => strictly_inside,
        Err(error) => {
            return LocalCygvResolvedSharedChamberCertificateHint {
                status: format!(
                    "weighted_p2_resolved_shared_chamber_strict_check_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                hyperplane_count: Some(secondary_hyperplanes.len()),
                min_pairing: pairing_min_string(&pairings),
                max_pairing: pairing_max_string(&pairings),
                strictly_inside: None,
            };
        }
    };
    let flipped_heights = heights
        .iter()
        .map(|height| F64::<Finite>::new(-height.get()).expect("negated finite height is finite"))
        .collect::<Vec<_>>();
    let flipped_strictly_inside = secondary_cone_strictly_contains_height_vector(
        &secondary_hyperplanes,
        &flipped_heights,
        F64::<Pos>::new(1e-6).expect("positive secondary cone epsilon"),
    )
    .unwrap_or(false);
    let status = if strictly_inside {
        "weighted_p2_resolved_shared_chamber_strictly_inside_exclusive_pair_secondary_cone"
    } else if flipped_strictly_inside {
        "weighted_p2_resolved_shared_chamber_strictly_inside_after_height_sign_flip"
    } else {
        "weighted_p2_resolved_shared_chamber_outside_or_on_wall"
    };
    LocalCygvResolvedSharedChamberCertificateHint {
        status: status.to_string(),
        hyperplane_count: Some(secondary_hyperplanes.len()),
        min_pairing: pairing_min_string(&pairings),
        max_pairing: pairing_max_string(&pairings),
        strictly_inside: Some(strictly_inside),
    }
}

fn local_cygv_resolved_shared_chamber_global_height_hint(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
    global_secondary_heights: Option<&[f64]>,
) -> LocalCygvResolvedSharedChamberGlobalHeightHint {
    let empty = |status: &str| LocalCygvResolvedSharedChamberGlobalHeightHint {
        status: status.to_string(),
        min_pairing: None,
        max_pairing: None,
        zero_pairing_count: None,
        positive_pairing_count: None,
        negative_pairing_count: None,
    };
    let Some(global_secondary_heights) = global_secondary_heights else {
        return empty("resolved_shared_chamber_global_height_missing_vector");
    };
    let Some(q_matrix) = skeleton.local_cygv_phase_q_matrix_candidate.as_ref() else {
        return empty("resolved_shared_chamber_global_height_blocked_missing_phase_q_matrix");
    };
    if q_matrix.len() != 1 {
        return empty("resolved_shared_chamber_global_height_not_one_parameter_local_q_matrix");
    }
    if one_parameter_weighted_p2_split_bundle_signature(&q_matrix[0]).is_none() {
        return empty("resolved_shared_chamber_global_height_not_weighted_p2_split_bundle");
    }
    let Some(witness) = witness else {
        return empty(
            "weighted_p2_resolved_shared_chamber_global_height_missing_origin_circuit_witness",
        );
    };
    let support = origin_circuit_resolved_shared_support_point_samples(witness);
    if support.is_empty() {
        return empty("weighted_p2_resolved_shared_chamber_global_height_missing_support_points");
    }
    let point_to_local = support
        .iter()
        .enumerate()
        .map(|(local, point)| (point.point_index, local))
        .collect::<BTreeMap<_, _>>();
    let mut shared_face = Vec::with_capacity(witness.shared_two_simplex.len() + 1);
    shared_face.push(0);
    shared_face.extend(witness.shared_two_simplex.iter().copied());
    let mut simplices = Vec::new();
    for exclusive in [
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ] {
        let mut simplex = shared_face.clone();
        simplex.push(exclusive);
        let mapped = simplex
            .iter()
            .map(|point_index| {
                point_to_local.get(point_index).copied().ok_or_else(|| {
                    format!(
                        "resolved shared global-height simplex point {point_index} missing support"
                    )
                })
            })
            .collect::<Result<Vec<_>, _>>();
        let mapped = match mapped {
            Ok(mapped) => mapped,
            Err(error) => {
                return LocalCygvResolvedSharedChamberGlobalHeightHint {
                    status: format!(
                        "weighted_p2_resolved_shared_chamber_global_height_simplex_error:{}",
                        status_error_fragment(&error)
                    ),
                    min_pairing: None,
                    max_pairing: None,
                    zero_pairing_count: None,
                    positive_pairing_count: None,
                    negative_pairing_count: None,
                };
            }
        };
        simplices.push(mapped);
    }
    let points = support
        .iter()
        .map(|point| Point::new(point.coordinates.clone()))
        .collect::<Vec<_>>();
    let heights = match support
        .iter()
        .map(|point| {
            global_secondary_heights
                .get(point.point_index)
                .copied()
                .ok_or_else(|| {
                    format!(
                        "point index {} maps to missing origin-included secondary height entry",
                        point.point_index
                    )
                })
                .and_then(|height| {
                    F64::<Finite>::new(height).ok_or_else(|| {
                        format!(
                            "point index {} has non-finite secondary height",
                            point.point_index
                        )
                    })
                })
        })
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(heights) => heights,
        Err(error) => {
            return LocalCygvResolvedSharedChamberGlobalHeightHint {
                status: format!(
                    "weighted_p2_resolved_shared_chamber_global_height_error:{}",
                    status_error_fragment(&error)
                ),
                min_pairing: None,
                max_pairing: None,
                zero_pairing_count: None,
                positive_pairing_count: None,
                negative_pairing_count: None,
            };
        }
    };
    let triangulation = Triangulation::new(simplices);
    let secondary_hyperplanes = match secondary_cone_hyperplanes_native(&points, &triangulation) {
        Ok(hyperplanes) => hyperplanes,
        Err(error) => {
            return LocalCygvResolvedSharedChamberGlobalHeightHint {
                status: format!(
                    "weighted_p2_resolved_shared_chamber_global_height_secondary_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                min_pairing: None,
                max_pairing: None,
                zero_pairing_count: None,
                positive_pairing_count: None,
                negative_pairing_count: None,
            };
        }
    };
    let pairings = match secondary_cone_height_pairings(&secondary_hyperplanes, &heights) {
        Ok(pairings) => pairings,
        Err(error) => {
            return LocalCygvResolvedSharedChamberGlobalHeightHint {
                status: format!(
                    "weighted_p2_resolved_shared_chamber_global_height_pairing_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                min_pairing: None,
                max_pairing: None,
                zero_pairing_count: None,
                positive_pairing_count: None,
                negative_pairing_count: None,
            };
        }
    };
    let zero_pairing_count = pairings
        .iter()
        .filter(|pairing| pairing.get().abs() <= 1e-6)
        .count();
    let positive_pairing_count = pairings
        .iter()
        .filter(|pairing| pairing.get() > 1e-6)
        .count();
    let negative_pairing_count = pairings
        .iter()
        .filter(|pairing| pairing.get() < -1e-6)
        .count();
    let strictly_inside = secondary_cone_strictly_contains_height_vector(
        &secondary_hyperplanes,
        &heights,
        F64::<Pos>::new(1e-6).expect("positive secondary cone epsilon"),
    )
    .unwrap_or(false);
    let flipped_heights = heights
        .iter()
        .map(|height| F64::<Finite>::new(-height.get()).expect("negated finite height is finite"))
        .collect::<Vec<_>>();
    let flipped_strictly_inside = secondary_cone_strictly_contains_height_vector(
        &secondary_hyperplanes,
        &flipped_heights,
        F64::<Pos>::new(1e-6).expect("positive secondary cone epsilon"),
    )
    .unwrap_or(false);
    let status = if pairings.is_empty() {
        "weighted_p2_resolved_shared_chamber_global_height_no_circuits"
    } else if strictly_inside {
        "weighted_p2_resolved_shared_chamber_global_height_strictly_inside_exclusive_pair_secondary_cone"
    } else if flipped_strictly_inside {
        "weighted_p2_resolved_shared_chamber_global_height_strictly_inside_after_height_sign_flip"
    } else if zero_pairing_count == pairings.len() {
        "weighted_p2_resolved_shared_chamber_global_height_on_all_walls"
    } else if negative_pairing_count == 0 {
        "weighted_p2_resolved_shared_chamber_global_height_on_wall_nonnegative"
    } else if positive_pairing_count == 0 {
        "weighted_p2_resolved_shared_chamber_global_height_on_wall_nonpositive"
    } else {
        "weighted_p2_resolved_shared_chamber_global_height_crosses_oriented_walls"
    };
    LocalCygvResolvedSharedChamberGlobalHeightHint {
        status: status.to_string(),
        min_pairing: pairing_min_string(&pairings),
        max_pairing: pairing_max_string(&pairings),
        zero_pairing_count: Some(zero_pairing_count),
        positive_pairing_count: Some(positive_pairing_count),
        negative_pairing_count: Some(negative_pairing_count),
    }
}

fn local_cygv_resolved_shared_chamber_full_union_compatibility_status(
    resolved_global_height: &LocalCygvResolvedSharedChamberGlobalHeightHint,
    global_regular: &LocalCygvStarUnionGlobalRegularTriangulationHint,
) -> String {
    if resolved_global_height.status
        != "weighted_p2_resolved_shared_chamber_global_height_strictly_inside_exclusive_pair_secondary_cone"
    {
        return format!(
            "resolved_full_union_compatibility_skipped:{}",
            resolved_global_height.status
        );
    }
    match global_regular.status.as_str() {
        "star_union_global_regular_shared_face_selects_target_exclusive_points" => {
            "resolved_global_height_strict_and_full_union_selects_target_exclusive_points"
                .to_string()
        }
        "star_union_global_regular_shared_face_matches_serialized_star_extras" => {
            "resolved_global_height_strict_but_full_union_selects_star_extras_requires_chamber_transport"
                .to_string()
        }
        "star_union_global_regular_shared_face_selects_star_extras_partial" => {
            "resolved_global_height_strict_but_full_union_selects_partial_star_extras".to_string()
        }
        "star_union_global_regular_no_shared_face_simplices" => {
            "resolved_global_height_strict_but_full_union_has_no_shared_face_simplices".to_string()
        }
        status => format!("resolved_global_height_strict_full_union_status:{status}"),
    }
}

fn pairing_min_string(pairings: &[F64<Finite>]) -> Option<String> {
    pairings
        .iter()
        .map(|pairing| pairing.get())
        .min_by(|left, right| {
            left.partial_cmp(right)
                .expect("finite secondary-cone pairing")
        })
        .map(|value| value.to_string())
}

fn pairing_max_string(pairings: &[F64<Finite>]) -> Option<String> {
    pairings
        .iter()
        .map(|pairing| pairing.get())
        .max_by(|left, right| {
            left.partial_cmp(right)
                .expect("finite secondary-cone pairing")
        })
        .map(|value| value.to_string())
}

fn local_cygv_source_resolution_hint_status(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
) -> String {
    let Some(q_matrix) = skeleton.local_cygv_phase_q_matrix_candidate.as_ref() else {
        return "local_resolution_hint_blocked_missing_phase_q_matrix".to_string();
    };
    if q_matrix.len() != 1 {
        return "local_resolution_hint_not_one_parameter_local_q_matrix".to_string();
    }
    let charges = &q_matrix[0];
    if one_parameter_weighted_p2_split_bundle_signature(charges).is_none() {
        return "local_resolution_hint_not_weighted_p2_split_bundle".to_string();
    }
    if skeleton.local_cygv_q_matrix_phase_status
        != "source_derived_unique_compact_threefold_phase_including_origin"
    {
        return format!(
            "local_resolution_hint_weighted_p2_split_bundle_blocked_phase_status:{}",
            skeleton.local_cygv_q_matrix_phase_status
        );
    }
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(witness);
    match zero_shared.len() {
        0 => "weighted_p2_split_bundle_no_zero_relation_shared_resolution_ray".to_string(),
        1 => {
            "source_witness_weighted_p2_split_bundle_has_single_zero_relation_shared_resolution_ray"
                .to_string()
        }
        _ => {
            "weighted_p2_split_bundle_has_multiple_zero_relation_shared_resolution_rays".to_string()
        }
    }
}

fn local_phase_chamber_membership_certificate_status(
    skeleton: &LocalCygvInputSkeleton,
    context: &ValidatedContext<'_>,
) -> String {
    let Some(certificate) = context.secondary_cone_height_certificate else {
        return "local_phase_chamber_blocked_missing_global_secondary_cone_certificate".to_string();
    };
    if !certificate.strictly_inside {
        return format!(
            "local_phase_chamber_blocked_global_secondary_cone_status:{}",
            certificate.status
        );
    }
    if let Some(twoface_certificate) = context.secondary_cone_2face_height_certificate
        && !twoface_certificate.strictly_inside
    {
        return format!(
            "local_phase_chamber_blocked_global_2face_secondary_cone_status:{}",
            twoface_certificate.status
        );
    }
    if skeleton.local_cygv_phase_q_matrix_candidate.is_none() {
        return "local_phase_chamber_blocked_missing_phase_q_matrix".to_string();
    }
    if skeleton.local_chamber_certificate_status
        == "source_derived_local_p2_bundle_positive_base_chamber"
    {
        return "source_derived_local_phase_chamber_certificate_with_global_secondary_cone_checkpoint"
            .to_string();
    }
    format!(
        "local_phase_chamber_blocked_{}",
        skeleton.local_chamber_certificate_status
    )
}

fn local_phase_chamber_membership_certificate_status_with_witness(
    skeleton: &LocalCygvInputSkeleton,
    witness: Option<&OriginCircuitWitnessSample>,
    context: &ValidatedContext<'_>,
) -> String {
    let status = local_phase_chamber_membership_certificate_status(skeleton, context);
    if status
        != "local_phase_chamber_blocked_local_chamber_certificate_blocked_weighted_p2_split_bundle_requires_source_derived_resolution_chamber"
    {
        return status;
    }

    let star_status = local_cygv_zero_shared_star_status(skeleton, witness);
    if star_status != "weighted_p2_zero_shared_star_uses_two_alternate_chamber_points" {
        return format!(
            "local_phase_chamber_blocked_weighted_p2_resolution_star_status:{star_status}"
        );
    }

    let resolved_chamber = local_cygv_resolved_shared_chamber_certificate_hint(skeleton, witness);
    if resolved_chamber.status
        != "weighted_p2_resolved_shared_chamber_strictly_inside_exclusive_pair_secondary_cone"
    {
        let resolved_global_height = local_cygv_resolved_shared_chamber_global_height_hint(
            skeleton,
            witness,
            context.secondary_cone_heights,
        );
        if resolved_global_height.status
            == "weighted_p2_resolved_shared_chamber_global_height_strictly_inside_exclusive_pair_secondary_cone"
        {
            return format!(
                "local_phase_chamber_blocked_weighted_p2_resolved_shared_affine_wall_global_height_strict:{}",
                resolved_chamber.status
            );
        }
        return format!(
            "local_phase_chamber_blocked_weighted_p2_resolved_shared_chamber:{}",
            resolved_chamber.status
        );
    }

    let star_support_hint = local_cygv_shared_two_simplex_star_support_hint(witness);
    let star_union_relation_hint =
        local_cygv_star_union_relation_hint(witness, &star_support_hint, Some(context.q_matrix));
    let star_union_status = format!(
        "local_phase_chamber_blocked_weighted_p2_star_union_chamber_history:{}",
        star_union_relation_hint.status
    );
    if star_union_relation_hint.status
        != "star_union_target_and_star_integral_in_union_charge_basis"
    {
        return star_union_status;
    }

    let global_regular = local_cygv_star_union_global_regular_triangulation_hint(
        witness,
        &star_support_hint,
        context.secondary_cone_heights,
    );
    if global_regular.status
        != "star_union_global_regular_shared_face_selects_target_exclusive_points"
    {
        return format!(
            "local_phase_chamber_blocked_weighted_p2_global_regular_chamber:{}",
            global_regular.status
        );
    }

    "source_derived_local_phase_chamber_certificate_weighted_p2_resolved_shared_chamber".to_string()
}

fn origin_circuit_zero_relation_shared_two_simplex_points(
    witness: Option<&OriginCircuitWitnessSample>,
) -> Vec<usize> {
    let Some(witness) = witness else {
        return Vec::new();
    };
    let relation_support = witness
        .relation_points
        .iter()
        .map(|point| point.point_index)
        .collect::<BTreeSet<_>>();
    let mut zero_shared = witness
        .shared_two_simplex
        .iter()
        .copied()
        .filter(|point| !relation_support.contains(point))
        .collect::<Vec<_>>();
    zero_shared.sort_unstable();
    zero_shared.dedup();
    zero_shared
}

fn origin_circuit_zero_relation_shared_two_simplex_point_samples(
    witness: Option<&OriginCircuitWitnessSample>,
) -> Vec<OriginCircuitRelationPointSample> {
    let Some(witness) = witness else {
        return Vec::new();
    };
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(Some(witness))
        .into_iter()
        .collect::<BTreeSet<_>>();
    witness
        .shared_two_simplex_points
        .iter()
        .filter(|point| zero_shared.contains(&point.point_index))
        .cloned()
        .collect()
}

fn origin_circuit_shared_two_simplex_star_extra_points(
    witness: Option<&OriginCircuitWitnessSample>,
) -> Vec<Vec<usize>> {
    let Some(witness) = witness else {
        return Vec::new();
    };
    let shared = witness
        .shared_two_simplex
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    witness
        .shared_two_simplex_star_simplices
        .iter()
        .map(|simplex| {
            simplex
                .iter()
                .copied()
                .filter(|point_index| *point_index != 0 && !shared.contains(point_index))
                .collect::<Vec<_>>()
        })
        .collect()
}

fn origin_circuit_shared_two_simplex_star_extra_point_samples(
    witness: Option<&OriginCircuitWitnessSample>,
) -> Vec<Vec<OriginCircuitRelationPointSample>> {
    witness
        .map(|witness| witness.shared_two_simplex_star_extra_point_samples.clone())
        .unwrap_or_default()
}

fn origin_circuit_shared_two_simplex_star_extra_affine_heights(
    witness: Option<&OriginCircuitWitnessSample>,
    hyperplane: Option<&[i64]>,
) -> Vec<Vec<PointAffineHeight>> {
    let Some(hyperplane) = hyperplane else {
        return Vec::new();
    };
    origin_circuit_shared_two_simplex_star_extra_point_samples(witness)
        .iter()
        .map(|simplex_extras| {
            simplex_extras
                .iter()
                .map(|point| PointAffineHeight {
                    point_index: point.point_index,
                    height: affine_hyperplane_height(hyperplane, &point.coordinates),
                })
                .collect::<Vec<_>>()
        })
        .collect()
}

