fn local_cygv_shared_two_simplex_star_support_hint(
    witness: Option<&OriginCircuitWitnessSample>,
) -> LocalCygvStarSupportHint {
    let empty = |status: &str| LocalCygvStarSupportHint {
        status: status.to_string(),
        point_indices: Vec::new(),
        affine_rank: None,
        charge_basis: None,
        charge_row_sums: None,
    };
    let Some(witness) = witness else {
        return empty("shared_two_simplex_star_support_missing_origin_circuit_witness");
    };
    if witness
        .shared_two_simplex_star_extra_point_samples
        .is_empty()
    {
        return empty("shared_two_simplex_star_support_missing_extra_point_samples");
    }
    let mut by_point = BTreeMap::new();
    if let Some(origin) = witness
        .relation_points
        .iter()
        .find(|point| point.point_index == 0)
        .cloned()
    {
        by_point.insert(origin.point_index, origin);
    }
    for point in &witness.shared_two_simplex_points {
        by_point.insert(point.point_index, point.clone());
    }
    for point in witness
        .shared_two_simplex_star_extra_point_samples
        .iter()
        .flatten()
    {
        by_point.insert(point.point_index, point.clone());
    }
    let support = by_point.into_values().collect::<Vec<_>>();
    let point_indices = support
        .iter()
        .map(|point| point.point_index)
        .collect::<Vec<_>>();
    let affine_rank = match affine_rank_for_point_samples(&support) {
        Ok(rank) => rank,
        Err(error) => {
            return LocalCygvStarSupportHint {
                status: format!(
                    "shared_two_simplex_star_support_affine_rank_error:{}",
                    status_error_fragment(&error)
                ),
                point_indices,
                affine_rank: None,
                charge_basis: None,
                charge_row_sums: None,
            };
        }
    };
    let charge_basis = match affine_charge_basis_for_point_samples(&support) {
        Ok(charge_basis) => charge_basis,
        Err(error) => {
            return LocalCygvStarSupportHint {
                status: format!(
                    "shared_two_simplex_star_support_charge_basis_error:{}",
                    status_error_fragment(&error)
                ),
                point_indices,
                affine_rank: Some(affine_rank),
                charge_basis: None,
                charge_row_sums: None,
            };
        }
    };
    let charge_row_sums = charge_basis
        .iter()
        .map(|row| row.iter().sum::<i64>())
        .collect::<Vec<_>>();
    LocalCygvStarSupportHint {
        status: format!(
            "shared_two_simplex_star_support_affine_rank_{affine_rank}_charge_rows_{}",
            charge_basis.len()
        ),
        point_indices,
        affine_rank: Some(affine_rank),
        charge_basis: Some(charge_basis),
        charge_row_sums: Some(charge_row_sums),
    }
}

fn local_cygv_shared_two_simplex_star_reduction_hint(
    hint: &LocalCygvStarSupportHint,
) -> LocalCygvStarReductionHint {
    let empty = |status: &str| LocalCygvStarReductionHint {
        status: status.to_string(),
        zero_charge_points: Vec::new(),
        reduced_charge_row: None,
    };
    let Some(charge_basis) = hint.charge_basis.as_ref() else {
        return empty("star_reduction_blocked_missing_charge_basis");
    };
    if charge_basis.len() != 1 {
        return empty("star_reduction_blocked_not_one_parameter_charge_basis");
    }
    let charge_row = &charge_basis[0];
    if charge_row.len() != hint.point_indices.len() {
        return empty("star_reduction_blocked_charge_width_mismatch");
    }
    let mut zero_charge_points = Vec::new();
    let mut reduced_charge_row = Vec::new();
    for (&point_index, &charge) in hint.point_indices.iter().zip(charge_row.iter()) {
        if charge == 0 {
            zero_charge_points.push(point_index);
        } else {
            reduced_charge_row.push(charge);
        }
    }
    if zero_charge_points.is_empty() {
        return LocalCygvStarReductionHint {
            status: "star_reduction_no_zero_charge_columns".to_string(),
            zero_charge_points,
            reduced_charge_row: Some(reduced_charge_row),
        };
    }
    if reduced_charge_row.is_empty() {
        return LocalCygvStarReductionHint {
            status: "star_reduction_all_columns_zero".to_string(),
            zero_charge_points,
            reduced_charge_row: Some(reduced_charge_row),
        };
    }
    if reduced_charge_row.iter().sum::<i64>() != 0 {
        return LocalCygvStarReductionHint {
            status: "star_reduction_nonzero_reduced_charge_not_calabi_yau".to_string(),
            zero_charge_points,
            reduced_charge_row: Some(reduced_charge_row),
        };
    }
    let status = classify_zero_charge_reduced_one_parameter_family(&reduced_charge_row);
    LocalCygvStarReductionHint {
        status,
        zero_charge_points,
        reduced_charge_row: Some(reduced_charge_row),
    }
}

fn classify_zero_charge_reduced_one_parameter_family(charges: &[i64]) -> String {
    let mut sorted = charges.to_vec();
    sorted.sort_unstable();
    if sorted == [-1, -1, 1, 1] {
        return "star_reduction_resolved_conifold_charge_family_with_spectator_zero_charges"
            .to_string();
    }
    if let Some(signature) = one_parameter_weighted_p2_split_bundle_signature(charges) {
        return format!(
            "star_reduction_weighted_p2_split_bundle_after_zero_charge_removal:{signature}"
        );
    }
    let flipped = charges.iter().map(|&value| -value).collect::<Vec<_>>();
    if let Some(signature) = one_parameter_weighted_p2_split_bundle_signature(&flipped) {
        return format!(
            "star_reduction_weighted_p2_split_bundle_after_zero_charge_removal_and_sign_flip:{signature}"
        );
    }
    format!(
        "star_reduction_uncertified_nonzero_charge_family:{}",
        sorted
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(",")
    )
}

fn local_cygv_star_reduced_unit_tensor_probe(
    reduction: &LocalCygvStarReductionHint,
) -> LocalCygvStarReducedUnitTensorProbe {
    let Some(reduced_charge_row) = reduction.reduced_charge_row.as_ref() else {
        return LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status: "star_reduced_unit_tensor_probe_not_run_no_reduced_charge_row".to_string(),
            error: None,
        };
    };
    if reduced_charge_row.is_empty() {
        return LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status: "star_reduced_unit_tensor_probe_not_run_empty_reduced_charge_row".to_string(),
            error: None,
        };
    }
    if reduced_charge_row.iter().sum::<i64>() != 0 {
        return LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status: "star_reduced_unit_tensor_probe_not_run_non_calabi_yau_charge".to_string(),
            error: None,
        };
    }
    let q_matrix = vec![reduced_charge_row.clone()];
    match one_parameter_primitive_cygv_value(
        &q_matrix,
        &[1],
        &[vec![0], vec![1]],
        MalachiteRational::from(1),
    ) {
        Ok(value) => LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: Some(value),
            status: "star_reduced_unit_tensor_probe_computed_with_unit_tensor_uncertified"
                .to_string(),
            error: None,
        },
        Err(error) => LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status: "star_reduced_unit_tensor_probe_hkty_error".to_string(),
            error: Some(error),
        },
    }
}

fn local_cygv_star_union_target_plus_star_unit_tensor_probe(
    target_plus_star: &[(usize, i64)],
) -> LocalCygvStarReducedUnitTensorProbe {
    if target_plus_star.is_empty() {
        return LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status:
                "star_union_target_plus_star_unit_tensor_probe_not_run_empty_target_plus_star_row"
                    .to_string(),
            error: None,
        };
    }
    let charge_row = target_plus_star
        .iter()
        .map(|(_, coefficient)| *coefficient)
        .collect::<Vec<_>>();
    if charge_row.iter().sum::<i64>() != 0 {
        return LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status: "star_union_target_plus_star_unit_tensor_probe_not_run_non_calabi_yau_charge"
                .to_string(),
            error: None,
        };
    }
    let cy_dim = i64::try_from(charge_row.len())
        .ok()
        .and_then(|len| len.checked_sub(2));
    let shape_status = match cy_dim {
        Some(3) => "compact_threefold_shape".to_string(),
        Some(cy_dim) => format!("not_compact_threefold_shape_cy_dim_{cy_dim}"),
        None => "shape_dimension_overflow".to_string(),
    };
    let q_matrix = vec![charge_row];
    match one_parameter_primitive_cygv_value(
        &q_matrix,
        &[1],
        &[vec![0], vec![1]],
        MalachiteRational::from(1),
    ) {
        Ok(value) => LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: Some(value),
            status: format!(
                "star_union_target_plus_star_unit_tensor_probe_computed_with_unit_tensor_{shape_status}_uncertified"
            ),
            error: None,
        },
        Err(error) => LocalCygvStarReducedUnitTensorProbe {
            candidate_gv: None,
            status: "star_union_target_plus_star_unit_tensor_probe_hkty_error".to_string(),
            error: Some(error),
        },
    }
}

fn local_cygv_star_union_target_plus_star_path_history_probe(
    target_plus_star_basis_nonzero: Option<&Vec<(usize, i64)>>,
    context: &ValidatedContext<'_>,
    run_probe: bool,
    element_limit: usize,
    lower_seed_pair_limit: usize,
    closure_generation_limit: Option<usize>,
) -> Option<LocalCygvStarUnionPathHistoryProbe> {
    if !run_probe {
        return None;
    }

    let empty = |status: &str,
                 degree: Option<i128>,
                 seed_count: Option<usize>,
                 reduced_seed_count: Option<usize>,
                 error: Option<String>|
     -> LocalCygvStarUnionPathHistoryProbe {
        LocalCygvStarUnionPathHistoryProbe {
            status: status.to_string(),
            degree,
            seed_count,
            reduced_seed_count,
            closure_element_count: None,
            closure_generation_counts: Vec::new(),
            closure_degree_counts: BTreeMap::new(),
            target_in_closure: None,
            lower_seed_decomposition_status: status.to_string(),
            lower_seed_decomposition_term_count: None,
            lower_seed_decomposition_terms_nonzero: None,
            lower_seed_decomposition_term_degree_counts: BTreeMap::new(),
            lower_seed_decomposition_term_known_qn_history_status_counts: BTreeMap::new(),
            lower_seed_decomposition_term_source_class_status_counts: BTreeMap::new(),
            lower_seed_decomposition_search_stats: None,
            error,
        }
    };

    let Some(target_plus_star_basis_nonzero) = target_plus_star_basis_nonzero else {
        return Some(empty(
            "skipped_missing_target_plus_star_global_basis_projection",
            None,
            None,
            None,
            None,
        ));
    };
    let target = match dense_from_sparse(target_plus_star_basis_nonzero, context.dimension) {
        Ok(target) => target,
        Err(error) => {
            return Some(empty(
                "error_invalid_target_plus_star_global_basis_projection",
                None,
                None,
                None,
                Some(error),
            ));
        }
    };
    let target_degree = match curve_degree(&target, context.grading) {
        Ok(degree) => degree,
        Err(error) => {
            return Some(empty(
                "error_invalid_target_plus_star_degree",
                None,
                None,
                None,
                Some(error),
            ));
        }
    };
    if target_degree <= 0 {
        return Some(empty(
            "skipped_nonpositive_target_plus_star_degree",
            Some(target_degree),
            None,
            None,
            None,
        ));
    }

    let mut seeds = Vec::new();
    let mut seen = HashSet::new();
    for ray in context.degree_bounded_rays {
        let degree = match curve_degree(ray, context.grading) {
            Ok(degree) => degree,
            Err(error) => {
                return Some(empty(
                    "error_invalid_degree_bounded_seed_degree",
                    Some(target_degree),
                    None,
                    None,
                    Some(error),
                ));
            }
        };
        if degree <= 0 || degree > target_degree {
            continue;
        }
        if seen.insert(ray.clone()) {
            seeds.push(ray.clone());
        }
    }
    if seeds.is_empty() {
        return Some(empty(
            "skipped_empty_target_plus_star_seed_set",
            Some(target_degree),
            Some(0),
            Some(0),
            None,
        ));
    }
    if seeds.len() > lower_seed_pair_limit {
        return Some(empty(
            &format!("skipped_seed_pair_limit_{lower_seed_pair_limit}"),
            Some(target_degree),
            Some(seeds.len()),
            None,
            None,
        ));
    }

    let reduced_seed_count = match cygv_pair_reduced_seed_generators(&seeds) {
        Ok(reduced_seeds) => reduced_seeds.len(),
        Err(error) => {
            return Some(empty(
                "error_cygv_seed_reduction_failed",
                Some(target_degree),
                Some(seeds.len()),
                None,
                Some(error.to_string()),
            ));
        }
    };
    let lower_seed_decomposition = lower_seed_decomposition_probe(
        &target,
        &seeds,
        STAR_UNION_LOWER_SEED_DECOMPOSITION_MAX_TERMS,
        lower_seed_pair_limit,
        Some(context.grading),
    );
    let lower_seed_decomposition_term_degree_counts = lower_seed_decomposition_term_degree_counts(
        lower_seed_decomposition.terms.as_deref(),
        context,
    );
    let lower_seed_decomposition_term_known_qn_history_status_counts =
        lower_seed_decomposition_term_known_qn_history_status_counts(
            lower_seed_decomposition.terms.as_deref(),
            context,
        );
    let lower_seed_decomposition_term_source_class_status_counts =
        lower_seed_decomposition_term_source_class_status_counts(
            lower_seed_decomposition.terms.as_deref(),
            context,
        );
    let closure = match streaming_bounded_cygv_semigroup_closure(
        &seeds,
        context.grading,
        target_degree,
        element_limit,
        closure_generation_limit,
    ) {
        Ok(closure) => closure,
        Err(error) => {
            return Some(LocalCygvStarUnionPathHistoryProbe {
                status: "error_bounded_closure_failed".to_string(),
                degree: Some(target_degree),
                seed_count: Some(seeds.len()),
                reduced_seed_count: Some(reduced_seed_count),
                closure_element_count: None,
                closure_generation_counts: Vec::new(),
                closure_degree_counts: BTreeMap::new(),
                target_in_closure: None,
                lower_seed_decomposition_status: lower_seed_decomposition.status,
                lower_seed_decomposition_term_count: lower_seed_decomposition.term_count,
                lower_seed_decomposition_terms_nonzero: lower_seed_decomposition.terms_nonzero,
                lower_seed_decomposition_term_degree_counts,
                lower_seed_decomposition_term_known_qn_history_status_counts,
                lower_seed_decomposition_term_source_class_status_counts,
                lower_seed_decomposition_search_stats: lower_seed_decomposition.search_stats,
                error: Some(error),
            });
        }
    };

    Some(LocalCygvStarUnionPathHistoryProbe {
        status: closure.status,
        degree: Some(target_degree),
        seed_count: Some(seeds.len()),
        reduced_seed_count: Some(reduced_seed_count),
        closure_element_count: Some(closure.elements.len()),
        closure_generation_counts: closure.generation_counts,
        closure_degree_counts: closure.degree_counts,
        target_in_closure: Some(closure.elements.contains(&target)),
        lower_seed_decomposition_status: lower_seed_decomposition.status,
        lower_seed_decomposition_term_count: lower_seed_decomposition.term_count,
        lower_seed_decomposition_terms_nonzero: lower_seed_decomposition.terms_nonzero,
        lower_seed_decomposition_term_degree_counts,
        lower_seed_decomposition_term_known_qn_history_status_counts,
        lower_seed_decomposition_term_source_class_status_counts,
        lower_seed_decomposition_search_stats: lower_seed_decomposition.search_stats,
        error: lower_seed_decomposition.error,
    })
}

fn lower_seed_decomposition_term_degree_counts(
    terms: Option<&[Vec<i64>]>,
    context: &ValidatedContext<'_>,
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    let Some(terms) = terms else {
        return counts;
    };
    for term in terms {
        let status = match curve_degree(term, context.grading) {
            Ok(degree) => degree.to_string(),
            Err(error) => format!("error_{}", status_error_fragment(&error)),
        };
        *counts.entry(status).or_insert(0usize) += 1;
    }
    counts
}

fn lower_seed_decomposition_term_known_qn_history_status_counts(
    terms: Option<&[Vec<i64>]>,
    context: &ValidatedContext<'_>,
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    let Some(terms) = terms else {
        return counts;
    };
    for term in terms {
        let (status, _, _, _) = global_basis_known_qn_history(term, context);
        *counts.entry(status).or_insert(0usize) += 1;
    }
    counts
}

fn lower_seed_decomposition_term_source_class_status_counts(
    terms: Option<&[Vec<i64>]>,
    context: &ValidatedContext<'_>,
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    let Some(terms) = terms else {
        return counts;
    };
    for term in terms {
        let (status, _) = global_basis_source_class_lookup(term, context);
        *counts
            .entry(status.unwrap_or_else(|| "source_class_missing".to_string()))
            .or_insert(0usize) += 1;
    }
    counts
}

fn local_cygv_star_target_relation_hint(
    witness: Option<&OriginCircuitWitnessSample>,
    star_support: &LocalCygvStarSupportHint,
) -> LocalCygvStarTargetRelationHint {
    let empty = |status: &str| LocalCygvStarTargetRelationHint {
        status: status.to_string(),
        missing_points: Vec::new(),
        extra_star_points: Vec::new(),
        coordinates: None,
    };
    let Some(witness) = witness else {
        return empty("star_target_relation_missing_origin_circuit_witness");
    };
    if star_support.point_indices.is_empty() {
        return empty("star_target_relation_missing_star_support");
    }
    let relation_by_point = witness
        .relation_points
        .iter()
        .map(|point| (point.point_index, point.coefficient))
        .collect::<BTreeMap<_, _>>();
    let relation_points = relation_by_point.keys().copied().collect::<BTreeSet<_>>();
    let star_points = star_support
        .point_indices
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let missing_points = relation_points
        .difference(&star_points)
        .copied()
        .collect::<Vec<_>>();
    let extra_star_points = star_points
        .difference(&relation_points)
        .copied()
        .collect::<Vec<_>>();
    if !missing_points.is_empty() {
        return LocalCygvStarTargetRelationHint {
            status: "star_target_relation_not_supported_by_star_support".to_string(),
            missing_points,
            extra_star_points,
            coordinates: None,
        };
    }
    let target = star_support
        .point_indices
        .iter()
        .map(|point_index| relation_by_point.get(point_index).copied().unwrap_or(0))
        .collect::<Vec<_>>();
    let Some(charge_basis) = star_support.charge_basis.as_ref() else {
        return LocalCygvStarTargetRelationHint {
            status: "star_target_relation_blocked_missing_star_charge_basis".to_string(),
            missing_points,
            extra_star_points,
            coordinates: None,
        };
    };
    let coordinates = match relation_coordinates_in_local_charge_basis(&target, charge_basis) {
        Ok(coordinates) => coordinates,
        Err(error) => {
            return LocalCygvStarTargetRelationHint {
                status: format!(
                    "star_target_relation_coordinate_error:{}",
                    status_error_fragment(&error)
                ),
                missing_points,
                extra_star_points,
                coordinates: None,
            };
        }
    };
    let status = if coordinates.is_some() {
        "star_target_relation_integral_in_star_charge_basis"
    } else {
        "star_target_relation_not_in_star_charge_basis"
    };
    LocalCygvStarTargetRelationHint {
        status: status.to_string(),
        missing_points,
        extra_star_points,
        coordinates,
    }
}

fn local_cygv_star_union_affine_height_profile(
    witness: Option<&OriginCircuitWitnessSample>,
    star_support: &LocalCygvStarSupportHint,
    hyperplane: Option<&[i64]>,
) -> Vec<StarUnionAffineHeight> {
    let (Some(witness), Some(hyperplane), Some(star_charge_basis)) =
        (witness, hyperplane, star_support.charge_basis.as_ref())
    else {
        return Vec::new();
    };
    let Some(star_charge_row) = star_charge_basis.first() else {
        return Vec::new();
    };
    if star_charge_basis.len() != 1 || star_charge_row.len() != star_support.point_indices.len() {
        return Vec::new();
    }
    let support = origin_circuit_star_union_point_samples(witness, star_support);
    if support.is_empty() {
        return Vec::new();
    }
    let target_by_point = witness
        .relation_points
        .iter()
        .map(|point| (point.point_index, point.coefficient))
        .collect::<BTreeMap<_, _>>();
    let star_by_point = star_support
        .point_indices
        .iter()
        .copied()
        .zip(star_charge_row.iter().copied())
        .collect::<BTreeMap<_, _>>();
    let shared_two_simplex = witness
        .shared_two_simplex
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(Some(witness))
        .into_iter()
        .collect::<BTreeSet<_>>();
    let relation_exclusive = BTreeSet::from([
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ]);
    let star_extra = origin_circuit_shared_two_simplex_star_extra_points(Some(witness))
        .into_iter()
        .flatten()
        .collect::<BTreeSet<_>>();
    support
        .into_iter()
        .map(|point| {
            let target_coefficient = target_by_point
                .get(&point.point_index)
                .copied()
                .unwrap_or(0);
            let star_coefficient = star_by_point.get(&point.point_index).copied().unwrap_or(0);
            StarUnionAffineHeight {
                role: star_union_point_role(
                    point.point_index,
                    &zero_shared,
                    &shared_two_simplex,
                    &relation_exclusive,
                    &star_extra,
                    &target_by_point,
                    &star_by_point,
                ),
                point_index: point.point_index,
                target_coefficient,
                star_coefficient,
                target_minus_star_coefficient: target_coefficient - star_coefficient,
                target_plus_star_coefficient: target_coefficient + star_coefficient,
                height: affine_hyperplane_height(hyperplane, &point.coordinates),
            }
        })
        .collect()
}

fn star_union_point_role(
    point_index: usize,
    zero_shared: &BTreeSet<usize>,
    shared_two_simplex: &BTreeSet<usize>,
    relation_exclusive: &BTreeSet<usize>,
    star_extra: &BTreeSet<usize>,
    target_by_point: &BTreeMap<usize, i64>,
    star_by_point: &BTreeMap<usize, i64>,
) -> String {
    if point_index == 0 {
        "origin".to_string()
    } else if zero_shared.contains(&point_index) {
        "zero_relation_shared_two_simplex".to_string()
    } else if relation_exclusive.contains(&point_index) {
        "origin_circuit_exclusive".to_string()
    } else if shared_two_simplex.contains(&point_index) {
        "relation_shared_two_simplex".to_string()
    } else if star_extra.contains(&point_index) {
        "star_extra".to_string()
    } else if target_by_point.contains_key(&point_index) {
        "target_relation".to_string()
    } else if star_by_point.contains_key(&point_index) {
        "star_support".to_string()
    } else {
        "star_union_support".to_string()
    }
}

fn star_union_point_role_map(
    witness: &OriginCircuitWitnessSample,
    star_support: &LocalCygvStarSupportHint,
) -> BTreeMap<usize, String> {
    let target_by_point = witness
        .relation_points
        .iter()
        .map(|point| (point.point_index, point.coefficient))
        .collect::<BTreeMap<_, _>>();
    let star_by_point = star_support
        .point_indices
        .iter()
        .copied()
        .map(|point_index| (point_index, 0_i64))
        .collect::<BTreeMap<_, _>>();
    let shared_two_simplex = witness
        .shared_two_simplex
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let zero_shared = origin_circuit_zero_relation_shared_two_simplex_points(Some(witness))
        .into_iter()
        .collect::<BTreeSet<_>>();
    let relation_exclusive = BTreeSet::from([
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ]);
    let star_extra = origin_circuit_shared_two_simplex_star_extra_points(Some(witness))
        .into_iter()
        .flatten()
        .collect::<BTreeSet<_>>();
    origin_circuit_star_union_point_samples(witness, star_support)
        .into_iter()
        .map(|point| {
            (
                point.point_index,
                star_union_point_role(
                    point.point_index,
                    &zero_shared,
                    &shared_two_simplex,
                    &relation_exclusive,
                    &star_extra,
                    &target_by_point,
                    &star_by_point,
                ),
            )
        })
        .collect()
}

fn star_union_circuit_role_counts(
    nonzero: &[(usize, i64)],
    role_by_point: &BTreeMap<usize, String>,
) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for &(point_index, _) in nonzero {
        let role = role_by_point
            .get(&point_index)
            .cloned()
            .unwrap_or_else(|| "unknown".to_string());
        *counts.entry(role).or_insert(0) += 1;
    }
    counts
}

fn star_union_circuit_role_signed_sums(
    nonzero: &[(usize, i64)],
    role_by_point: &BTreeMap<usize, String>,
) -> BTreeMap<String, i64> {
    let mut sums = BTreeMap::new();
    for &(point_index, coefficient) in nonzero {
        let role = role_by_point
            .get(&point_index)
            .cloned()
            .unwrap_or_else(|| "unknown".to_string());
        *sums.entry(role).or_insert(0) += coefficient;
    }
    sums
}

fn local_cygv_star_union_off_height_lookup_sample(
    height_profile: &[StarUnionAffineHeight],
    context: &ValidatedContext<'_>,
) -> Vec<LocalCygvStarUnionOffHeightLookup> {
    ["target", "star", "target_minus_star", "target_plus_star"]
        .into_iter()
        .map(|role| local_cygv_star_union_off_height_lookup(role, height_profile, context))
        .collect()
}

fn local_cygv_star_union_chamber_coverage_hint(
    witness: Option<&OriginCircuitWitnessSample>,
    star_support: &LocalCygvStarSupportHint,
) -> LocalCygvStarUnionChamberCoverageHint {
    let empty = |status: &str| LocalCygvStarUnionChamberCoverageHint {
        status: status.to_string(),
        covered_simplex_count: 0,
        uncovered_point_indices: Vec::new(),
    };
    let Some(witness) = witness else {
        return empty("star_union_chamber_coverage_missing_origin_circuit_witness");
    };
    if star_support.point_indices.is_empty() {
        return empty("star_union_chamber_coverage_missing_star_support");
    }
    if witness.shared_two_simplex_star_simplices.is_empty() {
        return empty("star_union_chamber_coverage_missing_star_simplices");
    }
    let union_points = origin_circuit_star_union_point_samples(witness, star_support)
        .into_iter()
        .map(|point| point.point_index)
        .collect::<BTreeSet<_>>();
    if union_points.is_empty() {
        return empty("star_union_chamber_coverage_missing_union_points");
    }
    let covered_points = witness
        .shared_two_simplex_star_simplices
        .iter()
        .flatten()
        .copied()
        .filter(|point_index| union_points.contains(point_index))
        .collect::<BTreeSet<_>>();
    let uncovered_point_indices = union_points
        .difference(&covered_points)
        .copied()
        .collect::<Vec<_>>();
    let relation_points = witness
        .relation_points
        .iter()
        .map(|point| point.point_index)
        .collect::<BTreeSet<_>>();
    let star_points = star_support
        .point_indices
        .iter()
        .copied()
        .collect::<BTreeSet<_>>();
    let status = if uncovered_point_indices.is_empty() {
        "star_union_chamber_star_triangulation_covers_union_points"
    } else if uncovered_point_indices.iter().all(|point_index| {
        relation_points.contains(point_index) && !star_points.contains(point_index)
    }) {
        "star_union_chamber_blocked_star_triangulation_missing_target_relation_points"
    } else {
        "star_union_chamber_blocked_star_triangulation_missing_union_points"
    };
    LocalCygvStarUnionChamberCoverageHint {
        status: status.to_string(),
        covered_simplex_count: witness.shared_two_simplex_star_simplices.len(),
        uncovered_point_indices,
    }
}

fn local_cygv_star_union_shared_face_secondary_hint(
    witness: Option<&OriginCircuitWitnessSample>,
    star_support: &LocalCygvStarSupportHint,
    hyperplane: Option<&[i64]>,
    global_secondary_heights: Option<&[f64]>,
) -> LocalCygvStarUnionSharedFaceSecondaryHint {
    let empty = |status: &str| LocalCygvStarUnionSharedFaceSecondaryHint {
        status: status.to_string(),
        simplex_count: None,
        hyperplane_count: None,
        min_pairing: None,
        max_pairing: None,
        zero_pairing_count: None,
        negative_pairing_count: None,
        strictly_inside: None,
        flipped_strictly_inside: None,
        global_height_status: "star_union_shared_face_secondary_global_height_not_evaluated"
            .to_string(),
        global_height_min_pairing: None,
        global_height_max_pairing: None,
        global_height_zero_pairing_count: None,
        global_height_positive_pairing_count: None,
        global_height_negative_pairing_count: None,
        circuit_sample: Vec::new(),
    };
    let Some(witness) = witness else {
        return empty("star_union_shared_face_secondary_missing_origin_circuit_witness");
    };
    let Some(hyperplane) = hyperplane else {
        return empty("star_union_shared_face_secondary_missing_affine_hyperplane");
    };
    if star_support.point_indices.is_empty() {
        return empty("star_union_shared_face_secondary_missing_star_support");
    }
    let support = origin_circuit_star_union_point_samples(witness, star_support);
    if support.is_empty() {
        return empty("star_union_shared_face_secondary_missing_union_points");
    }
    let point_to_local = support
        .iter()
        .enumerate()
        .map(|(local, point)| (point.point_index, local))
        .collect::<BTreeMap<_, _>>();
    let mut shared_face = Vec::with_capacity(witness.shared_two_simplex.len() + 1);
    shared_face.push(0);
    shared_face.extend(witness.shared_two_simplex.iter().copied());
    shared_face.sort_unstable();
    shared_face.dedup();
    if shared_face.len() != 4 {
        return LocalCygvStarUnionSharedFaceSecondaryHint {
            status: format!(
                "star_union_shared_face_secondary_blocked_shared_face_size_{}",
                shared_face.len()
            ),
            simplex_count: None,
            hyperplane_count: None,
            min_pairing: None,
            max_pairing: None,
            zero_pairing_count: None,
            negative_pairing_count: None,
            strictly_inside: None,
            flipped_strictly_inside: None,
            global_height_status: "star_union_shared_face_secondary_global_height_not_evaluated"
                .to_string(),
            global_height_min_pairing: None,
            global_height_max_pairing: None,
            global_height_zero_pairing_count: None,
            global_height_positive_pairing_count: None,
            global_height_negative_pairing_count: None,
            circuit_sample: Vec::new(),
        };
    }
    let mut exclusive_points = vec![
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ];
    exclusive_points.extend(
        origin_circuit_shared_two_simplex_star_extra_points(Some(witness))
            .into_iter()
            .flatten(),
    );
    exclusive_points.sort_unstable();
    exclusive_points.dedup();
    if exclusive_points.len() < 2 {
        return LocalCygvStarUnionSharedFaceSecondaryHint {
            status: format!(
                "star_union_shared_face_secondary_blocked_exclusive_point_count_{}",
                exclusive_points.len()
            ),
            simplex_count: None,
            hyperplane_count: None,
            min_pairing: None,
            max_pairing: None,
            zero_pairing_count: None,
            negative_pairing_count: None,
            strictly_inside: None,
            flipped_strictly_inside: None,
            global_height_status: "star_union_shared_face_secondary_global_height_not_evaluated"
                .to_string(),
            global_height_min_pairing: None,
            global_height_max_pairing: None,
            global_height_zero_pairing_count: None,
            global_height_positive_pairing_count: None,
            global_height_negative_pairing_count: None,
            circuit_sample: Vec::new(),
        };
    }
    let simplices = match exclusive_points
        .iter()
        .map(|&exclusive| {
            let mut simplex = shared_face.clone();
            simplex.push(exclusive);
            simplex
                .iter()
                .map(|point_index| {
                    point_to_local.get(point_index).copied().ok_or_else(|| {
                        format!("shared-face fan point {point_index} missing union support")
                    })
                })
                .collect::<Result<Vec<_>, _>>()
        })
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(simplices) => simplices,
        Err(error) => {
            return LocalCygvStarUnionSharedFaceSecondaryHint {
                status: format!(
                    "star_union_shared_face_secondary_simplex_error:{}",
                    status_error_fragment(&error)
                ),
                simplex_count: None,
                hyperplane_count: None,
                min_pairing: None,
                max_pairing: None,
                zero_pairing_count: None,
                negative_pairing_count: None,
                strictly_inside: None,
                flipped_strictly_inside: None,
                global_height_status:
                    "star_union_shared_face_secondary_global_height_not_evaluated".to_string(),
                global_height_min_pairing: None,
                global_height_max_pairing: None,
                global_height_zero_pairing_count: None,
                global_height_positive_pairing_count: None,
                global_height_negative_pairing_count: None,
                circuit_sample: Vec::new(),
            };
        }
    };
    let points = support
        .iter()
        .map(|point| Point::new(point.coordinates.clone()))
        .collect::<Vec<_>>();
    let heights = support
        .iter()
        .map(|point| {
            F64::<Finite>::new(affine_hyperplane_height(hyperplane, &point.coordinates) as f64)
                .expect("integer affine height is finite")
        })
        .collect::<Vec<_>>();
    let triangulation = Triangulation::new(simplices);
    let secondary_hyperplanes = match secondary_cone_hyperplanes_native(&points, &triangulation) {
        Ok(hyperplanes) => hyperplanes,
        Err(error) => {
            return LocalCygvStarUnionSharedFaceSecondaryHint {
                status: format!(
                    "star_union_shared_face_secondary_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                simplex_count: Some(triangulation.simplices().len()),
                hyperplane_count: None,
                min_pairing: None,
                max_pairing: None,
                zero_pairing_count: None,
                negative_pairing_count: None,
                strictly_inside: None,
                flipped_strictly_inside: None,
                global_height_status:
                    "star_union_shared_face_secondary_global_height_not_evaluated".to_string(),
                global_height_min_pairing: None,
                global_height_max_pairing: None,
                global_height_zero_pairing_count: None,
                global_height_positive_pairing_count: None,
                global_height_negative_pairing_count: None,
                circuit_sample: Vec::new(),
            };
        }
    };
    let pairings = match secondary_cone_height_pairings(&secondary_hyperplanes, &heights) {
        Ok(pairings) => pairings,
        Err(error) => {
            return LocalCygvStarUnionSharedFaceSecondaryHint {
                status: format!(
                    "star_union_shared_face_secondary_pairing_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                simplex_count: Some(triangulation.simplices().len()),
                hyperplane_count: Some(secondary_hyperplanes.len()),
                min_pairing: None,
                max_pairing: None,
                zero_pairing_count: None,
                negative_pairing_count: None,
                strictly_inside: None,
                flipped_strictly_inside: None,
                global_height_status:
                    "star_union_shared_face_secondary_global_height_not_evaluated".to_string(),
                global_height_min_pairing: None,
                global_height_max_pairing: None,
                global_height_zero_pairing_count: None,
                global_height_positive_pairing_count: None,
                global_height_negative_pairing_count: None,
                circuit_sample: Vec::new(),
            };
        }
    };
    let epsilon = F64::<Pos>::new(1e-6).expect("positive secondary cone epsilon");
    let strictly_inside = match secondary_cone_strictly_contains_height_vector(
        &secondary_hyperplanes,
        &heights,
        epsilon,
    ) {
        Ok(strictly_inside) => strictly_inside,
        Err(error) => {
            return LocalCygvStarUnionSharedFaceSecondaryHint {
                status: format!(
                    "star_union_shared_face_secondary_strict_check_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                simplex_count: Some(triangulation.simplices().len()),
                hyperplane_count: Some(secondary_hyperplanes.len()),
                min_pairing: pairing_min_string(&pairings),
                max_pairing: pairing_max_string(&pairings),
                zero_pairing_count: None,
                negative_pairing_count: None,
                strictly_inside: None,
                flipped_strictly_inside: None,
                global_height_status:
                    "star_union_shared_face_secondary_global_height_not_evaluated".to_string(),
                global_height_min_pairing: None,
                global_height_max_pairing: None,
                global_height_zero_pairing_count: None,
                global_height_positive_pairing_count: None,
                global_height_negative_pairing_count: None,
                circuit_sample: Vec::new(),
            };
        }
    };
    let flipped_heights = heights
        .iter()
        .map(|height| F64::<Finite>::new(-height.get()).expect("negated finite height is finite"))
        .collect::<Vec<_>>();
    let flipped_strictly_inside = secondary_cone_strictly_contains_height_vector(
        &secondary_hyperplanes,
        &flipped_heights,
        F64::<Pos>::new(1e-6).expect("positive secondary cone epsilon"),
    )
    .unwrap_or(false);
    let zero_pairing_count = pairings
        .iter()
        .filter(|pairing| pairing.get().abs() <= 1e-6)
        .count();
    let negative_pairing_count = pairings
        .iter()
        .filter(|pairing| pairing.get() < -1e-6)
        .count();
    let global_height_summary = local_cygv_star_union_global_secondary_height_summary(
        &support,
        &secondary_hyperplanes,
        global_secondary_heights,
    );
    let role_by_point = star_union_point_role_map(witness, star_support);
    let circuit_sample = secondary_hyperplanes
        .iter()
        .zip(pairings.iter())
        .zip(global_height_summary.circuit_pairings.iter())
        .zip(global_height_summary.circuit_pairing_orientations.iter())
        .map(
            |(((hyperplane, pairing), global_height_pairing), global_height_orientation)| {
                let nonzero = support
                    .iter()
                    .zip(hyperplane.iter())
                    .filter_map(|(point, &coefficient)| {
                        (coefficient != 0).then_some((point.point_index, coefficient))
                    })
                    .collect::<Vec<_>>();

                LocalCygvStarUnionSecondaryCircuitSample {
                    role_counts: star_union_circuit_role_counts(&nonzero, &role_by_point),
                    role_signed_sums: star_union_circuit_role_signed_sums(&nonzero, &role_by_point),
                    nonzero,
                    pairing: pairing.get().to_string(),
                    global_height_pairing: global_height_pairing.clone(),
                    global_height_orientation: global_height_orientation.clone(),
                }
            },
        )
        .collect::<Vec<_>>();
    let status = if strictly_inside {
        "star_union_shared_face_secondary_strictly_inside"
    } else if flipped_strictly_inside {
        "star_union_shared_face_secondary_strictly_inside_after_height_sign_flip"
    } else if negative_pairing_count > 0 {
        "star_union_shared_face_secondary_outside"
    } else if zero_pairing_count > 0 {
        "star_union_shared_face_secondary_on_wall"
    } else {
        "star_union_shared_face_secondary_not_strictly_inside"
    };
    LocalCygvStarUnionSharedFaceSecondaryHint {
        status: status.to_string(),
        simplex_count: Some(triangulation.simplices().len()),
        hyperplane_count: Some(secondary_hyperplanes.len()),
        min_pairing: pairing_min_string(&pairings),
        max_pairing: pairing_max_string(&pairings),
        zero_pairing_count: Some(zero_pairing_count),
        negative_pairing_count: Some(negative_pairing_count),
        strictly_inside: Some(strictly_inside),
        flipped_strictly_inside: Some(flipped_strictly_inside),
        global_height_status: global_height_summary.status,
        global_height_min_pairing: global_height_summary.min_pairing,
        global_height_max_pairing: global_height_summary.max_pairing,
        global_height_zero_pairing_count: global_height_summary.zero_pairing_count,
        global_height_positive_pairing_count: global_height_summary.positive_pairing_count,
        global_height_negative_pairing_count: global_height_summary.negative_pairing_count,
        circuit_sample,
    }
}

fn local_cygv_star_union_opposite_star_wall_circuit_hint(
    secondary: &LocalCygvStarUnionSharedFaceSecondaryHint,
    lookups: &[LocalCygvStarUnionGlobalBasisLookup],
) -> LocalCygvStarUnionOppositeStarWallCircuitHint {
    let empty = |status: &str| LocalCygvStarUnionOppositeStarWallCircuitHint {
        status: status.to_string(),
        circuit_nonzero: None,
        circuit_pairing: None,
        circuit_global_height_pairing: None,
        circuit_global_height_orientation: None,
        circuit_role_counts: None,
        circuit_role_signed_sums: None,
        opposite_star_known_qn_history_status: None,
        opposite_star_source_derived_gv: None,
        opposite_star_source_class_status: None,
    };
    let Some(star) = star_union_lookup_by_role(lookups, "star") else {
        return empty("opposite_star_wall_circuit_missing_star_lookup");
    };
    let Some(source_ray) = star.opposite_source_ray_ambient_nonzero.as_ref() else {
        return LocalCygvStarUnionOppositeStarWallCircuitHint {
            status: "opposite_star_wall_circuit_missing_opposite_source_ray".to_string(),
            circuit_nonzero: None,
            circuit_pairing: None,
            circuit_global_height_pairing: None,
            circuit_global_height_orientation: None,
            circuit_role_counts: None,
            circuit_role_signed_sums: None,
            opposite_star_known_qn_history_status: star.opposite_known_qn_history_status.clone(),
            opposite_star_source_derived_gv: star.opposite_source_derived_gv.clone(),
            opposite_star_source_class_status: star.opposite_source_class_status.clone(),
        };
    };
    let Some(circuit) = secondary
        .circuit_sample
        .iter()
        .find(|circuit| sparse_entries_match(&circuit.nonzero, source_ray))
    else {
        return LocalCygvStarUnionOppositeStarWallCircuitHint {
            status: "opposite_star_wall_circuit_no_matching_shared_face_circuit".to_string(),
            circuit_nonzero: None,
            circuit_pairing: None,
            circuit_global_height_pairing: None,
            circuit_global_height_orientation: None,
            circuit_role_counts: None,
            circuit_role_signed_sums: None,
            opposite_star_known_qn_history_status: star.opposite_known_qn_history_status.clone(),
            opposite_star_source_derived_gv: star.opposite_source_derived_gv.clone(),
            opposite_star_source_class_status: star.opposite_source_class_status.clone(),
        };
    };
    let history = star
        .opposite_known_qn_history_status
        .as_deref()
        .unwrap_or("missing_opposite_star_known_qn_history");
    let status = if history.starts_with("known_nonzero") {
        "opposite_star_wall_circuit_matches_known_nonzero_history"
    } else if history.starts_with("known_zero") {
        "opposite_star_wall_circuit_matches_known_zero_history"
    } else {
        "opposite_star_wall_circuit_matches_unknown_history"
    };
    LocalCygvStarUnionOppositeStarWallCircuitHint {
        status: status.to_string(),
        circuit_nonzero: Some(circuit.nonzero.clone()),
        circuit_pairing: Some(circuit.pairing.clone()),
        circuit_global_height_pairing: circuit.global_height_pairing.clone(),
        circuit_global_height_orientation: circuit.global_height_orientation.clone(),
        circuit_role_counts: Some(circuit.role_counts.clone()),
        circuit_role_signed_sums: Some(circuit.role_signed_sums.clone()),
        opposite_star_known_qn_history_status: star.opposite_known_qn_history_status.clone(),
        opposite_star_source_derived_gv: star.opposite_source_derived_gv.clone(),
        opposite_star_source_class_status: star.opposite_source_class_status.clone(),
    }
}

fn local_cygv_star_union_crossed_wall_stable_weyl_probe(
    wall: &LocalCygvStarUnionOppositeStarWallCircuitHint,
    lookups: &[LocalCygvStarUnionGlobalBasisLookup],
    context: &ValidatedContext<'_>,
) -> LocalCygvStarUnionCrossedWallStableWeylProbe {
    let empty =
        |status: &str, source_sample_status: &str| LocalCygvStarUnionCrossedWallStableWeylProbe {
            status: status.to_string(),
            source_sample_status: source_sample_status.to_string(),
            matching_candidate_count: None,
            shrinking_divisor_index: None,
            cms_divisor_linear_system: None,
            shrinking_divisor_basis_nonzero: None,
            shrinking_divisor_ambient_basis_nonzero: None,
            divisor_quadratic_vanishes_on_curve_facet: None,
            weyl_reflection_matches_flop_transform: None,
            extremal_ray_certificate_status: None,
            separator_normal_nonzero: None,
            error: None,
        };

    if wall.status != "opposite_star_wall_circuit_matches_known_nonzero_history" {
        return empty(
            "stable_weyl_not_checked_wall_circuit_not_known_nonzero",
            "source_sample_not_checked",
        );
    }
    let Some(star) = star_union_lookup_by_role(lookups, "star") else {
        return empty(
            "stable_weyl_not_checked_missing_star_lookup",
            "source_sample_not_checked",
        );
    };
    let Some(curve_sparse) = star.opposite_basis_nonzero.as_ref() else {
        return empty(
            "stable_weyl_not_checked_missing_crossed_wall_curve",
            "source_sample_not_checked",
        );
    };
    let curve = match dense_from_sparse(curve_sparse, context.dimension) {
        Ok(curve) => curve,
        Err(error) => {
            let mut probe = empty(
                "stable_weyl_error_invalid_crossed_wall_curve",
                "source_sample_not_checked",
            );
            probe.error = Some(error);
            return probe;
        }
    };
    let Some(gv) = wall.opposite_star_source_derived_gv.as_deref() else {
        return empty(
            "stable_weyl_not_checked_missing_crossed_wall_gv",
            "source_sample_not_checked",
        );
    };
    let gv_invariant = match parse_integral_rational(gv, "crossed wall GV") {
        Ok(value) => value,
        Err(error) => {
            let mut probe = empty(
                "stable_weyl_error_nonintegral_crossed_wall_gv",
                "source_sample_not_checked",
            );
            probe.error = Some(error);
            return probe;
        }
    };
    let (source_sample, source_sample_status) =
        match source_sample_for_crossed_wall_curve(context, &curve) {
            Ok(Some(found)) => found,
            Ok(None) => {
                return empty(
                    "stable_weyl_blocked_missing_source_sample_for_crossed_wall_curve",
                    "source_sample_missing",
                );
            }
            Err(error) => {
                let mut probe = empty(
                    "stable_weyl_error_source_sample_lookup_failed",
                    "source_sample_error",
                );
                probe.error = Some(error);
                return probe;
            }
        };
    let mut source_sample_status = source_sample_status.to_string();
    let (source_gv, import_status) =
        match source_derived_gv_value_and_status_for_sample(source_sample) {
            Ok(value) => value,
            Err(error) => {
                let mut probe = empty(
                    "stable_weyl_error_source_gv_import_failed",
                    &source_sample_status,
                );
                probe.error = Some(error);
                return probe;
            }
        };
    if source_gv.as_deref() != Some(gv) {
        let context_known_gv_matches = context
            .source_derived_gv_by_basis
            .get(&curve)
            .is_some_and(|context_gv| context_gv == gv);
        if source_gv.is_none() && context_known_gv_matches {
            source_sample_status =
                format!("{source_sample_status}_context_known_gv_without_sample_import");
        } else {
            let mut probe = empty(
                "stable_weyl_blocked_source_sample_gv_mismatch",
                &source_sample_status,
            );
            probe.error = Some(format!(
                "source sample import status {import_status} gives GV {:?}, wall gives {gv}",
                source_gv
            ));
            return probe;
        }
    }
    let source_sample_status = source_sample_status.as_str();
    let Some(checks) = source_sample
        .cms_general_divisor_intersection_checks
        .as_deref()
    else {
        return empty(
            "stable_weyl_blocked_missing_cms_divisor_checks",
            source_sample_status,
        );
    };
    let matching_checks = checks
        .iter()
        .filter(|check| {
            cms_general_divisor_intersection_check_status(check)
                == "cms_general_divisor_integral_solution_matches_inferred_degree"
        })
        .collect::<Vec<_>>();
    if matching_checks.is_empty() {
        if let Some(first_check) = checks.first() {
            let check_status = cms_general_divisor_intersection_check_status(first_check);
            return LocalCygvStarUnionCrossedWallStableWeylProbe {
                status: format!(
                    "stable_weyl_blocked_{}",
                    status_error_fragment(&check_status)
                ),
                source_sample_status: source_sample_status.to_string(),
                matching_candidate_count: Some(checks.len()),
                shrinking_divisor_index: Some(first_check.shrinking_divisor_index),
                cms_divisor_linear_system: first_check.linear_system.clone(),
                shrinking_divisor_basis_nonzero: first_check.solution_basis_nonzero.clone(),
                shrinking_divisor_ambient_basis_nonzero: first_check
                    .solution_ambient_basis_nonzero
                    .clone(),
                divisor_quadratic_vanishes_on_curve_facet: None,
                weyl_reflection_matches_flop_transform: None,
                extremal_ray_certificate_status: star
                    .opposite_extremal_ray_certificate
                    .as_ref()
                    .map(|probe| probe.status.clone()),
                separator_normal_nonzero: star
                    .opposite_extremal_ray_certificate
                    .as_ref()
                    .and_then(|probe| probe.separator_normal_nonzero.clone()),
                error: None,
            };
        }
        return empty(
            "stable_weyl_blocked_no_cms_divisor_checks",
            source_sample_status,
        );
    }

    let mut first_probe = None;
    let matching_candidate_count = matching_checks.len();
    for check in matching_checks {
        let probe = local_cygv_star_union_crossed_wall_stable_weyl_candidate_probe(
            check,
            matching_candidate_count,
            &curve,
            &gv_invariant,
            star.opposite_extremal_ray_certificate.as_ref(),
            context,
            source_sample_status,
        );
        if probe.status == "stable_weyl_certified_exact_checks" {
            return probe;
        }
        if first_probe.is_none() {
            first_probe = Some(probe);
        }
    }
    first_probe.unwrap_or_else(|| {
        empty(
            "stable_weyl_blocked_no_integral_shrinking_divisor_candidate",
            source_sample_status,
        )
    })
}

fn source_sample_for_crossed_wall_curve<'a>(
    context: &'a ValidatedContext<'_>,
    curve: &[i64],
) -> Result<Option<(&'a MissingGvTargetSample, &'static str)>, String> {
    let search = |stats: Option<&'a MissingGvTargetStats>,
                  status: &'static str|
     -> Result<Option<(&'a MissingGvTargetSample, &'static str)>, String> {
        let Some(stats) = stats else {
            return Ok(None);
        };
        for sample in &stats.sample {
            if dense_from_sparse(&sample.basis_nonzero, context.dimension)? == curve {
                return Ok(Some((sample, status)));
            }
        }
        Ok(None)
    };
    if let Some(found) = search(
        context.uncovered_source_ray_stats,
        "source_sample_uncovered_source_ray_stats",
    )? {
        return Ok(Some(found));
    }
    if let Some(found) = search(
        context.shared_facet_unresolved_source_ray_stats,
        "source_sample_shared_facet_unresolved_source_ray_stats",
    )? {
        return Ok(Some(found));
    }
    search(
        Some(context.stats),
        "source_sample_missing_target_stats_self_match",
    )
}

fn local_cygv_star_union_crossed_wall_stable_weyl_candidate_probe(
    check: &CmsGeneralDivisorIntersectionCheck,
    matching_candidate_count: usize,
    curve: &[i64],
    gv_invariant: &Integer,
    extremal_probe: Option<&TargetExtremalRayCertificateProbe>,
    context: &ValidatedContext<'_>,
    source_sample_status: &str,
) -> LocalCygvStarUnionCrossedWallStableWeylProbe {
    let mut probe = LocalCygvStarUnionCrossedWallStableWeylProbe {
        status: "stable_weyl_candidate_not_evaluated".to_string(),
        source_sample_status: source_sample_status.to_string(),
        matching_candidate_count: Some(matching_candidate_count),
        shrinking_divisor_index: Some(check.shrinking_divisor_index),
        cms_divisor_linear_system: check.linear_system.clone(),
        shrinking_divisor_basis_nonzero: check.solution_basis_nonzero.clone(),
        shrinking_divisor_ambient_basis_nonzero: check.solution_ambient_basis_nonzero.clone(),
        divisor_quadratic_vanishes_on_curve_facet: None,
        weyl_reflection_matches_flop_transform: None,
        extremal_ray_certificate_status: extremal_probe.map(|probe| probe.status.clone()),
        separator_normal_nonzero: extremal_probe
            .and_then(|probe| probe.separator_normal_nonzero.clone()),
        error: None,
    };
    let Some(divisor_sparse) = check.solution_basis_nonzero.as_ref() else {
        probe.status = "stable_weyl_blocked_missing_basis_shrinking_divisor".to_string();
        return probe;
    };
    let divisor = match dense_integer_from_rational_sparse(
        divisor_sparse,
        context.dimension,
        "shrinking divisor",
    ) {
        Ok(divisor) => divisor,
        Err(error) => {
            probe.status = "stable_weyl_error_invalid_shrinking_divisor".to_string();
            probe.error = Some(error);
            return probe;
        }
    };
    let quadratic =
        divisor_quadratic_vanishes_on_curve_facet(&context.intersection, &divisor, curve);
    probe.divisor_quadratic_vanishes_on_curve_facet = quadratic;
    if quadratic != Some(true) {
        probe.status = "stable_weyl_blocked_divisor_quadratic_check_failed".to_string();
        return probe;
    }
    let tensor = weyl_reflection_matches_flop_transform(
        &context.intersection,
        &divisor,
        curve,
        gv_invariant,
    );
    probe.weyl_reflection_matches_flop_transform = tensor;
    if tensor != Some(true) {
        probe.status = "stable_weyl_blocked_weyl_tensor_check_failed".to_string();
        return probe;
    }
    let Some(extremal_probe) = extremal_probe else {
        probe.status = "stable_weyl_blocked_extremal_certificate_not_run".to_string();
        return probe;
    };
    if !matches!(
        extremal_probe.status.as_str(),
        "certified_exact_extremal_ray" | "certified_exact_extremal_ray_by_lp_after_generator_limit"
    ) {
        probe.status = format!(
            "stable_weyl_blocked_extremal_certificate_{}",
            status_error_fragment(&extremal_probe.status)
        );
        return probe;
    }
    let Some(separator_sparse) = extremal_probe.separator_normal_nonzero.as_ref() else {
        probe.status = "stable_weyl_error_certified_extremal_missing_separator".to_string();
        return probe;
    };
    let separator = match dense_from_sparse(separator_sparse, context.dimension) {
        Ok(separator) => separator,
        Err(error) => {
            probe.status = "stable_weyl_error_invalid_extremal_separator".to_string();
            probe.error = Some(error);
            return probe;
        }
    };
    match check_stable_weyl_candidate_certificate(
        &context.intersection,
        &separator,
        context.degree_bounded_rays,
        &divisor,
        curve,
        gv_invariant,
    ) {
        Ok(Some(_certificate)) => {
            probe.status = "stable_weyl_certified_exact_checks".to_string();
        }
        Ok(None) => {
            probe.status = "stable_weyl_blocked_combined_certificate_rejected".to_string();
        }
        Err(error) => {
            probe.status = "stable_weyl_error_combined_certificate_failed".to_string();
            probe.error = Some(error.to_string());
        }
    }
    probe
}

fn sparse_entries_match(lhs: &[(usize, i64)], rhs: &[(usize, i64)]) -> bool {
    if lhs.len() != rhs.len() {
        return false;
    }
    let mut lhs = lhs.to_vec();
    let mut rhs = rhs.to_vec();
    lhs.sort_unstable();
    rhs.sort_unstable();
    lhs == rhs
}

fn local_cygv_star_union_wall_transport_readiness(
    transport: &LocalCygvStarUnionTransportDecompositionSummary,
    wall: &LocalCygvStarUnionOppositeStarWallCircuitHint,
    shared_face_secondary: &LocalCygvStarUnionSharedFaceSecondaryHint,
    lookups: &[LocalCygvStarUnionGlobalBasisLookup],
    target_plus_star_support_generator_count: Option<usize>,
    target_plus_star_support_face_certificate_status: Option<&str>,
    crossed_wall_stable_weyl_certificate: Option<LocalCygvStarUnionCrossedWallStableWeylProbe>,
) -> LocalCygvStarUnionWallTransportReadiness {
    let target_plus_star = star_union_lookup_by_role(lookups, "target_plus_star");
    let star = star_union_lookup_by_role(lookups, "star");
    let crossed_wall_branch =
        star.and_then(|lookup| lookup.opposite_source_branch_diagnostic.as_ref());
    let target_plus_star_extremal_status = transport
        .target_plus_star_extremal_ray_certificate
        .as_ref()
        .map(|probe| probe.status.clone());
    let mut missing_inputs = Vec::new();
    let transport_ready = transport.status
        == "star_union_transport_target_equals_target_plus_star_plus_opposite_star";
    if !transport_ready {
        missing_inputs.push("star_union_transport_identity".to_string());
    }
    let wall_known = wall.status == "opposite_star_wall_circuit_matches_known_nonzero_history";
    if !wall_known {
        missing_inputs.push("known_opposite_star_wall_circuit_gv".to_string());
    }
    let target_plus_star_known = transport
        .target_plus_star_known_qn_history_status
        .as_deref()
        .is_some_and(|status| {
            status.starts_with("known_nonzero") || status.starts_with("known_zero")
        });
    if !target_plus_star_known {
        missing_inputs.push("target_plus_star_qn_history".to_string());
    }
    let target_plus_star_has_generator = !matches!(
        target_plus_star_extremal_status.as_deref(),
        Some("not_certified_no_same_positive_ray_generator")
            | Some("error_invalid_ray_target_curve_is_zero")
    );
    let target_plus_star_has_support_face = matches!(
        target_plus_star_support_face_certificate_status,
        Some(status) if status.contains("certified")
    );
    if !target_plus_star_has_generator && !target_plus_star_has_support_face {
        missing_inputs.push("target_plus_star_chamber_semigroup_transport".to_string());
    }
    let local_shared_face_is_wall = matches!(
        shared_face_secondary.status.as_str(),
        "star_union_shared_face_secondary_on_wall"
            | "star_union_shared_face_secondary_not_strictly_inside"
            | "star_union_shared_face_secondary_outside"
    ) || matches!(
        shared_face_secondary.global_height_status.as_str(),
        "star_union_shared_face_secondary_global_height_on_all_walls"
            | "star_union_shared_face_secondary_global_height_on_wall_nonnegative"
            | "star_union_shared_face_secondary_global_height_on_wall_nonpositive"
            | "star_union_shared_face_secondary_global_height_crosses_oriented_walls"
            | "star_union_shared_face_secondary_global_height_crosses_wall"
    );
    if wall_known && local_shared_face_is_wall {
        missing_inputs.push("target_plus_star_wall_crossing_chamber_transport".to_string());
    }
    if wall_known {
        if let Some(missing_input) =
            wall_transport_flop_certificate_missing_input(&crossed_wall_stable_weyl_certificate)
        {
            missing_inputs.push(missing_input.to_string());
        }
    }
    missing_inputs.sort();
    missing_inputs.dedup();

    let status = if !transport_ready {
        "wall_transport_blocked_transport_identity"
    } else if !wall_known {
        "wall_transport_blocked_missing_known_wall_circuit"
    } else if local_shared_face_is_wall {
        "wall_transport_known_wall_remainder_requires_wall_crossing_chamber_transport"
    } else if !target_plus_star_known
        && !target_plus_star_has_generator
        && !target_plus_star_has_support_face
    {
        "wall_transport_known_wall_remainder_requires_chamber_semigroup"
    } else if !target_plus_star_known {
        "wall_transport_known_wall_remainder_qn_history_missing"
    } else {
        "wall_transport_components_known_needs_flop_certificate"
    };

    LocalCygvStarUnionWallTransportReadiness {
        status: status.to_string(),
        missing_inputs,
        local_shared_face_secondary_status: Some(shared_face_secondary.status.clone()),
        local_shared_face_secondary_strictly_inside: shared_face_secondary.strictly_inside,
        local_shared_face_secondary_global_height_status: Some(
            shared_face_secondary.global_height_status.clone(),
        ),
        crossed_wall_curve_basis_nonzero: star
            .and_then(|lookup| lookup.opposite_basis_nonzero.clone()),
        crossed_wall_curve_ambient_nonzero: wall.circuit_nonzero.clone(),
        crossed_wall_global_height_orientation: wall.circuit_global_height_orientation.clone(),
        crossed_wall_role_counts: wall.circuit_role_counts.clone(),
        crossed_wall_role_signed_sums: wall.circuit_role_signed_sums.clone(),
        crossed_wall_gv: wall.opposite_star_source_derived_gv.clone(),
        crossed_wall_branch_q_dot_t: crossed_wall_branch.map(|branch| branch.q_dot_t.clone()),
        crossed_wall_parity_mod2: crossed_wall_branch.map(|branch| branch.parity_mod2),
        crossed_wall_positive_dilog_status: crossed_wall_branch
            .map(|branch| branch.dilog_status.clone()),
        crossed_wall_negative_continuation_status: crossed_wall_negative_continuation_status(
            crossed_wall_branch,
        ),
        target_plus_star_basis_nonzero: target_plus_star
            .and_then(|lookup| lookup.basis_nonzero.clone()),
        target_plus_star_extremal_status,
        target_plus_star_support_generator_count,
        target_plus_star_support_face_certificate_status:
            target_plus_star_support_face_certificate_status.map(str::to_string),
        crossed_wall_stable_weyl_certificate,
    }
}

fn wall_transport_flop_certificate_missing_input(
    stable_weyl_certificate: &Option<LocalCygvStarUnionCrossedWallStableWeylProbe>,
) -> Option<&'static str> {
    match stable_weyl_certificate
        .as_ref()
        .map(|probe| probe.status.as_str())
    {
        Some("stable_weyl_certified_exact_checks") => None,
        Some("stable_weyl_blocked_cms_general_divisor_no_rational_divisor_solution") => {
            Some("non_weyl_wall_crossing_transport_certificate")
        }
        Some(status) if status.starts_with("stable_weyl_blocked_") => {
            Some("shrinking_divisor_or_flop_certificate")
        }
        Some(status) if status.starts_with("stable_weyl_error_") => {
            Some("shrinking_divisor_or_flop_certificate")
        }
        _ => Some("shrinking_divisor_or_flop_certificate"),
    }
}

fn crossed_wall_negative_continuation_status(
    branch: Option<&MissingGvBranchDiagnostic>,
) -> Option<String> {
    let branch = branch?;
    let q_dot_t = match branch.q_dot_t.parse::<f64>() {
        Ok(value) => value,
        Err(_) => return Some("crossed_wall_negative_continuation_q_dot_t_parse_error".into()),
    };
    match gv_dilog_from_curve_volume_checked(-q_dot_t, branch.parity) {
        Ok(_) => Some("crossed_wall_negative_continuation_real_axis_ok".into()),
        Err(failure) => Some(format!(
            "crossed_wall_negative_continuation_{}",
            gv_dilog_failure_status(failure)
        )),
    }
}

fn gv_dilog_failure_status(failure: GvDilogFailure) -> &'static str {
    match failure {
        GvDilogFailure::NonFiniteCurveVolume => "nonfinite_curve_volume",
        GvDilogFailure::ZeroCurveVolume => "zero_curve_volume",
        GvDilogFailure::NonFiniteArgument => "nonfinite_argument",
        GvDilogFailure::RealBranchCut => "real_branch_cut",
        GvDilogFailure::EvaluationFailed => "evaluation_failed",
    }
}

