struct LocalCygvStarUnionGlobalRegularTriangulationHint {
    status: String,
    simplex_count: Option<usize>,
    simplices: Vec<Vec<usize>>,
    shared_face_simplex_count: Option<usize>,
    shared_face_extra_points: Vec<usize>,
    target_exclusive_selected_points: Vec<usize>,
    star_extra_selected_points: Vec<usize>,
}

fn local_cygv_star_union_global_regular_triangulation_hint(
    witness: Option<&OriginCircuitWitnessSample>,
    star_support: &LocalCygvStarSupportHint,
    global_secondary_heights: Option<&[f64]>,
) -> LocalCygvStarUnionGlobalRegularTriangulationHint {
    let empty = |status: &str| LocalCygvStarUnionGlobalRegularTriangulationHint {
        status: status.to_string(),
        simplex_count: None,
        simplices: Vec::new(),
        shared_face_simplex_count: None,
        shared_face_extra_points: Vec::new(),
        target_exclusive_selected_points: Vec::new(),
        star_extra_selected_points: Vec::new(),
    };
    let Some(witness) = witness else {
        return empty("star_union_global_regular_missing_origin_circuit_witness");
    };
    if star_support.point_indices.is_empty() {
        return empty("star_union_global_regular_missing_star_support");
    }
    let Some(global_secondary_heights) = global_secondary_heights else {
        return empty("star_union_global_regular_missing_global_height_vector");
    };
    let support = origin_circuit_star_union_point_samples(witness, star_support);
    if support.is_empty() {
        return empty("star_union_global_regular_missing_union_points");
    }
    let local_points = support
        .iter()
        .map(|point| Point::new(point.coordinates.clone()))
        .collect::<Vec<_>>();
    let local_heights = match support
        .iter()
        .map(|point| {
            global_secondary_heights
                .get(point.point_index)
                .copied()
                .ok_or_else(|| {
                    format!(
                        "point index {} maps to missing origin-included secondary height entry",
                        point.point_index
                    )
                })
        })
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(heights) => heights,
        Err(error) => {
            return LocalCygvStarUnionGlobalRegularTriangulationHint {
                status: format!(
                    "star_union_global_regular_height_error:{}",
                    status_error_fragment(&error)
                ),
                ..empty("star_union_global_regular_height_error")
            };
        }
    };
    let triangulation = match compute_regular_triangulation(&local_points, &local_heights) {
        Ok(triangulation) => triangulation,
        Err(error) => {
            return LocalCygvStarUnionGlobalRegularTriangulationHint {
                status: format!(
                    "star_union_global_regular_triangulation_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                ..empty("star_union_global_regular_triangulation_error")
            };
        }
    };
    let simplices = triangulation
        .simplices()
        .iter()
        .map(|simplex| {
            let mut point_indices = simplex
                .iter()
                .filter_map(|&local| support.get(local).map(|point| point.point_index))
                .collect::<Vec<_>>();
            point_indices.sort_unstable();
            point_indices
        })
        .collect::<Vec<_>>();
    let mut shared_face = BTreeSet::from([0]);
    shared_face.extend(witness.shared_two_simplex.iter().copied());
    let target_exclusive = BTreeSet::from([
        witness.first_facet_exclusive_point,
        witness.second_facet_exclusive_point,
    ]);
    let star_extra = origin_circuit_shared_two_simplex_star_extra_points(Some(witness))
        .into_iter()
        .flatten()
        .collect::<BTreeSet<_>>();
    let mut shared_face_extra_points = BTreeSet::new();
    for simplex in &simplices {
        let simplex_set = simplex.iter().copied().collect::<BTreeSet<_>>();
        if shared_face.iter().all(|point| simplex_set.contains(point)) {
            for point in simplex_set.difference(&shared_face) {
                shared_face_extra_points.insert(*point);
            }
        }
    }
    let shared_face_extra_points = shared_face_extra_points.into_iter().collect::<Vec<_>>();
    let target_exclusive_selected_points = shared_face_extra_points
        .iter()
        .copied()
        .filter(|point| target_exclusive.contains(point))
        .collect::<Vec<_>>();
    let star_extra_selected_points = shared_face_extra_points
        .iter()
        .copied()
        .filter(|point| star_extra.contains(point))
        .collect::<Vec<_>>();
    let other_selected_count = shared_face_extra_points
        .iter()
        .filter(|point| !target_exclusive.contains(point) && !star_extra.contains(point))
        .count();
    let shared_face_simplex_count = simplices
        .iter()
        .filter(|simplex| shared_face.iter().all(|point| simplex.contains(point)))
        .count();
    let status = if shared_face_simplex_count == 0 {
        "star_union_global_regular_no_shared_face_simplices"
    } else if !target_exclusive_selected_points.is_empty() {
        "star_union_global_regular_shared_face_selects_target_exclusive_points"
    } else if other_selected_count > 0 {
        "star_union_global_regular_shared_face_selects_other_points"
    } else if star_extra_selected_points.len() == star_extra.len() {
        "star_union_global_regular_shared_face_matches_serialized_star_extras"
    } else {
        "star_union_global_regular_shared_face_selects_star_extras_partial"
    };
    LocalCygvStarUnionGlobalRegularTriangulationHint {
        status: status.to_string(),
        simplex_count: Some(simplices.len()),
        simplices,
        shared_face_simplex_count: Some(shared_face_simplex_count),
        shared_face_extra_points,
        target_exclusive_selected_points,
        star_extra_selected_points,
    }
}

fn local_cygv_star_union_crossed_wall_regular_side_hint(
    wall: &LocalCygvStarUnionOppositeStarWallCircuitHint,
    global_regular: &LocalCygvStarUnionGlobalRegularTriangulationHint,
) -> LocalCygvStarUnionCrossedWallRegularSideHint {
    let empty = |status: &str| LocalCygvStarUnionCrossedWallRegularSideHint {
        status: status.to_string(),
        selected_omission_side: None,
        circuit_flip_status: None,
        flipped_omission_side: None,
        positive_coefficient_points: Vec::new(),
        negative_coefficient_points: Vec::new(),
        positive_coefficient_omission_hits: Vec::new(),
        negative_coefficient_omission_hits: Vec::new(),
        selected_side_circuit_facets: Vec::new(),
        opposite_side_circuit_facets: Vec::new(),
        circuit_flip_removed_simplices: Vec::new(),
        circuit_flip_added_simplices: Vec::new(),
        circuit_flip_simplex_count: None,
        local_circuit_flip_status: None,
        local_circuit_flip_link: None,
        local_circuit_flip_removed_simplices: Vec::new(),
        local_circuit_flip_added_simplices: Vec::new(),
        local_circuit_flip_simplex_count: None,
    };
    let Some(circuit) = wall.circuit_nonzero.as_ref() else {
        return empty("crossed_wall_regular_side_missing_wall_circuit");
    };
    if global_regular.simplices.is_empty() {
        return empty("crossed_wall_regular_side_missing_global_regular_triangulation");
    }
    let classification = match classify_circuit_omission_side(&global_regular.simplices, circuit) {
        Ok(classification) => classification,
        Err(error) => {
            return LocalCygvStarUnionCrossedWallRegularSideHint {
                status: format!(
                    "crossed_wall_regular_side_circuit_error:{}",
                    status_error_fragment(&error.to_string())
                ),
                selected_omission_side: None,
                circuit_flip_status: None,
                flipped_omission_side: None,
                positive_coefficient_points: Vec::new(),
                negative_coefficient_points: Vec::new(),
                positive_coefficient_omission_hits: Vec::new(),
                negative_coefficient_omission_hits: Vec::new(),
                selected_side_circuit_facets: Vec::new(),
                opposite_side_circuit_facets: Vec::new(),
                circuit_flip_removed_simplices: Vec::new(),
                circuit_flip_added_simplices: Vec::new(),
                circuit_flip_simplex_count: None,
                local_circuit_flip_status: None,
                local_circuit_flip_link: None,
                local_circuit_flip_removed_simplices: Vec::new(),
                local_circuit_flip_added_simplices: Vec::new(),
                local_circuit_flip_simplex_count: None,
            };
        }
    };
    let status = match classification.side {
        CircuitOmissionSide::PositiveCoefficient => {
            "crossed_wall_regular_selects_positive_coefficient_omission_side"
        }
        CircuitOmissionSide::NegativeCoefficient => {
            "crossed_wall_regular_selects_negative_coefficient_omission_side"
        }
        CircuitOmissionSide::None => "crossed_wall_regular_side_no_circuit_omission_facets_seen",
        CircuitOmissionSide::MixedOrPartial => {
            "crossed_wall_regular_side_mixed_or_partial_omission_facets"
        }
    };
    let (circuit_flip_status, flipped_omission_side, removed_simplices, added_simplices, count) =
        match flip_circuit_in_triangulation(&global_regular.simplices, circuit) {
            Ok(flip) => (
                Some("circuit_flip_constructed_adjacent_chamber".to_string()),
                Some(flip.flipped_side.as_str().to_string()),
                flip.removed_simplices,
                flip.added_simplices,
                Some(flip.simplices.len()),
            ),
            Err(error) => (
                Some(format!(
                    "circuit_flip_error:{}",
                    status_error_fragment(&error.to_string())
                )),
                None,
                Vec::new(),
                Vec::new(),
                None,
            ),
        };
    let complete_links = complete_circuit_flip_links(&global_regular.simplices, circuit);
    let (
        local_circuit_flip_status,
        local_circuit_flip_link,
        local_removed_simplices,
        local_added_simplices,
        local_count,
    ) = match complete_links {
        Ok(links) if links.len() == 1 => {
            let link = links[0].clone();
            match flip_circuit_link_in_triangulation(&global_regular.simplices, circuit, &link) {
                Ok(flip) => (
                    Some("local_circuit_flip_constructed_adjacent_chamber".to_string()),
                    Some(link),
                    flip.removed_simplices,
                    flip.added_simplices,
                    Some(flip.simplices.len()),
                ),
                Err(error) => (
                    Some(format!(
                        "local_circuit_flip_error:{}",
                        status_error_fragment(&error.to_string())
                    )),
                    Some(link),
                    Vec::new(),
                    Vec::new(),
                    None,
                ),
            }
        }
        Ok(links) if links.is_empty() => (
            Some("local_circuit_flip_no_complete_selected_link".to_string()),
            None,
            Vec::new(),
            Vec::new(),
            None,
        ),
        Ok(links) => (
            Some(format!(
                "local_circuit_flip_ambiguous_complete_selected_links:{}",
                links.len()
            )),
            None,
            Vec::new(),
            Vec::new(),
            None,
        ),
        Err(error) => (
            Some(format!(
                "local_circuit_flip_link_error:{}",
                status_error_fragment(&error.to_string())
            )),
            None,
            Vec::new(),
            Vec::new(),
            None,
        ),
    };

    LocalCygvStarUnionCrossedWallRegularSideHint {
        status: status.to_string(),
        selected_omission_side: Some(classification.side.as_str().to_string()),
        circuit_flip_status,
        flipped_omission_side,
        positive_coefficient_points: classification.positive_coefficient_points,
        negative_coefficient_points: classification.negative_coefficient_points,
        positive_coefficient_omission_hits: classification.positive_coefficient_omission_hits,
        negative_coefficient_omission_hits: classification.negative_coefficient_omission_hits,
        selected_side_circuit_facets: classification.selected_side_facets,
        opposite_side_circuit_facets: classification.opposite_side_facets,
        circuit_flip_removed_simplices: removed_simplices,
        circuit_flip_added_simplices: added_simplices,
        circuit_flip_simplex_count: count,
        local_circuit_flip_status,
        local_circuit_flip_link,
        local_circuit_flip_removed_simplices: local_removed_simplices,
        local_circuit_flip_added_simplices: local_added_simplices,
        local_circuit_flip_simplex_count: local_count,
    }
}

fn local_cygv_star_union_chamber_semigroup_transport_probe(
    point_samples: &[OriginCircuitRelationPointSample],
    star_union: &LocalCygvStarUnionRelationHint,
    global_regular: &LocalCygvStarUnionGlobalRegularTriangulationHint,
    regular_side: &LocalCygvStarUnionCrossedWallRegularSideHint,
    context: Option<&ValidatedContext<'_>>,
) -> LocalCygvStarUnionChamberSemigroupTransportProbe {
    let blocked =
        |status: &str, error: Option<String>| LocalCygvStarUnionChamberSemigroupTransportProbe {
            status: status.to_string(),
            target_plus_star_coordinates: star_union.target_plus_star_coordinates.clone(),
            current_chamber_generator_count: None,
            current_chamber_generators: Vec::new(),
            current_chamber_generator_context: Vec::new(),
            current_chamber_generator_known_qn_history_status_counts: BTreeMap::new(),
            current_chamber_provided_generator_cygv_probe: None,
            current_chamber_decomposition: None,
            current_chamber_positive_degree_status: "positive_degree_chamber_not_run".to_string(),
            current_chamber_positive_degree_decomposition: None,
            flipped_chamber_status: None,
            flipped_chamber_generator_count: None,
            flipped_chamber_generators: Vec::new(),
            flipped_chamber_generator_context: Vec::new(),
            flipped_chamber_generator_known_qn_history_status_counts: BTreeMap::new(),
            flipped_chamber_provided_generator_cygv_probe: None,
            flipped_chamber_decomposition: None,
            flipped_chamber_positive_degree_status: "positive_degree_chamber_not_run".to_string(),
            flipped_chamber_positive_degree_decomposition: None,
            positive_degree_transport_status: "positive_degree_transport_not_run".to_string(),
            error,
        };

    let Some(charge_basis) = star_union.charge_basis.as_deref() else {
        return blocked(
            "star_union_chamber_semigroup_blocked_missing_charge_basis",
            None,
        );
    };
    let Some(target) = star_union.target_plus_star_coordinates.as_deref() else {
        return blocked(
            "star_union_chamber_semigroup_blocked_missing_target_plus_star_coordinates",
            None,
        );
    };
    if global_regular.simplices.is_empty() {
        return blocked(
            "star_union_chamber_semigroup_blocked_missing_global_regular_triangulation",
            None,
        );
    }

    let current_generators = match local_cygv_star_union_chamber_generators_in_charge_basis(
        point_samples,
        &star_union.point_indices,
        charge_basis,
        &global_regular.simplices,
    ) {
        Ok(generators) => generators,
        Err(error) => {
            return blocked(
                "star_union_chamber_semigroup_current_chamber_error",
                Some(error),
            );
        }
    };
    let current_decomposition =
        match chamber_semigroup_decomposition_terms(target, &current_generators) {
            Ok(decomposition) => decomposition,
            Err(error) => {
                return blocked(
                    "star_union_chamber_semigroup_current_decomposition_error",
                    Some(error),
                );
            }
        };

    let flipped = local_cygv_star_union_flipped_link_simplices(global_regular, regular_side);
    let (flipped_status, flipped_generators, flipped_decomposition) = match flipped {
        Ok(Some(flipped_simplices)) => {
            match local_cygv_star_union_chamber_generators_in_charge_basis(
                point_samples,
                &star_union.point_indices,
                charge_basis,
                &flipped_simplices,
            ) {
                Ok(generators) => {
                    match chamber_semigroup_decomposition_terms(target, &generators) {
                        Ok(decomposition) => (
                            Some("local_flip_chamber_semigroup_computed".to_string()),
                            generators,
                            decomposition,
                        ),
                        Err(error) => (
                            Some(format!(
                                "local_flip_chamber_semigroup_decomposition_error:{}",
                                status_error_fragment(&error)
                            )),
                            generators,
                            None,
                        ),
                    }
                }
                Err(error) => (
                    Some(format!(
                        "local_flip_chamber_semigroup_error:{}",
                        status_error_fragment(&error)
                    )),
                    Vec::new(),
                    None,
                ),
            }
        }
        Ok(None) => (
            Some("local_flip_chamber_semigroup_not_available".to_string()),
            Vec::new(),
            None,
        ),
        Err(error) => (
            Some(format!(
                "local_flip_chamber_semigroup_error:{}",
                status_error_fragment(&error)
            )),
            Vec::new(),
            None,
        ),
    };

    let status = match (
        current_decomposition.is_some(),
        flipped_decomposition.is_some(),
    ) {
        (true, true) => {
            "star_union_chamber_semigroup_candidate_current_and_flipped_contain_target_plus_star"
        }
        (true, false) => "star_union_chamber_semigroup_candidate_current_contains_target_plus_star",
        (false, true) => "star_union_chamber_semigroup_candidate_flipped_contains_target_plus_star",
        (false, false) => "star_union_chamber_semigroup_candidate_target_plus_star_not_found",
    };

    let current_chamber_generator_context = context
        .map(|context| {
            chamber_semigroup_generator_contexts(
                &star_union.point_indices,
                point_samples,
                charge_basis,
                &current_generators,
                context,
            )
        })
        .unwrap_or_default();
    let flipped_chamber_generator_context = context
        .map(|context| {
            chamber_semigroup_generator_contexts(
                &star_union.point_indices,
                point_samples,
                charge_basis,
                &flipped_generators,
                context,
            )
        })
        .unwrap_or_default();
    let current_chamber_generator_known_qn_history_status_counts =
        chamber_semigroup_generator_known_qn_history_status_counts(
            &current_chamber_generator_context,
        );
    let flipped_chamber_generator_known_qn_history_status_counts =
        chamber_semigroup_generator_known_qn_history_status_counts(
            &flipped_chamber_generator_context,
        );
    let current_chamber_provided_generator_cygv_probe = context.map(|context| {
        chamber_semigroup_provided_generator_cygv_probe(
            star_union.target_plus_star_basis_nonzero.as_ref(),
            &current_chamber_generator_context,
            context,
            "current_chamber_generators",
        )
    });
    let flipped_chamber_provided_generator_cygv_probe = context.map(|context| {
        chamber_semigroup_provided_generator_cygv_probe(
            star_union.target_plus_star_basis_nonzero.as_ref(),
            &flipped_chamber_generator_context,
            context,
            "flipped_chamber_generators",
        )
    });
    let (
        current_chamber_positive_degree_status,
        current_chamber_positive_degree_decomposition,
        flipped_chamber_positive_degree_status,
        flipped_chamber_positive_degree_decomposition,
        positive_degree_transport_status,
    ) = if context.is_some() {
        let (current_status, current_decomposition) =
            positive_degree_chamber_status_and_decomposition(
                target,
                &current_generators,
                &current_chamber_generator_context,
            );
        let (flipped_status, flipped_decomposition) =
            positive_degree_chamber_status_and_decomposition(
                target,
                &flipped_generators,
                &flipped_chamber_generator_context,
            );
        let transport_status = positive_degree_transport_status(&current_status, &flipped_status);
        (
            current_status,
            current_decomposition,
            flipped_status,
            flipped_decomposition,
            transport_status,
        )
    } else {
        (
            "positive_degree_chamber_not_run_without_global_degree_context".to_string(),
            None,
            "positive_degree_chamber_not_run_without_global_degree_context".to_string(),
            None,
            "positive_degree_transport_not_run_without_global_degree_context".to_string(),
        )
    };

    LocalCygvStarUnionChamberSemigroupTransportProbe {
        status: status.to_string(),
        target_plus_star_coordinates: Some(target.to_vec()),
        current_chamber_generator_count: Some(current_generators.len()),
        current_chamber_generators: current_generators,
        current_chamber_generator_context,
        current_chamber_generator_known_qn_history_status_counts,
        current_chamber_provided_generator_cygv_probe,
        current_chamber_decomposition: current_decomposition,
        current_chamber_positive_degree_status,
        current_chamber_positive_degree_decomposition,
        flipped_chamber_status: flipped_status,
        flipped_chamber_generator_count: (!flipped_generators.is_empty())
            .then_some(flipped_generators.len()),
        flipped_chamber_generators: flipped_generators,
        flipped_chamber_generator_context,
        flipped_chamber_generator_known_qn_history_status_counts,
        flipped_chamber_provided_generator_cygv_probe,
        flipped_chamber_decomposition: flipped_decomposition,
        flipped_chamber_positive_degree_status,
        flipped_chamber_positive_degree_decomposition,
        positive_degree_transport_status,
        error: None,
    }
}

fn local_cygv_star_union_chamber_generators_in_charge_basis(
    point_samples: &[OriginCircuitRelationPointSample],
    point_indices: &[usize],
    charge_basis: &[Vec<i64>],
    global_simplices: &[Vec<usize>],
) -> Result<Vec<Vec<i64>>, String> {
    if point_indices.is_empty() {
        return Err("star-union chamber semigroup has no point indices".to_string());
    }
    if charge_basis.is_empty() {
        return Err("star-union chamber semigroup has no charge basis".to_string());
    }
    if charge_basis
        .iter()
        .any(|row| row.len() != point_indices.len())
    {
        return Err("star-union chamber semigroup charge-basis width mismatch".to_string());
    }
    let by_point = point_samples
        .iter()
        .map(|sample| (sample.point_index, sample))
        .collect::<BTreeMap<_, _>>();
    let points = point_indices
        .iter()
        .map(|point_index| {
            by_point
                .get(point_index)
                .map(|sample| Point::new(sample.coordinates.clone()))
                .ok_or_else(|| {
                    format!("star-union chamber point {point_index} has no coordinate sample")
                })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let local_index_by_global = point_indices
        .iter()
        .copied()
        .enumerate()
        .map(|(local, global)| (global, local))
        .collect::<BTreeMap<_, _>>();
    let local_simplices = global_simplices
        .iter()
        .map(|simplex| {
            simplex
                .iter()
                .map(|point| {
                    local_index_by_global.get(point).copied().ok_or_else(|| {
                        format!("star-union chamber simplex contains point {point} outside support")
                    })
                })
                .collect::<Result<Vec<_>, _>>()
        })
        .collect::<Result<Vec<_>, _>>()?;
    let triangulation = Triangulation::new(local_simplices);
    let hyperplanes = secondary_cone_hyperplanes_native(&points, &triangulation)
        .map_err(|error| error.to_string())?;
    let mut generators = BTreeSet::new();
    for hyperplane in hyperplanes {
        let Some(coordinates) =
            relation_coordinates_in_local_charge_basis(&hyperplane, charge_basis)?
        else {
            return Err(format!(
                "star-union chamber circuit {hyperplane:?} is not in charge basis"
            ));
        };
        generators.insert(primitive_i64_ray_direction(
            &coordinates,
            "star-union chamber circuit coordinate",
        )?);
    }
    Ok(generators.into_iter().collect())
}

fn chamber_semigroup_generator_contexts(
    point_indices: &[usize],
    point_samples: &[OriginCircuitRelationPointSample],
    charge_basis: &[Vec<i64>],
    generators: &[Vec<i64>],
    context: &ValidatedContext<'_>,
) -> Vec<LocalCygvChamberSemigroupGeneratorContext> {
    generators
        .iter()
        .enumerate()
        .map(|(generator_index, generator)| {
            chamber_semigroup_generator_context(
                generator_index,
                generator,
                point_indices,
                point_samples,
                charge_basis,
                context,
            )
        })
        .collect()
}

fn chamber_semigroup_generator_context(
    generator_index: usize,
    generator: &[i64],
    point_indices: &[usize],
    point_samples: &[OriginCircuitRelationPointSample],
    charge_basis: &[Vec<i64>],
    context: &ValidatedContext<'_>,
) -> LocalCygvChamberSemigroupGeneratorContext {
    let empty = |point_relation_status: &str,
                 point_relation_nonzero: Option<Vec<(usize, i64)>>,
                 global_basis_status: &str,
                 known_qn_history_status: &str,
                 error: Option<String>|
     -> LocalCygvChamberSemigroupGeneratorContext {
        let degree_bounded_support_overlap_diagnostic =
            point_relation_nonzero.as_deref().map_or_else(
                || {
                    chamber_generator_support_overlap_diagnostic_not_run(
                        "point_relation_unavailable",
                    )
                },
                |point_relation_nonzero| {
                    chamber_generator_degree_bounded_support_overlap_diagnostic(
                        point_relation_nonzero,
                        None,
                        context,
                        CHAMBER_GENERATOR_SUPPORT_OVERLAP_SAMPLE_LIMIT,
                    )
                },
            );
        LocalCygvChamberSemigroupGeneratorContext {
            generator_index,
            chamber_coordinate: generator.to_vec(),
            point_relation_status: point_relation_status.to_string(),
            point_relation_nonzero,
            global_basis_status: global_basis_status.to_string(),
            basis_nonzero: None,
            degree: None,
            known_qn_history_status: known_qn_history_status.to_string(),
            toric_gv: None,
            source_derived_gv: None,
            source_class_status: None,
            source_ray_ambient_nonzero: None,
            local_toric_diagnostic: chamber_generator_local_toric_diagnostic_not_run(
                "point_relation_unavailable",
            ),
            degree_bounded_support_overlap_diagnostic,
            lower_seed_sum_decomposition: None,
            bounded_lower_seed_decomposition: None,
            lower_seed_decomposition_error: None,
            error,
        }
    };

    let point_relation =
        match chamber_semigroup_generator_point_relation(point_indices, charge_basis, generator) {
            Ok(point_relation) => point_relation,
            Err(error) => {
                return empty(
                    "chamber_generator_point_relation_error",
                    None,
                    "chamber_generator_global_basis_projection_not_run",
                    "invalid_chamber_generator_point_relation",
                    Some(error),
                );
            }
        };
    let point_relation_nonzero = point_indices
        .iter()
        .copied()
        .zip(point_relation.iter().copied())
        .filter(|(_, coefficient)| *coefficient != 0)
        .collect::<Vec<_>>();
    if point_relation_nonzero.is_empty() {
        return LocalCygvChamberSemigroupGeneratorContext {
            generator_index,
            chamber_coordinate: generator.to_vec(),
            point_relation_status: "chamber_generator_point_relation_zero".to_string(),
            point_relation_nonzero: Some(point_relation_nonzero),
            global_basis_status: "chamber_generator_global_basis_projection_zero".to_string(),
            basis_nonzero: Some(Vec::new()),
            degree: Some(0),
            known_qn_history_status: "zero_chamber_generator".to_string(),
            toric_gv: None,
            source_derived_gv: None,
            source_class_status: None,
            source_ray_ambient_nonzero: None,
            local_toric_diagnostic: chamber_generator_local_toric_diagnostic_not_run(
                "zero_point_relation",
            ),
            degree_bounded_support_overlap_diagnostic:
                chamber_generator_support_overlap_diagnostic_not_run("zero_point_relation"),
            lower_seed_sum_decomposition: None,
            bounded_lower_seed_decomposition: None,
            lower_seed_decomposition_error: None,
            error: None,
        };
    }

    let basis_dense = match project_star_union_relation_to_global_basis(
        point_indices,
        &point_relation,
        context.q_matrix,
    ) {
        Ok(Some(basis_dense)) => basis_dense,
        Ok(None) => {
            return empty(
                "chamber_generator_point_relation_reconstructed",
                Some(point_relation_nonzero),
                "chamber_generator_global_basis_projection_no_integral_basis_coordinates",
                "chamber_generator_not_in_global_basis",
                None,
            );
        }
        Err(error) => {
            return empty(
                "chamber_generator_point_relation_reconstructed",
                Some(point_relation_nonzero),
                "chamber_generator_global_basis_projection_error",
                "invalid_chamber_generator_global_basis_projection",
                Some(error),
            );
        }
    };
    let basis_nonzero = sparse_from_dense(&basis_dense);
    let degree = match curve_degree(&basis_dense, context.grading) {
        Ok(degree) => degree,
        Err(error) => {
            let local_toric_diagnostic =
                chamber_generator_local_toric_diagnostic(&point_relation_nonzero, point_samples);
            let degree_bounded_support_overlap_diagnostic =
                chamber_generator_degree_bounded_support_overlap_diagnostic(
                    &point_relation_nonzero,
                    None,
                    context,
                    CHAMBER_GENERATOR_SUPPORT_OVERLAP_SAMPLE_LIMIT,
                );
            return LocalCygvChamberSemigroupGeneratorContext {
                generator_index,
                chamber_coordinate: generator.to_vec(),
                point_relation_status: "chamber_generator_point_relation_reconstructed".to_string(),
                point_relation_nonzero: Some(point_relation_nonzero),
                global_basis_status: "chamber_generator_global_basis_projection_integral"
                    .to_string(),
                basis_nonzero: Some(basis_nonzero),
                degree: None,
                known_qn_history_status: "invalid_chamber_generator_global_basis_degree"
                    .to_string(),
                toric_gv: None,
                source_derived_gv: None,
                source_class_status: None,
                source_ray_ambient_nonzero: None,
                local_toric_diagnostic,
                degree_bounded_support_overlap_diagnostic,
                lower_seed_sum_decomposition: None,
                bounded_lower_seed_decomposition: None,
                lower_seed_decomposition_error: None,
                error: Some(error),
            };
        }
    };
    let (known_qn_history_status, toric_gv, source_derived_gv, error) =
        global_basis_known_qn_history(&basis_dense, context);
    let (source_class_status, source_ray_ambient_nonzero) =
        global_basis_source_class_lookup(&basis_dense, context);
    let (
        lower_seed_sum_decomposition,
        bounded_lower_seed_decomposition,
        lower_seed_decomposition_error,
    ) = star_union_lower_seed_diagnostics(&basis_dense, degree, context, true);
    let local_toric_diagnostic =
        chamber_generator_local_toric_diagnostic(&point_relation_nonzero, point_samples);
    let degree_bounded_support_overlap_diagnostic =
        chamber_generator_degree_bounded_support_overlap_diagnostic(
            &point_relation_nonzero,
            Some(degree),
            context,
            CHAMBER_GENERATOR_SUPPORT_OVERLAP_SAMPLE_LIMIT,
        );

    LocalCygvChamberSemigroupGeneratorContext {
        generator_index,
        chamber_coordinate: generator.to_vec(),
        point_relation_status: "chamber_generator_point_relation_reconstructed".to_string(),
        point_relation_nonzero: Some(point_relation_nonzero),
        global_basis_status: "chamber_generator_global_basis_projection_integral".to_string(),
        basis_nonzero: Some(basis_nonzero),
        degree: Some(degree),
        known_qn_history_status,
        toric_gv,
        source_derived_gv,
        source_class_status,
        source_ray_ambient_nonzero,
        local_toric_diagnostic,
        degree_bounded_support_overlap_diagnostic,
        lower_seed_sum_decomposition,
        bounded_lower_seed_decomposition,
        lower_seed_decomposition_error,
        error,
    }
}

fn chamber_semigroup_generator_point_relation(
    point_indices: &[usize],
    charge_basis: &[Vec<i64>],
    generator: &[i64],
) -> Result<Vec<i64>, String> {
    if generator.len() != charge_basis.len() {
        return Err(format!(
            "chamber generator dimension {} does not match charge-basis row count {}",
            generator.len(),
            charge_basis.len()
        ));
    }
    if charge_basis
        .iter()
        .any(|row| row.len() != point_indices.len())
    {
        return Err("chamber generator charge-basis width mismatch".to_string());
    }
    let mut relation = vec![0i64; point_indices.len()];
    for col in 0..point_indices.len() {
        let mut coefficient = 0i128;
        for (&coordinate, row) in generator.iter().zip(charge_basis.iter()) {
            let product = i128::from(coordinate)
                .checked_mul(i128::from(row[col]))
                .ok_or_else(|| {
                    "chamber generator point-relation product overflows i128".to_string()
                })?;
            coefficient = coefficient.checked_add(product).ok_or_else(|| {
                "chamber generator point-relation coefficient overflows i128".to_string()
            })?;
        }
        relation[col] = i64::try_from(coefficient).map_err(|_| {
            "chamber generator point-relation coefficient does not fit in i64".to_string()
        })?;
    }
    Ok(relation)
}

