fn lower_seed_predecessor_bounded_candidate_side_status(
    known_qn_history_status: &str,
    curve_nonzero: &[(usize, i64)],
    summary_by_curve: &BTreeMap<Vec<(usize, i64)>, &CygvLowerSeedUnknownCandidateSummary>,
) -> String {
    if known_qn_history_status != "unknown_not_toric_covered" {
        return known_qn_history_status.to_string();
    }
    let Some(summary) = summary_by_curve.get(curve_nonzero) else {
        return "unknown_missing_lower_seed_candidate_summary".to_string();
    };
    lower_seed_unknown_bounded_candidate_status_label(summary)
}

fn lower_seed_unknown_bounded_candidate_status_label(
    summary: &CygvLowerSeedUnknownCandidateSummary,
) -> String {
    let counts = &summary.bounded_seed_decomposition_diamond_candidate_status_counts;
    if counts.is_empty() {
        return "unknown_missing_bounded_diamond_candidate_status".to_string();
    }
    if counts.len() == 1 {
        let status = counts.keys().next().expect("single status exists");
        return format!("bounded_{status}");
    }
    let fragments = counts
        .iter()
        .map(|(status, count)| format!("{status}_{count}"))
        .collect::<Vec<_>>()
        .join("__");
    format!("bounded_mixed_{fragments}")
}

fn cygv_lower_seed_unknown_candidate_summaries<'a>(
    probes: impl IntoIterator<Item = (usize, &'a CygvPathHistoryProbe)>,
    run_bounded_seed_diamonds: bool,
    context: &ValidatedContext<'_>,
) -> Vec<CygvLowerSeedUnknownCandidateSummary> {
    let mut summaries: BTreeMap<Vec<(usize, i64)>, CygvLowerSeedUnknownCandidateSummaryBuilder> =
        BTreeMap::new();
    for (target_index, probe) in probes {
        let bounded_seed_set = target_degree_bounded_seed_set(target_index, context);
        for (candidate_index, candidate) in probe
            .lower_seed_predecessor_candidate_sample
            .iter()
            .enumerate()
        {
            add_lower_seed_unknown_candidate_side(
                &mut summaries,
                target_index,
                candidate_index,
                "predecessor",
                candidate.predecessor_degree,
                &candidate.predecessor_known_qn_history_status,
                &candidate.predecessor_nonzero,
                candidate.difference_degree,
                &candidate.difference_known_qn_history_status,
                candidate.difference_toric_gv.clone(),
                candidate.difference_source_derived_gv.clone(),
                &candidate.difference_nonzero,
                candidate.predecessor_first_generation_seed_sum.clone(),
                &bounded_seed_set,
                run_bounded_seed_diamonds,
                context,
            );
            add_lower_seed_unknown_candidate_side(
                &mut summaries,
                target_index,
                candidate_index,
                "difference",
                candidate.difference_degree,
                &candidate.difference_known_qn_history_status,
                &candidate.difference_nonzero,
                candidate.predecessor_degree,
                &candidate.predecessor_known_qn_history_status,
                candidate.predecessor_toric_gv.clone(),
                candidate.predecessor_source_derived_gv.clone(),
                &candidate.predecessor_nonzero,
                candidate.difference_first_generation_seed_sum.clone(),
                &bounded_seed_set,
                run_bounded_seed_diamonds,
                context,
            );
        }
    }
    let mut out = summaries
        .into_values()
        .map(|builder| CygvLowerSeedUnknownCandidateSummary {
            degree: builder.degree,
            occurrence_count: builder.occurrences.len(),
            source_class_status_counts: builder.source_class_status_counts,
            counterpart_degree_counts: builder.counterpart_degree_counts,
            counterpart_known_qn_history_status_counts: builder
                .counterpart_known_qn_history_status_counts,
            first_generation_seed_sum_status_counts: builder
                .first_generation_seed_sum_status_counts,
            bounded_seed_decomposition_status_counts: builder
                .bounded_seed_decomposition_status_counts,
            bounded_seed_decomposition_term_degree_counts: builder
                .bounded_seed_decomposition_term_degree_counts,
            bounded_seed_decomposition_term_known_qn_history_status_counts: builder
                .bounded_seed_decomposition_term_known_qn_history_status_counts,
            bounded_seed_decomposition_diamond_candidate_status_counts: builder
                .bounded_seed_decomposition_diamond_candidate_status_counts,
            source_ray_ambient_nonzero: builder.source_ray_ambient_nonzero,
            matching_missing_target_index: builder.matching_missing_target_index,
            matching_missing_target_degree: builder.matching_missing_target_degree,
            matching_missing_target_origin_circuit_pattern: builder
                .matching_missing_target_origin_circuit_pattern,
            matching_missing_target_exact_kind: builder.matching_missing_target_exact_kind,
            matching_uncovered_source_ray_index: builder.matching_uncovered_source_ray_index,
            matching_uncovered_source_ray_degree: builder.matching_uncovered_source_ray_degree,
            matching_uncovered_source_ray_origin_circuit_pattern: builder
                .matching_uncovered_source_ray_origin_circuit_pattern,
            matching_uncovered_source_ray_exact_kind: builder
                .matching_uncovered_source_ray_exact_kind,
            matching_uncovered_source_ray_cms_check_status_counts: builder
                .matching_uncovered_source_ray_cms_check_status_counts,
            matching_uncovered_source_ray_cms_solution_summaries: builder
                .matching_uncovered_source_ray_cms_solution_summaries,
            matching_uncovered_source_ray_local_charge_signature: builder
                .matching_uncovered_source_ray_local_charge_signature,
            matching_uncovered_source_ray_local_cygv_readiness_counts: builder
                .matching_uncovered_source_ray_local_cygv_readiness_counts,
            matching_uncovered_source_ray_local_missing_input_counts: builder
                .matching_uncovered_source_ray_local_missing_input_counts,
            curve_nonzero: builder.curve_nonzero,
            occurrences: builder.occurrences,
        })
        .collect::<Vec<_>>();
    out.sort_by(|lhs, rhs| {
        lhs.degree
            .cmp(&rhs.degree)
            .then_with(|| lhs.curve_nonzero.cmp(&rhs.curve_nonzero))
    });
    out
}

fn target_degree_bounded_seed_set(
    target_index: usize,
    context: &ValidatedContext<'_>,
) -> Result<HashSet<Vec<i64>>, String> {
    let sample = context
        .stats
        .sample
        .get(target_index)
        .ok_or_else(|| format!("target sample index {target_index} is out of bounds"))?;
    let mut seed_set = HashSet::new();
    for ray in context.degree_bounded_rays {
        let degree = curve_degree(ray, context.grading)?;
        if degree > 0 && degree <= sample.degree {
            seed_set.insert(ray.clone());
        }
    }
    Ok(seed_set)
}

#[allow(clippy::too_many_arguments)]
fn add_lower_seed_unknown_candidate_side(
    summaries: &mut BTreeMap<Vec<(usize, i64)>, CygvLowerSeedUnknownCandidateSummaryBuilder>,
    target_index: usize,
    candidate_index: usize,
    side: &str,
    degree: i128,
    known_qn_history_status: &str,
    curve_nonzero: &[(usize, i64)],
    counterpart_degree: i128,
    counterpart_known_qn_history_status: &str,
    counterpart_toric_gv: Option<String>,
    counterpart_source_derived_gv: Option<String>,
    counterpart_nonzero: &[(usize, i64)],
    first_generation_seed_sum: Option<CygvSeedSumDecomposition>,
    bounded_seed_set: &Result<HashSet<Vec<i64>>, String>,
    run_bounded_seed_diamonds: bool,
    context: &ValidatedContext<'_>,
) {
    if known_qn_history_status != "unknown_not_toric_covered" {
        return;
    }
    let source_context = dense_from_sparse(curve_nonzero, context.dimension)
        .ok()
        .and_then(|curve| path_support_source_class_context(&curve, context).ok());
    let source_class_status = source_context.as_ref().map_or_else(
        || "source_context_lookup_error".to_string(),
        |source_context| source_context.status.clone(),
    );
    let entry = summaries.entry(curve_nonzero.to_vec()).or_insert_with(|| {
        CygvLowerSeedUnknownCandidateSummaryBuilder {
            degree,
            source_class_status_counts: BTreeMap::new(),
            counterpart_degree_counts: BTreeMap::new(),
            counterpart_known_qn_history_status_counts: BTreeMap::new(),
            first_generation_seed_sum_status_counts: BTreeMap::new(),
            bounded_seed_decomposition_status_counts: BTreeMap::new(),
            bounded_seed_decomposition_term_degree_counts: BTreeMap::new(),
            bounded_seed_decomposition_term_known_qn_history_status_counts: BTreeMap::new(),
            bounded_seed_decomposition_diamond_candidate_status_counts: BTreeMap::new(),
            source_ray_ambient_nonzero: source_context
                .as_ref()
                .and_then(|source_context| source_context.source_ray_ambient_nonzero.clone()),
            matching_missing_target_index: source_context
                .as_ref()
                .and_then(|source_context| source_context.matching_missing_target_index),
            matching_missing_target_degree: source_context
                .as_ref()
                .and_then(|source_context| source_context.matching_missing_target_degree),
            matching_missing_target_origin_circuit_pattern: source_context.as_ref().and_then(
                |source_context| {
                    source_context
                        .matching_missing_target_origin_circuit_pattern
                        .clone()
                },
            ),
            matching_missing_target_exact_kind: source_context.as_ref().and_then(
                |source_context| source_context.matching_missing_target_exact_kind.clone(),
            ),
            matching_uncovered_source_ray_index: source_context
                .as_ref()
                .and_then(|source_context| source_context.matching_uncovered_source_ray_index),
            matching_uncovered_source_ray_degree: source_context
                .as_ref()
                .and_then(|source_context| source_context.matching_uncovered_source_ray_degree),
            matching_uncovered_source_ray_origin_circuit_pattern: source_context.as_ref().and_then(
                |source_context| {
                    source_context
                        .matching_uncovered_source_ray_origin_circuit_pattern
                        .clone()
                },
            ),
            matching_uncovered_source_ray_exact_kind: source_context.as_ref().and_then(
                |source_context| {
                    source_context
                        .matching_uncovered_source_ray_exact_kind
                        .clone()
                },
            ),
            matching_uncovered_source_ray_cms_check_status_counts: source_context
                .as_ref()
                .map(|source_context| {
                    source_context
                        .matching_uncovered_source_ray_cms_check_status_counts
                        .clone()
                })
                .unwrap_or_default(),
            matching_uncovered_source_ray_cms_solution_summaries: source_context
                .as_ref()
                .map(|source_context| {
                    source_context
                        .matching_uncovered_source_ray_cms_solution_summaries
                        .clone()
                })
                .unwrap_or_default(),
            matching_uncovered_source_ray_local_charge_signature: source_context.as_ref().and_then(
                |source_context| {
                    source_context
                        .matching_uncovered_source_ray_local_charge_signature
                        .clone()
                },
            ),
            matching_uncovered_source_ray_local_cygv_readiness_counts: BTreeMap::new(),
            matching_uncovered_source_ray_local_missing_input_counts: BTreeMap::new(),
            curve_nonzero: curve_nonzero.to_vec(),
            occurrences: Vec::new(),
        }
    });
    debug_assert_eq!(entry.degree, degree);
    *entry
        .source_class_status_counts
        .entry(source_class_status)
        .or_insert(0) += 1;
    *entry
        .counterpart_degree_counts
        .entry(counterpart_degree)
        .or_insert(0) += 1;
    *entry
        .counterpart_known_qn_history_status_counts
        .entry(counterpart_known_qn_history_status.to_string())
        .or_insert(0) += 1;
    *entry
        .first_generation_seed_sum_status_counts
        .entry(lower_seed_unknown_first_generation_seed_sum_status(
            first_generation_seed_sum.as_ref(),
        ))
        .or_insert(0) += 1;
    let (bounded_seed_decomposition, bounded_seed_decomposition_error) = match bounded_seed_set {
        Ok(seed_set) => {
            match dense_from_sparse(curve_nonzero, context.dimension).and_then(|curve| {
                bounded_seed_decomposition_summary(
                    &curve,
                    seed_set,
                    4,
                    run_bounded_seed_diamonds.then_some(context),
                )
            }) {
                Ok(summary) => (Some(summary), None),
                Err(error) => (None, Some(error)),
            }
        }
        Err(error) => (None, Some(error.clone())),
    };
    *entry
        .bounded_seed_decomposition_status_counts
        .entry(lower_seed_unknown_bounded_seed_decomposition_status(
            bounded_seed_decomposition.as_ref(),
            bounded_seed_decomposition_error.as_deref(),
        ))
        .or_insert(0) += 1;
    let bounded_seed_decomposition_diamond_candidate_status =
        lower_seed_unknown_bounded_seed_diamond_candidate_status(
            bounded_seed_decomposition.as_ref(),
        );
    *entry
        .bounded_seed_decomposition_diamond_candidate_status_counts
        .entry(bounded_seed_decomposition_diamond_candidate_status.clone())
        .or_insert(0) += 1;
    let (bounded_seed_decomposition_terms, bounded_seed_decomposition_term_error) =
        lower_seed_unknown_bounded_seed_decomposition_terms(
            bounded_seed_decomposition.as_ref(),
            context,
        );
    if let Some(error) = bounded_seed_decomposition_term_error.as_deref() {
        *entry
            .bounded_seed_decomposition_term_known_qn_history_status_counts
            .entry(format!("error_{}", status_error_fragment(error)))
            .or_insert(0) += 1;
    }
    for term in &bounded_seed_decomposition_terms {
        *entry
            .bounded_seed_decomposition_term_degree_counts
            .entry(term.degree)
            .or_insert(0) += 1;
        *entry
            .bounded_seed_decomposition_term_known_qn_history_status_counts
            .entry(term.known_qn_history_status.clone())
            .or_insert(0) += 1;
    }
    if let Some(source_context) = source_context.as_ref() {
        if let Some(readiness) = &source_context.matching_uncovered_source_ray_local_cygv_readiness
        {
            *entry
                .matching_uncovered_source_ray_local_cygv_readiness_counts
                .entry(readiness.clone())
                .or_insert(0) += 1;
        }
        for input in &source_context.matching_uncovered_source_ray_local_missing_inputs {
            *entry
                .matching_uncovered_source_ray_local_missing_input_counts
                .entry(input.clone())
                .or_insert(0) += 1;
        }
    }
    entry
        .matching_uncovered_source_ray_cms_solution_summaries
        .sort();
    entry
        .matching_uncovered_source_ray_cms_solution_summaries
        .dedup();
    entry
        .occurrences
        .push(CygvLowerSeedUnknownCandidateOccurrence {
            target_index,
            candidate_index,
            side: side.to_string(),
            counterpart_degree,
            counterpart_known_qn_history_status: counterpart_known_qn_history_status.to_string(),
            counterpart_toric_gv,
            counterpart_source_derived_gv,
            counterpart_nonzero: counterpart_nonzero.to_vec(),
            first_generation_seed_sum,
            bounded_seed_decomposition,
            bounded_seed_decomposition_error,
            bounded_seed_decomposition_terms,
            bounded_seed_decomposition_term_error,
            bounded_seed_decomposition_diamond_candidate_status,
        });
}

fn lower_seed_unknown_first_generation_seed_sum_status(
    seed_sum: Option<&CygvSeedSumDecomposition>,
) -> String {
    seed_sum.map_or_else(
        || "missing_first_generation_seed_sum".to_string(),
        |seed_sum| {
            format!(
                "reduced_seed_{}__seed_{}",
                seed_sum.reduced_seed_known_qn_history_status,
                seed_sum.seed_known_qn_history_status
            )
        },
    )
}

fn lower_seed_unknown_bounded_seed_decomposition_status(
    decomposition: Option<&CygvBoundedSeedDecompositionSummary>,
    error: Option<&str>,
) -> String {
    decomposition.map_or_else(
        || {
            format!(
                "error_{}",
                status_error_fragment(error.unwrap_or("missing_bounded_seed_decomposition_error"))
            )
        },
        |decomposition| decomposition.status.clone(),
    )
}

fn lower_seed_unknown_bounded_seed_diamond_candidate_status(
    decomposition: Option<&CygvBoundedSeedDecompositionSummary>,
) -> String {
    let Some(decomposition) = decomposition else {
        return "missing_bounded_seed_decomposition".to_string();
    };
    if decomposition.status != "found_lower_seed_decomposition" {
        return decomposition.status.clone();
    }
    bounded_diamond_candidate_status(
        decomposition.diamond_status.as_deref(),
        decomposition.diamond_gv.as_deref(),
        decomposition.diamond_gw_noninteger_candidate_count,
        decomposition.diamond_target_qn_trace_status.as_deref(),
    )
}

fn bounded_diamond_candidate_status(
    diamond_status: Option<&str>,
    diamond_gv: Option<&str>,
    diamond_gw_noninteger_candidate_count: Option<usize>,
    diamond_target_qn_trace_status: Option<&str>,
) -> String {
    let Some(diamond_status) = diamond_status else {
        return "diamond_not_run".to_string();
    };
    if diamond_status != "computed_bounded_decomposition_diamond_qn_trace" {
        return format!("diamond_{diamond_status}");
    }
    if diamond_gw_noninteger_candidate_count.is_some_and(|count| count > 0) {
        return "blocked_noninteger_gw_candidates".to_string();
    }
    let Some(gv) = diamond_gv else {
        return "missing_diamond_gv".to_string();
    };
    let parsed_gv = match parse_rational(gv) {
        Ok(value) => value,
        Err(error) => return format!("error_{}", status_error_fragment(&error)),
    };
    if parsed_gv.denominator_ref() != &1u32 {
        return "blocked_noninteger_diamond_gv".to_string();
    }
    if parsed_gv == MalachiteRational::from(0) {
        return "integer_zero_or_absent_gv".to_string();
    }
    match diamond_target_qn_trace_status {
        Some("path_support_qn_materialized_for_nonzero_gv") => "integer_nonzero_gv".to_string(),
        Some(status) => format!("integer_nonzero_gv_with_{status}"),
        None => "integer_nonzero_gv_missing_qn_trace_status".to_string(),
    }
}

fn lower_seed_unknown_bounded_seed_decomposition_terms(
    decomposition: Option<&CygvBoundedSeedDecompositionSummary>,
    context: &ValidatedContext<'_>,
) -> (Vec<CygvBoundedSeedDecompositionTermSummary>, Option<String>) {
    let Some(terms_nonzero) = decomposition
        .and_then(|decomposition| decomposition.terms_nonzero.as_ref().map(Vec::as_slice))
    else {
        return (Vec::new(), None);
    };
    let mut out = Vec::with_capacity(terms_nonzero.len());
    for term_nonzero in terms_nonzero {
        let curve = match dense_from_sparse(term_nonzero, context.dimension) {
            Ok(curve) => curve,
            Err(error) => return (Vec::new(), Some(error)),
        };
        let degree = match curve_degree(&curve, context.grading) {
            Ok(degree) => degree,
            Err(error) => return (Vec::new(), Some(error)),
        };
        let toric_gv = context.covered_toric_gv_by_basis.get(&curve).cloned();
        let source_derived_gv = context.source_derived_gv_by_basis.get(&curve).cloned();
        let known_qn_history_status =
            match known_qn_history_status(toric_gv.as_deref(), source_derived_gv.as_deref()) {
                Ok(status) => status.to_string(),
                Err(error) => return (Vec::new(), Some(error)),
            };
        out.push(CygvBoundedSeedDecompositionTermSummary {
            degree,
            toric_gv,
            source_derived_gv,
            known_qn_history_status,
            curve_nonzero: term_nonzero.clone(),
        });
    }
    (out, None)
}

