fn path_support_pre_subtraction_formula_status(
    pre_subtraction_candidate: Option<&String>,
    expected_values: &[String],
    expected_sum: Option<&String>,
) -> Result<String, String> {
    let Some(pre_subtraction_candidate) = pre_subtraction_candidate else {
        return Ok("missing_pre_subtraction_candidate".to_string());
    };
    if expected_values.is_empty() {
        return Ok("missing_formula_candidate".to_string());
    }
    let candidate = parse_rational(pre_subtraction_candidate)?;
    for value in expected_values {
        if candidate == parse_rational(value)? {
            return Ok("pre_subtraction_candidate_matches_formula_candidate".to_string());
        }
    }
    if let Some(expected_sum) = expected_sum {
        if candidate == parse_rational(expected_sum)? {
            return Ok("pre_subtraction_candidate_matches_formula_sum".to_string());
        }
    }
    Ok("pre_subtraction_candidate_mismatches_formula_candidates".to_string())
}

fn candidate_pair_formula_sum_status(
    candidate: Option<&String>,
    expected_sum: Option<&String>,
    label: &str,
) -> Result<(String, Option<String>), String> {
    let Some(expected_sum) = expected_sum else {
        return Ok((format!("{label}_expected_formula_sum_missing"), None));
    };
    let Some(candidate) = candidate else {
        return Ok((format!("{label}_missing"), None));
    };
    let expected_sum = parse_rational(expected_sum)?;
    let candidate = parse_rational(candidate)?;
    let delta = expected_sum - candidate;
    let status = if delta == 0 {
        format!("{label}_matches_expected_formula_sum")
    } else {
        format!("{label}_mismatches_expected_formula_sum")
    };
    Ok((status, Some(delta.to_string())))
}

fn target_gw_formula_instanton_balance(
    target_instanton_coefficient: Option<&String>,
    target_pivot_component: Option<i32>,
    expected_sum: Option<&String>,
    label: &str,
) -> Result<CygvCandidatePairFormulaInstantonBalance, String> {
    let Some(expected_sum) = expected_sum else {
        return Ok(CygvCandidatePairFormulaInstantonBalance {
            required_instanton_coefficient: None,
            missing_instanton_coefficient: None,
            status: format!("{label}_expected_formula_sum_missing"),
        });
    };
    let Some(target_instanton_coefficient) = target_instanton_coefficient else {
        return Ok(CygvCandidatePairFormulaInstantonBalance {
            required_instanton_coefficient: None,
            missing_instanton_coefficient: None,
            status: format!("{label}_target_coefficient_missing"),
        });
    };
    let Some(target_pivot_component) = target_pivot_component else {
        return Ok(CygvCandidatePairFormulaInstantonBalance {
            required_instanton_coefficient: None,
            missing_instanton_coefficient: None,
            status: format!("{label}_target_pivot_missing"),
        });
    };
    if target_pivot_component == 0 {
        return Ok(CygvCandidatePairFormulaInstantonBalance {
            required_instanton_coefficient: None,
            missing_instanton_coefficient: None,
            status: format!("{label}_zero_target_pivot"),
        });
    }

    let expected_sum = parse_rational(expected_sum)?;
    let target_instanton_coefficient = parse_rational(target_instanton_coefficient)?;
    let required = expected_sum * MalachiteRational::from(Integer::from(target_pivot_component));
    let missing = required.clone() - target_instanton_coefficient;
    let status = if missing == 0 {
        format!("{label}_balanced")
    } else {
        format!("{label}_mismatch")
    };
    Ok(CygvCandidatePairFormulaInstantonBalance {
        required_instanton_coefficient: Some(required.to_string()),
        missing_instanton_coefficient: Some(missing.to_string()),
        status,
    })
}

fn candidate_pair_target_gw_formula_instanton_balance(
    target_instanton_coefficient: Option<&String>,
    target_pivot_component: Option<i32>,
    expected_sum: Option<&String>,
) -> Result<CygvCandidatePairFormulaInstantonBalance, String> {
    target_gw_formula_instanton_balance(
        target_instanton_coefficient,
        target_pivot_component,
        expected_sum,
        "candidate_pair_diamond_gw_formula_instanton",
    )
}

fn expected_toric_gv1_formula_values(
    candidates: Option<&[CmsGeneralDivisorShapeCandidate]>,
) -> Vec<String> {
    let mut values = candidates
        .unwrap_or_default()
        .iter()
        .filter_map(|candidate| candidate.toric_gv1_formula_value)
        .collect::<Vec<_>>();
    values.sort_unstable();
    values.dedup();
    values.into_iter().map(|value| value.to_string()).collect()
}

fn expected_toric_gv1_formula_value_sum(
    candidates: Option<&[CmsGeneralDivisorShapeCandidate]>,
) -> Option<String> {
    let mut found = false;
    let mut sum = 0i64;
    for value in candidates
        .unwrap_or_default()
        .iter()
        .filter_map(|candidate| candidate.toric_gv1_formula_value)
    {
        found = true;
        sum = sum.checked_add(value)?;
    }
    found.then(|| sum.to_string())
}

