    #[test]
    fn expected_formula_sum_preserves_candidate_multiplicity() {
        let candidates = vec![
            CmsGeneralDivisorShapeCandidate {
                shrinking_divisor_index: 1,
                shrinking_divisor_coefficient: -1,
                shrinking_divisor_coordinates: vec![0, 1],
                inferred_other_normal_degree: -1,
                toric_gv1_formula_value: Some(1),
                all_non_origin_relation_points_are_two_face: true,
            },
            CmsGeneralDivisorShapeCandidate {
                shrinking_divisor_index: 2,
                shrinking_divisor_coefficient: -2,
                shrinking_divisor_coordinates: vec![1, 0],
                inferred_other_normal_degree: 0,
                toric_gv1_formula_value: Some(-2),
                all_non_origin_relation_points_are_two_face: true,
            },
            CmsGeneralDivisorShapeCandidate {
                shrinking_divisor_index: 3,
                shrinking_divisor_coefficient: -1,
                shrinking_divisor_coordinates: vec![1, 1],
                inferred_other_normal_degree: -1,
                toric_gv1_formula_value: Some(1),
                all_non_origin_relation_points_are_two_face: true,
            },
        ];

        assert_eq!(
            expected_toric_gv1_formula_values(Some(&candidates)),
            vec!["-2".to_string(), "1".to_string()]
        );
        assert_eq!(
            expected_toric_gv1_formula_value_sum(Some(&candidates)).as_deref(),
            Some("0")
        );
    }

    #[test]
    fn candidate_pair_formula_sum_status_uses_exact_rationals() {
        let (status, delta) = candidate_pair_formula_sum_status(
            Some(&"2".to_string()),
            Some(&"2".to_string()),
            "candidate_pair_diamond_gv",
        )
        .unwrap();
        assert_eq!(
            status,
            "candidate_pair_diamond_gv_matches_expected_formula_sum"
        );
        assert_eq!(delta.as_deref(), Some("0"));

        let (status, delta) = candidate_pair_formula_sum_status(
            Some(&"3/2".to_string()),
            Some(&"2".to_string()),
            "candidate_pair_diamond_gw_candidate",
        )
        .unwrap();
        assert_eq!(
            status,
            "candidate_pair_diamond_gw_candidate_mismatches_expected_formula_sum"
        );
        assert_eq!(delta.as_deref(), Some("1/2"));

        let (status, delta) =
            candidate_pair_formula_sum_status(None, Some(&"2".to_string()), "candidate").unwrap();
        assert_eq!(status, "candidate_missing");
        assert_eq!(delta, None);
    }

    #[test]
    fn candidate_pair_formula_instanton_balance_reports_missing_coefficient() {
        let balance = candidate_pair_target_gw_formula_instanton_balance(
            Some(&"-6".to_string()),
            Some(-3),
            Some(&"3".to_string()),
        )
        .unwrap();

        assert_eq!(
            balance.status,
            "candidate_pair_diamond_gw_formula_instanton_mismatch"
        );
        assert_eq!(
            balance.required_instanton_coefficient.as_deref(),
            Some("-9")
        );
        assert_eq!(balance.missing_instanton_coefficient.as_deref(), Some("-3"));

        let balanced = candidate_pair_target_gw_formula_instanton_balance(
            Some(&"-9".to_string()),
            Some(-3),
            Some(&"3".to_string()),
        )
        .unwrap();
        assert_eq!(
            balanced.status,
            "candidate_pair_diamond_gw_formula_instanton_balanced"
        );
        assert_eq!(balanced.missing_instanton_coefficient.as_deref(), Some("0"));
    }

    #[test]
    fn local_cygv_integer_tensor_scan_status_counts_are_opt_in() {
        let scans = vec![
            LocalCygvIntegerTensorScanSummary {
                target_index: 0,
                degree: 10,
                status: "integer_tensor_scan_has_expected_match_but_uncertified".to_string(),
                formula_sum_status: "integer_tensor_scan_has_formula_sum_match_but_uncertified"
                    .to_string(),
                scan_bound: 8,
                expected_toric_gv1_formula_values: vec!["3".to_string()],
                expected_toric_gv1_formula_value_sum: Some("3".to_string()),
                entries: Vec::new(),
            },
            LocalCygvIntegerTensorScanSummary {
                target_index: 1,
                degree: 18,
                status: "integer_tensor_scan_no_expected_match".to_string(),
                formula_sum_status: "integer_tensor_scan_no_formula_sum_match".to_string(),
                scan_bound: 8,
                expected_toric_gv1_formula_values: vec!["-2".to_string(), "1".to_string()],
                expected_toric_gv1_formula_value_sum: Some("-1".to_string()),
                entries: Vec::new(),
            },
        ];

        let disabled = local_cygv_integer_tensor_scan_status_counts(&scans, 9, false);
        assert_eq!(disabled, BTreeMap::from([("not_run".to_string(), 9)]));

        let enabled = local_cygv_integer_tensor_scan_status_counts(&scans, 9, true);
        assert_eq!(
            enabled,
            BTreeMap::from([
                (
                    "integer_tensor_scan_has_expected_match_but_uncertified".to_string(),
                    1
                ),
                ("integer_tensor_scan_no_expected_match".to_string(), 1),
            ])
        );

        let disabled_sum =
            local_cygv_integer_tensor_formula_sum_scan_status_counts(&scans, 9, false);
        assert_eq!(disabled_sum, BTreeMap::from([("not_run".to_string(), 9)]));

        let enabled_sum = local_cygv_integer_tensor_formula_sum_scan_status_counts(&scans, 9, true);
        assert_eq!(
            enabled_sum,
            BTreeMap::from([
                (
                    "integer_tensor_scan_has_formula_sum_match_but_uncertified".to_string(),
                    1
                ),
                ("integer_tensor_scan_no_formula_sum_match".to_string(), 1),
            ])
        );
    }

