        assert_eq!(q_intersections(&[2, 1], &q_matrix).unwrap(), vec![1, -3, 3]);
        let negative_count = cygv_negative_intersection_count(&[2, 1], &q_matrix).unwrap();
        assert_eq!(negative_count, 1);
