    #[test]
    fn bounded_diamond_parent_qn_comparison_flags_domain_dependent_shape() {
        let trace = vec![CygvQnTracePolynomial {
            element_index: 3,
            degree: 2,
            element: vec![1, 0],
            terms: vec![
                CygvQnTraceTerm {
                    monomial_index: 3,
                    exponent: vec![1, 0],
                    coefficient: "1".to_string(),
                },
                CygvQnTraceTerm {
                    monomial_index: 4,
                    exponent: vec![2, 0],
                    coefficient: "-1".to_string(),
                },
            ],
            li2_terms: vec![CygvQnTraceTerm {
                monomial_index: 4,
                exponent: vec![2, 0],
                coefficient: "-1".to_string(),
            }],
        }];
        let sources =
            path_support_target_monomial_qn_sources(&trace, &HashMap::new(), &[2, 0], None)
                .expect("target monomial source should be traced");
        let bounded = CygvBoundedSeedDecompositionSummary {
            max_terms: 4,
            status: "found_lower_seed_decomposition".to_string(),
            term_count: Some(2),
            terms_nonzero: Some(vec![vec![(0, 1)], vec![(0, 1)]]),
            diamond_element_count: Some(3),
            diamond_status: Some("computed_bounded_decomposition_diamond_qn_trace".to_string()),
            diamond_gv: Some("5".to_string()),
            diamond_error: None,
            diamond_qn_trace_polynomial_count: Some(1),
            diamond_target_qn_trace_status: Some(
                "path_support_qn_materialized_for_nonzero_gv".to_string(),
            ),
            diamond_target_qn_trace_term_count: Some(1),
            diamond_qn_trace_sample: vec![CygvPathSupportQnTracePolynomialSample {
                element_index: 1,
                degree: 1,
                curve_nonzero: vec![(0, 1)],
                term_count: 1,
                term_sample_limit: CYGV_PATH_SUPPORT_QN_TRACE_TERM_SAMPLE_LIMIT,
                term_sample: vec![CygvPathSupportQnTraceTermSample {
                    monomial_index: 1,
                    exponent_nonzero: vec![(0, 1)],
                    coefficient: "1".to_string(),
                }],
            }],
            diamond_gw_coefficient_trace_count: None,
            diamond_gw_noninteger_candidate_count: None,
            diamond_gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
            diamond_gw_noninteger_source_class_status_counts: BTreeMap::new(),
            diamond_gw_noninteger_candidate_sample: Vec::new(),
            diamond_gw_coefficient_trace_error: None,
            diamond_target_gw_coefficient_status: None,
            diamond_target_gw_instanton_coefficient: None,
            diamond_target_gw_candidate: None,
        };

        let comparison = bounded_diamond_parent_qn_comparison(&sources[0], &bounded);
        assert_eq!(
            comparison.status.as_deref(),
            Some("different_qn_term_counts")
        );
        assert_eq!(
            comparison.parent_only_term_signature_sample,
            vec![CygvPathSupportQnTraceTermSignature {
                exponent_nonzero: vec![(0, 2)],
                coefficient: "-1".to_string(),
            }]
        );
        assert!(comparison.diamond_only_term_signature_sample.is_empty());

        assert_eq!(
            qn_term_signature_multiset_difference(
                &[
                    CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: vec![(0, 1)],
                        coefficient: "1".to_string(),
                    },
                    CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: vec![(0, 1)],
                        coefficient: "1".to_string(),
                    },
                ],
                &[CygvPathSupportQnTraceTermSignature {
                    exponent_nonzero: vec![(0, 1)],
                    coefficient: "1".to_string(),
                }],
                16,
            ),
            vec![CygvPathSupportQnTraceTermSignature {
                exponent_nonzero: vec![(0, 1)],
                coefficient: "1".to_string(),
            }]
        );
        assert_eq!(
            qn_term_signature_comparison_status(
                2,
                true,
                &[
                    CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: vec![(0, 1)],
                        coefficient: "1".to_string(),
                    },
                    CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: vec![(0, 2)],
                        coefficient: "-1".to_string(),
                    },
                ],
                Some(2),
                true,
                &[
                    CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: vec![(0, 2)],
                        coefficient: "-1".to_string(),
                    },
                    CygvPathSupportQnTraceTermSignature {
                        exponent_nonzero: vec![(0, 1)],
                        coefficient: "1".to_string(),
                    },
                ],
            ),
            "same_qn_term_signatures"
        );

        let stats = MissingGvTargetStats {
            target_count: 1,
            real_cone_decomposition_exact_kind_counts: HashMap::new(),
            sample: vec![minimal_missing_sample(vec![(0, 2)])],
        };
        let grading = vec![1];
        let q_matrix: Vec<Vec<i64>> = Vec::new();
        let degree_bounded_rays = vec![vec![2]];
        let context = ValidatedContext {
            dimension: 1,
            degree_bound: 2,
            q_cols: 0,
            grading: &grading,
            q_matrix: &q_matrix,
            degree_bounded_rays: &degree_bounded_rays,
            degree_bounded_ray_context: None,
            covered_toric_gv_by_basis: HashMap::from([
                (vec![1], "5".to_string()),
                (vec![2], "7".to_string()),
            ]),
            source_derived_gv_by_basis: HashMap::new(),
            intersection: Intersection::new(1),
            stats: &stats,
            uncovered_source_ray_stats: None,
            shared_facet_unresolved_source_ray_stats: None,
            secondary_cone_height_certificate: None,
            secondary_cone_2face_height_certificate: None,
            secondary_cone_heights: None,
        };
        let term_context = qn_term_signature_context_sample(
            &comparison.parent_only_term_signature_sample,
            &context,
            &HashSet::from([vec![2]]),
            &HashSet::new(),
            Some(&[1]),
        )
        .expect("parent-only qN term context should classify the extra monomial");
        assert_eq!(term_context.len(), 1);
        assert_eq!(term_context[0].degree, 2);
        assert_eq!(
            term_context[0].known_qn_history_status,
            "known_nonzero_toric_gv"
        );
        assert_eq!(
            term_context[0].source_class_status,
            "source_ray_context_missing_but_matches_missing_target"
        );
        assert_eq!(term_context[0].matching_missing_target_index, Some(0));
        assert!(term_context[0].source_is_seed);
        assert!(!term_context[0].source_is_reduced_seed);
        assert_eq!(
            term_context[0].offset_from_source_nonzero,
            Some(vec![(0, 1)])
        );
        assert_eq!(term_context[0].offset_from_source_degree, Some(1));
        assert_eq!(
            term_context[0].offset_from_source_toric_gv.as_deref(),
            Some("5")
        );
        assert_eq!(
            term_context[0]
                .offset_from_source_known_qn_history_status
                .as_deref(),
            Some("known_nonzero_toric_gv")
        );

        let mut compared_source = sources[0].clone();
        compared_source.source_bounded_diamond_parent_qn_comparison_status =
            Some("different_qn_term_counts".to_string());
        compared_source.source_bounded_diamond_parent_only_qn_term_context_sample =
            term_context.clone();
        compared_source.source_bounded_seed_decomposition =
            Some(CygvBoundedSeedDecompositionSummary {
                max_terms: 4,
                status: "found_lower_seed_decomposition".to_string(),
                term_count: Some(2),
                terms_nonzero: Some(vec![vec![(0, 1)], vec![(0, 1)]]),
                diamond_element_count: Some(3),
                diamond_status: Some("computed_bounded_decomposition_diamond_qn_trace".to_string()),
                diamond_gv: Some("5".to_string()),
                diamond_error: None,
                diamond_qn_trace_polynomial_count: Some(1),
                diamond_target_qn_trace_status: Some(
                    "path_support_qn_materialized_for_nonzero_gv".to_string(),
                ),
                diamond_target_qn_trace_term_count: Some(1),
                diamond_qn_trace_sample: Vec::new(),
                diamond_gw_coefficient_trace_count: None,
                diamond_gw_noninteger_candidate_count: None,
                diamond_gw_noninteger_known_qn_history_status_counts: BTreeMap::new(),
                diamond_gw_noninteger_source_class_status_counts: BTreeMap::new(),
                diamond_gw_noninteger_candidate_sample: Vec::new(),
                diamond_gw_coefficient_trace_error: None,
                diamond_target_gw_coefficient_status: None,
                diamond_target_gw_instanton_coefficient: None,
                diamond_target_gw_candidate: None,
            });
        let semigroup_probe = source_parent_qn_term_semigroup_probe(&compared_source, &context)
            .expect("qN-term semigroup probe should build a bounded diagnostic")
            .expect("mismatched source should request a qN-term semigroup probe");
        assert_eq!(semigroup_probe.element_count, Some(3));
        assert_eq!(semigroup_probe.status, "skipped_no_q_matrix");
        let seed_expanded_probe = source_parent_qn_term_seed_expanded_semigroup_probe(
            &compared_source,
            &context,
            &HashSet::from([vec![1]]),
        )
        .expect("seed-expanded qN-term semigroup probe should build a bounded diagnostic")
        .expect("mismatched source should request a seed-expanded qN-term semigroup probe");
        assert_eq!(seed_expanded_probe.element_count, Some(3));
        assert_eq!(seed_expanded_probe.status, "skipped_no_q_matrix");
        let (offset_generators, offset_max_degree) =
            source_qn_term_offset_generators(&compared_source, &context)
                .expect("offset generators should build from source decomposition plus offsets");
        assert_eq!(offset_generators, vec![vec![1]]);
        assert_eq!(offset_max_degree, 2);
        let offset_generator_probe = source_parent_qn_term_offset_generator_probe(
            &compared_source,
            &context,
            &SupportingMoriFaceLpSearchOptions::default(),
        )
        .expect("offset-generator probe should build a bounded diagnostic")
        .expect("mismatched source with known offset should request offset generators");
        assert_eq!(offset_generator_probe.generator_count, Some(1));
        assert_eq!(
            offset_generator_probe.generator_degree_counts,
            BTreeMap::from([(1, 1)])
        );
        assert_eq!(
            offset_generator_probe.generator_sample_limit,
            CYGV_PATH_SUPPORT_GENERATOR_SAMPLE_LIMIT
        );
        assert_eq!(
            offset_generator_probe.generator_nonzero_sample,
            vec![vec![(0, 1)]]
        );
        assert_eq!(offset_generator_probe.status, "skipped_no_q_matrix");
        assert_eq!(
            offset_generator_probe
                .generator_face_certificate_status
                .as_deref(),
            Some("offset_generators_full_dimensional_rank_1_dim_1")
        );
        assert_eq!(
            target_monomial_qn_source_diamond_parent_qn_comparison_status_counts(&[
                sources[0].clone(),
                compared_source,
            ]),
            BTreeMap::from([
                ("different_qn_term_counts".to_string(), 1),
                ("not_compared".to_string(), 1),
            ])
        );
    }

    #[test]
